        // ============= SELECTS TOLERANTES AL EDITAR =============
        // Si al editar un registro el valor guardado no figura entre las opciones del <select>
        // (datos importados, versiones anteriores, etc.), el campo quedaba vacío y el formulario
        // no se podía guardar o perdía el dato. Ahora la opción faltante se agrega automáticamente.
        (function () {
            const desc = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value');
            if (!desc || !desc.set) return;
            Object.defineProperty(HTMLSelectElement.prototype, 'value', {
                configurable: true,
                enumerable: desc.enumerable,
                get: desc.get,
                set: function (v) {
                    try {
                        if (this.form && !this.multiple && v !== null && v !== undefined && String(v) !== '' &&
                            !Array.from(this.options).some(o => o.value === String(v))) {
                            const o = document.createElement('option');
                            o.value = String(v);
                            o.textContent = String(v).replace(/_/g, ' ');
                            this.appendChild(o);
                        }
                    } catch (e) {}
                    desc.set.call(this, v);
                }
            });
        })();

        // ============= FOCO TRAS DIÁLOGOS NATIVOS (Electron/Windows) =============
        // Después de alert()/confirm() nativos la ventana puede quedar sin foco de teclado y los
        // campos de texto no dejan escribir hasta cambiar de ventana. Se devuelve el foco al cerrar el diálogo.
        (function () {
            if (window.__appDialogs) return; // con diálogos propios no hace falta
            if (!(window.prohsAPI && typeof window.prohsAPI.refocus === 'function')) return;
            const origAlert = window.alert.bind(window);
            const origConfirm = window.confirm.bind(window);
            const restore = () => {
                const el = document.activeElement;
                window.prohsAPI.refocus().catch(() => {});
                setTimeout(() => {
                    try { window.focus(); if (el && el !== document.body && el.focus) el.focus(); } catch (e) {}
                }, 40);
            };
            window.alert = function (msg) { const r = origAlert(msg); restore(); return r; };
            window.confirm = function (msg) { const r = origConfirm(msg); restore(); return r; };
        })();

        // ============= SIDEBAR TOGGLE =============
        function toggleSidebar() {
            const sidebar = document.getElementById('sidebar');
            const overlay = document.querySelector('.sidebar-overlay');
            const mainContent = document.getElementById('mainContent');
            
            sidebar.classList.toggle('open');
            overlay.classList.toggle('active');
            
            if (window.innerWidth > 1024) {
                sidebar.classList.toggle('closed');
                mainContent.classList.toggle('expanded');
            }
        }
        
        // Responsive handling
        window.addEventListener('resize', () => {
            const sidebar = document.getElementById('sidebar');
            const overlay = document.querySelector('.sidebar-overlay');
            
            if (window.innerWidth > 1024) {
                overlay.classList.remove('active');
                sidebar.classList.remove('open');
            }
        });
        
        // Ajustar sidebar en load
        window.addEventListener('load', () => {
            if (window.innerWidth <= 1024) {
                document.getElementById('sidebar').classList.add('closed');
            }
        });
        
