        function machineryTypeLabel(tipo) {
            if (!tipo) return 'Sin especificar';
            return MACHINERY_TYPE_LABELS[tipo] || (tipo.charAt(0).toUpperCase() + tipo.slice(1).replace(/_/g, ' '));
        }
        function vehicleTypeLabel(tipo) {
            if (!tipo) return 'N/A';
            return VEHICLE_TYPE_LABELS[tipo] || (tipo.charAt(0).toUpperCase() + tipo.slice(1).replace(/_/g, ' '));
        }

        // Fundamento normativo por tipo de permiso de trabajo (JSA), mostrado como
        // ayuda contextual en el formulario e incluido en el informe PDF consolidado.
        const JSA_PERMIT_INFO = {
            'Trabajo en Altura': 'Se considera trabajo en altura a partir de 2 m. Requiere andamios arriostrados, arnés con punto de anclaje verificado y protección de aberturas/perímetros con barandas. Dec. 911/96, Cap. 9.',
            'Trabajo en Caliente': 'Incluye soldadura, corte y esmerilado. Requiere control de atmósfera explosiva, retiro de materiales combustibles del entorno, extintor disponible y vigía de fuego durante y después de la tarea. Dec. 351/79, Cap. 18.',
            'Espacio Confinado': 'Recinto con acceso limitado y riesgo de atmósfera peligrosa (déficit de oxígeno, gases tóxicos o inflamables). Requiere Programa de Seguridad de Espacios Confinados, medición previa y continua de la atmósfera, y vigía en el exterior. Res. SRT 953/2010 - Norma IRAM 3625/2003.',
            'Trabajo Eléctrico': 'Requiere bloqueo y etiquetado (LOTO) de la fuente de energía, verificación de ausencia de tensión antes de intervenir y uso de EPP dieléctrico. Dec. 351/79, Cap. 14 - AEA 90364.',
            'Excavación': 'Requiere verificación previa de las condiciones del terreno por responsable habilitado, entibado o taludes según tipo de suelo, y señalización/vallado perimetral. Dec. 911/96, Cap. 8 (Excavaciones y Trabajos Subterráneos).',
            'General': 'Tarea no rutinaria sin riesgo crítico específico asociado. Se aplican los criterios generales de análisis de trabajo seguro (identificación de pasos, peligros y controles) conforme a la Ley 19.587 y el Dec. 351/79.'
        };
        function showJSAPermisoInfo(tipo) {
            const box = document.getElementById('jsaPermisoInfo');
            if (!box) return;
            if (tipo && JSA_PERMIT_INFO[tipo]) {
                box.innerHTML = '<i class="fas fa-circle-info mr-1"></i><strong>' + tipo + ':</strong> ' + JSA_PERMIT_INFO[tipo];
                box.classList.remove('hidden');
            } else {
                box.classList.add('hidden');
                box.innerHTML = '';
            }
        }

        // ============= STATE MANAGEMENT =============
        let currentEstablishment = null;
        let currentActiveModule = null; // Módulo actualmente visible

        // Módulos que se resaltan en el sidebar cuando el establecimiento
        // activo está marcado como obra de construcción (obra_construccion = true).
        // No oculta ni restringe ningún módulo: solo prioriza visualmente
        // los más relevantes para la gestión de Higiene y Seguridad en obra.
        const OBRA_PRIORITY_MODULES = ['rgrlObras', 'contractors', 'jsa', 'fireload', 'machinery'];

        function updateObraPriorityHighlights() {
            const isObra = !!(currentEstablishment && currentEstablishment.obra_construccion);
            document.querySelectorAll('.sidebar-nav-item[data-module], .home-card[data-module]').forEach(function(item) {
                const mod = item.getAttribute('data-module');
                const shouldHighlight = isObra && OBRA_PRIORITY_MODULES.includes(mod);
                item.classList.toggle('obra-priority', shouldHighlight);
                let badge = item.querySelector('.obra-priority-badge');
                if (shouldHighlight && !badge) {
                    badge = document.createElement('i');
                    badge.className = 'fas fa-hard-hat obra-priority-badge';
                    badge.title = 'Módulo prioritario para obras de construcción';
                    item.appendChild(badge);
                } else if (!shouldHighlight && badge) {
                    badge.remove();
                }
            });
            if (typeof updateNavCatObraMarks === 'function') {
                updateNavCatObraMarks();
                updateSidebarAlerts();
            }
        }

        // Arrays que componen appData. Toda carga/importación pasa por normalizeAppData
        // para que ninguno falte (y se descarte lo que no pertenece).
        const APP_DATA_KEYS = ['establishments', 'inspections', 'actions', 'fireloads', 'extinguishers', 'risks',
            'trainings', 'incidents', 'ppe', 'ppeDeliveries', 'jsas', 'chemicals', 'measurements', 'evacuationPlans',
            'drills', 'contractors', 'maintenances', 'medicals', 'documents', 'annualTrainingPlan', 'vehicles',
            'machinery', 'wastes', 'audits', 'surveys', 'nonconformities', 'protocols', 'personnel', 'inductions',
            'communications', 'arts', 'signedDocs', 'reqGuide', 'envRecs'];
        function normalizeAppData(src) {
            const out = {};
            APP_DATA_KEYS.forEach(function (k) { out[k] = (src && Array.isArray(src[k])) ? src[k] : []; });
            if (typeof migratePersonnelModel === 'function') migratePersonnelModel(out);
            return out;
        }

        let appData = {
            establishments: [],
            inspections: [],
            actions: [],
            fireloads: [],
            extinguishers: [],
            risks: [],
            trainings: [],
            incidents: [],
            ppe: [],
            jsas: [],
            chemicals: [],
            measurements: [],
            drills: [],
            contractors: [],
            maintenances: [],
            medicals: [],
            documents: [],
            annualTrainingPlan: [],
            vehicles: [],
            machinery: [],
            wastes: [],
            audits: [],
            surveys: [],
            nonconformities: [],
            protocols: [],
            personnel: [],
            inductions: [],
            communications: [],
            arts: [],
            signedDocs: [],
            reqGuide: [],
            envRecs: []
        };

        // ============= JERARQUÍA EMPRESA-OBRA Y ACTIVOS COMPARTIDOS =============
        // Un establecimiento puede ser de tipo 'empresa' (dueña de recursos) o
        // 'obra' (obra de construcción que pertenece a una empresa mediante
        // empresaPadreId). Por compatibilidad con datos existentes, un
        // establecimiento sin campo 'tipo' definido se considera 'empresa'.
        // Los vehículos/maquinarias pertenecen siempre a una empresa
        // (establecimiento_id = id de la empresa dueña) y llevan un arreglo
        // 'asignaciones' con el historial de obras donde estuvieron/están
        // desplegados: {obraId, desde, hasta}. hasta === null indica la
        // asignación abierta (actual). Sin asignación abierta, el activo se
        // considera físicamente en la empresa dueña.

        function esEmpresa(establecimiento) {
            return !!establecimiento && (!establecimiento.tipo || establecimiento.tipo === 'empresa');
        }

        function esObra(establecimiento) {
            return !!establecimiento && establecimiento.tipo === 'obra';
        }

        function getEmpresaMadre(establecimiento) {
            if (!esObra(establecimiento) || !establecimiento.empresaPadreId) return null;
            return (appData.establishments || []).find(function(e) { return e.id === establecimiento.empresaPadreId; }) || null;
        }

        // Devuelve el id de la empresa "dueña" de los recursos gestionados desde
        // este establecimiento: si es una empresa, ella misma; si es una obra
        // con empresa madre válida, la empresa madre; si es una obra huérfana
        // (sin padre o con padre inexistente), actúa como su propia dueña para
        // no romper la carga/visualización de datos.
        function getOwnerEmpresaId(establecimiento) {
            if (!establecimiento) return null;
            const madre = getEmpresaMadre(establecimiento);
            return madre ? madre.id : establecimiento.id;
        }

        function getAsignacionActual(activo) {
            if (!activo || !Array.isArray(activo.asignaciones)) return null;
            return activo.asignaciones.find(function(a) { return !a.hasta; }) || null;
        }

        // Id del establecimiento donde se encuentra físicamente el activo hoy:
        // la obra de su asignación abierta, o su empresa dueña si no tiene
        // ninguna asignación abierta.
        function getUbicacionActualId(activo) {
            const asignacion = getAsignacionActual(activo);
            if (asignacion) return asignacion.obraId;
            return activo.establecimiento_id;
        }

        // Cierra la asignación abierta (si existe) y, si se pasa obraId, abre
        // una nueva asignación hacia esa obra. Sin obraId, el activo vuelve a
        // quedar "en la empresa" (sin asignación abierta).
        function asignarActivoAObra(activo, obraId) {
            if (!activo) return;
            if (!Array.isArray(activo.asignaciones)) activo.asignaciones = [];
            const abierta = getAsignacionActual(activo);
            const ahora = new Date().toISOString();
            if (abierta) abierta.hasta = ahora;
            if (obraId) {
                activo.asignaciones.push({ obraId: obraId, desde: ahora, hasta: null });
            }
        }

        // Cierra cualquier asignación abierta hacia una obra puntual (se usa,
        // por ejemplo, al eliminar esa obra) sin necesidad de tener el activo
        // ya resuelto en memoria.
        function cerrarAsignacionesDeObra(obraId) {
            const ahora = new Date().toISOString();
            ['vehicles', 'machinery'].forEach(function(coleccion) {
                (appData[coleccion] || []).forEach(function(activo) {
                    const abierta = getAsignacionActual(activo);
                    if (abierta && abierta.obraId === obraId) {
                        abierta.hasta = ahora;
                    }
                });
            });
            (appData.personnel || []).forEach(function(w) {
                (Array.isArray(w.asignaciones) ? w.asignaciones : []).forEach(function(a) {
                    if (a && !a.hasta && String(a.obraId) === String(obraId)) a.hasta = ahora;
                });
            });
        }

        // ============= PERSONAL COMPARTIDO ENTRE OBRAS =============
        // Un trabajador pertenece a la EMPRESA (establecimiento_id = empresa dueña) y se
        // lo asigna a una o más obras con 'asignaciones' [{obraId, desde, hasta}]
        // (hasta === null: asignación abierta). A diferencia de vehículos y maquinarias,
        // puede tener varias asignaciones abiertas a la vez. El personal de un
        // contratista queda fijo en el establecimiento donde se cargó el contratista
        // (sin asignaciones). Desde la empresa se ve toda la nómina (propia y de sus
        // obras); desde una obra, sólo quienes tienen asignada esa obra.
        function getEstablecimientoPorId(id) {
            return (appData.establishments || []).find(function (e) { return String(e.id) === String(id); }) || null;
        }
        // Ids de la empresa y de todas sus obras (donde puede haber registros del mismo trabajador).
        function getFamilyEstIds(estId) {
            const est = getEstablecimientoPorId(estId);
            if (!est) return [estId];
            const owner = getOwnerEmpresaId(est);
            const ids = [owner];
            (appData.establishments || []).forEach(function (e) { if (esObra(e) && String(e.empresaPadreId) === String(owner)) ids.push(e.id); });
            return ids;
        }
        function idEnLista(lista, id) { return lista.some(function (x) { return String(x) === String(id); }); }
        function workerObrasAbiertas(w) {
            return (Array.isArray(w && w.asignaciones) ? w.asignaciones : []).filter(function (a) { return a && !a.hasta; }).map(function (a) { return a.obraId; });
        }
        function workerVisibleInEst(w, est) {
            if (!w || !est) return false;
            if (String(w.establecimiento_id) === String(est.id)) return true;
            if (esObra(est)) return idEnLista(workerObrasAbiertas(w), est.id);
            const home = getEstablecimientoPorId(w.establecimiento_id);
            return !!home && esObra(home) && String(getOwnerEmpresaId(home)) === String(getOwnerEmpresaId(est));
        }
        function workerVisibleInId(w, estId) { return workerVisibleInEst(w, getEstablecimientoPorId(estId)); }
        // Obras donde trabaja hoy (nombres): asignaciones abiertas, o la obra donde quedó fijo (contratistas / datos viejos).
        function workerObrasNombres(w) {
            const out = [];
            workerObrasAbiertas(w).forEach(function (id) { const e = getEstablecimientoPorId(id); out.push(e ? e.nombre : 'Obra eliminada'); });
            const home = getEstablecimientoPorId(w.establecimiento_id);
            if (home && esObra(home) && out.indexOf(home.nombre) === -1) out.push(home.nombre);
            return out;
        }
        // Deja abiertas exactamente las asignaciones a "obraIds": cierra las que sobran y abre las nuevas.
        function asignarTrabajadorAObras(w, obraIds) {
            if (!Array.isArray(w.asignaciones)) w.asignaciones = [];
            const want = (obraIds || []).map(String);
            const ahora = new Date().toISOString();
            w.asignaciones.forEach(function (a) { if (a && !a.hasta && want.indexOf(String(a.obraId)) === -1) a.hasta = ahora; });
            want.forEach(function (id) {
                if (!w.asignaciones.some(function (a) { return a && !a.hasta && String(a.obraId) === id; })) w.asignaciones.push({ obraId: id, desde: ahora, hasta: null });
            });
        }
        // Conversión de la nómina vieja (cada trabajador atado a una obra) al modelo compartido.
        // Es idempotente: sólo toca a quien todavía no tiene 'asignaciones'.
        function migratePersonnelModel(d) {
            const ests = (d && d.establishments) || [];
            const byId = function (id) { return ests.find(function (e) { return String(e.id) === String(id); }) || null; };
            ((d && d.personnel) || []).forEach(function (w) {
                if (!w || typeof w !== 'object' || Array.isArray(w.asignaciones)) return;
                w.asignaciones = [];
                const home = byId(w.establecimiento_id);
                if (home && home.tipo === 'obra' && home.empresaPadreId && byId(home.empresaPadreId) && !w.contratista_id) {
                    w.establecimiento_id = home.empresaPadreId;
                    w.asignaciones.push({ obraId: home.id, desde: w.fecha_ingreso ? w.fecha_ingreso + 'T00:00:00.000Z' : (w.created_at || new Date().toISOString()), hasta: null });
                }
            });
        }

        // Vista "dual" de activos compartidos (vehicles/machinery) según el
        // establecimiento actualmente seleccionado en el sidebar:
        //  - Si es una EMPRESA: muestra todos los activos que le pertenecen
        //    (establecimiento_id === id de esa empresa), estén o no desplegados
        //    en una obra en este momento.
        //  - Si es una OBRA: muestra solo los activos cuya asignación actual
        //    apunta a esa obra (getUbicacionActualId === id de la obra).
        function getActivosVisibles(coleccion, establecimiento) {
            const lista = appData[coleccion] || [];
            if (!establecimiento) return [];
            if (esObra(establecimiento)) {
                return lista.filter(function(activo) {
                    return getUbicacionActualId(activo) === establecimiento.id;
                });
            }
            const ownerId = getOwnerEmpresaId(establecimiento);
            return lista.filter(function(activo) { return activo.establecimiento_id === ownerId; });
        }

        function getNombreEstablecimientoPorId(id) {
            const est = (appData.establishments || []).find(function(e) { return e.id === id; });
            return est ? est.nombre : null;
        }

        // Texto corto para mostrar en la ficha del activo indicando dónde está hoy.
        function getUbicacionActualLabel(activo) {
            const asignacion = getAsignacionActual(activo);
            if (asignacion) {
                return '<i class="fas fa-hard-hat"></i> En obra: ' + (getNombreEstablecimientoPorId(asignacion.obraId) || 'Obra eliminada');
            }
            return '<i class="fas fa-building"></i> En la empresa: ' + (getNombreEstablecimientoPorId(activo.establecimiento_id) || 'Empresa eliminada');
        }

        // Genera el <select> HTML para reasignar un activo, listado solo cuando
        // se está viendo desde la empresa dueña (o desde una obra, para poder
        // "devolverlo"). value="" siempre representa "en la empresa".
        function getSelectorUbicacionActivoHtml(activo, onchangeFn) {
            const ownerId = activo.establecimiento_id;
            const obrasHijas = (appData.establishments || []).filter(function(e) {
                return esObra(e) && e.empresaPadreId === ownerId;
            });
            const actualId = getUbicacionActualId(activo);
            let opciones = '<option value=""' + (actualId === ownerId ? ' selected' : '') + '>En la empresa</option>';
            opciones += obrasHijas.map(function(o) {
                return '<option value="' + o.id + '"' + (actualId === o.id ? ' selected' : '') + '>' + o.nombre + '</option>';
            }).join('');
            return '<select onchange="' + onchangeFn + '(' + JSON.stringify(activo.id) + ', this.value)" class="border border-gray-300 rounded p-1 text-xs w-full mt-1">' + opciones + '</select>';
        }

        function cambiarUbicacionVehiculo(vehicleId, nuevaObraId) {
            const vehicle = (appData.vehicles || []).find(function(v) { return v.id === vehicleId || String(v.id) === String(vehicleId); });
            if (!vehicle) return;
            asignarActivoAObra(vehicle, nuevaObraId || null);
            saveData();
            loadVehicles();
        }

        function cambiarUbicacionMaquinaria(machineryId, nuevaObraId) {
            const machinery = (appData.machinery || []).find(function(m) { return m.id === machineryId || String(m.id) === String(machineryId); });
            if (!machinery) return;
            asignarActivoAObra(machinery, nuevaObraId || null);
            saveData();
            loadMachinery();
        }

        // Mantiene visible, en todo momento, a qué EMPRESA pertenecen los
        // datos que se están viendo: el selector de empresa en el sidebar
        // (ver populateEmpresaSidebarSelect/syncSelectorsToEstablishment, que
        // fijan su valor) y un breadcrumb en el header. Si el establecimiento
        // activo es una obra, se muestra "Empresa › Obra"; si es una empresa,
        // sólo su nombre. Se llama cada vez que cambia currentEstablishment
        // (selección, edición o eliminación de establecimientos).
        // Resumen de la empresa/obra activa en el botón plegable del sidebar.
        function updateSidebarEstSummary() {
            const toggle = document.getElementById('sidebarEstToggle');
            if (!toggle) return;
            if (!currentEstablishment) {
                toggle.classList.add('hidden');
                sidebarEstSet(false); // sin selección: el bloque queda abierto para elegir
                return;
            }
            let empresa, obra = '';
            if (esObra(currentEstablishment)) {
                const madre = getEmpresaMadre(currentEstablishment);
                empresa = madre ? madre.nombre : 'Empresa no encontrada';
                obra = currentEstablishment.nombre;
            } else {
                empresa = currentEstablishment.nombre;
                const n = (appData.establishments || []).filter(e => esObra(e) && e.empresaPadreId === currentEstablishment.id).length;
                obra = 'Datos generales' + (n ? ' · ' + n + (n === 1 ? ' obra' : ' obras') : '');
            }
            document.getElementById('sidebarEstSumEmpresa').textContent = empresa;
            document.getElementById('sidebarEstSumObra').textContent = obra;
            toggle.title = empresa + (obra ? ' › ' + obra : '') + ' — clic para cambiar';
            toggle.classList.remove('hidden');
        }
        function sidebarEstSet(collapsed) {
            const body = document.getElementById('sidebarEstBody');
            const toggle = document.getElementById('sidebarEstToggle');
            if (!body || !toggle) return;
            body.classList.toggle('collapsed', collapsed);
            toggle.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        }
        function toggleSidebarEst() {
            const body = document.getElementById('sidebarEstBody');
            if (body) sidebarEstSet(!body.classList.contains('collapsed'));
        }

        function updateEstablishmentContextUI() {
            updateSidebarEstSummary();
            const sidebarObraBox = document.getElementById('sidebarObraName');
            const headerBox = document.getElementById('headerContext');
            const headerSep = document.getElementById('headerContextSep');
            if (!headerBox) return; // vista sin este bloque (no debería pasar, pero por las dudas)

            if (!currentEstablishment) {
                if (sidebarObraBox) sidebarObraBox.classList.add('hidden');
                headerBox.classList.remove('visible');
                return;
            }

            let empresaNombre, obraNombre;
            if (esObra(currentEstablishment)) {
                const madre = getEmpresaMadre(currentEstablishment);
                empresaNombre = madre ? madre.nombre : 'Empresa no encontrada';
                obraNombre = currentEstablishment.nombre;
            } else {
                empresaNombre = currentEstablishment.nombre;
                obraNombre = null;
            }

            if (obraNombre) {
                document.getElementById('sidebarObraNameText').textContent = obraNombre;
                sidebarObraBox.classList.remove('hidden');
            } else if (sidebarObraBox) {
                sidebarObraBox.classList.add('hidden');
            }

            const hcFoto = document.getElementById('headerContextFoto'), hcIcon = document.getElementById('headerContextIcon');
            if (hcFoto) {
                if (currentEstablishment.foto) { hcFoto.src = currentEstablishment.foto; hcFoto.style.display = ''; if (hcIcon) hcIcon.style.display = 'none'; }
                else { hcFoto.removeAttribute('src'); hcFoto.style.display = 'none'; if (hcIcon) hcIcon.style.display = ''; }
            }
            document.getElementById('headerContextEmpresa').textContent = empresaNombre;
            document.getElementById('headerContextObra').textContent = obraNombre || '';
            headerSep.style.display = obraNombre ? '' : 'none';
            headerBox.classList.add('visible');
        }

        // ============= LOGO PDF MANAGEMENT =============
        // Logo PROHS en formato base64 para PDFs (será convertido de WebP a PNG)
        let pdfLogoBase64 = null;
        
        // Función para convertir WebP a PNG/JPEG para jsPDF
        async function convertWebPtoJPEG(webpBase64) {
            return new Promise((resolve) => {
                const img = new Image();
                img.onload = function() {
                    const canvas = document.createElement('canvas');
                    canvas.width = img.width;
                    canvas.height = img.height;
                    const ctx = canvas.getContext('2d');
                    // Fondo blanco para JPEG
                    ctx.fillStyle = '#FFFFFF';
                    ctx.fillRect(0, 0, canvas.width, canvas.height);
                    ctx.drawImage(img, 0, 0);
                    const jpegBase64 = canvas.toDataURL('image/jpeg', 0.95);
                    resolve(jpegBase64);
                };
                img.onerror = function() {
                    resolve(null);
                };
                img.src = webpBase64;
            });
        }
        
        // Inicializar logo para PDFs
        async function initPdfLogo() {
            const logoImg = document.querySelector('.splash-logo img');
            if (logoImg && logoImg.src) {
                pdfLogoBase64 = await convertWebPtoJPEG(logoImg.src);
            }
        }
        
        // Función para agregar encabezado con logo a PDF
        function addPdfHeader(doc, title, establishment = null) {
            const pageWidth = doc.internal.pageSize.getWidth();
            const primaryColor = [15, 115, 197]; // #0f73c5
            
            // Rectángulo de fondo del header (más compacto)
            doc.setFillColor(primaryColor[0], primaryColor[1], primaryColor[2]);
            doc.rect(0, 0, pageWidth, 22, 'F');
            pdfHeaderPhoto(doc, establishment || currentEstablishment);
            
            // Logo (si está disponible)
            let textStartX = 14;
            if (pdfLogoBase64) {
                try {
                    // Logo más pequeño con proporción correcta (ratio original 2.31:1)
                    const logoWidth = 32;
                    const logoHeight = logoWidth / 2.31; // ~14
                    doc.addImage(pdfLogoBase64, 'JPEG', 5, 5, logoWidth, logoHeight);
                    textStartX = 40;
                } catch (e) {
                    console.warn('Error al agregar logo al PDF:', e);
                }
            }
            
            // Título del documento
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(13);
            doc.setFont('helvetica', 'bold');
            doc.text(title, textStartX, 10);
            
            // Subtítulo con establecimiento
            doc.setFontSize(9);
            doc.setFont('helvetica', 'normal');
            const estName = establishment ? establishment.nombre : (currentEstablishment ? currentEstablishment.nombre : 'Sin establecimiento');
            doc.text(estName, textStartX, 16);
            
            // El contenido que sigue al encabezado se escribe en negro (antes quedaba
            // en blanco sobre blanco —invisible— tras cada salto de página).
            doc.setTextColor(0, 0, 0);
            // Retornar Y donde debe comenzar el contenido (fecha va en footer)
            return 28;
        }
        
        // Función para agregar pie de página a PDF
        function addPdfFooter(doc, pageNum, totalPages) {
            const pageWidth = doc.internal.pageSize.getWidth();
            const pageHeight = doc.internal.pageSize.getHeight();
            const margin = 15;
            
            // Si no se pasa totalPages, calcularlo
            const total = totalPages || doc.internal.getNumberOfPages();
            
            // Linea separadora
            doc.setDrawColor(200, 200, 200);
            doc.setLineWidth(0.3);
            doc.line(margin, pageHeight - 15, pageWidth - margin, pageHeight - 15);
            
            doc.setFontSize(7);
            doc.setTextColor(120, 120, 120);
            doc.text('PROHS Consulting - Sistema de Gestion en Higiene y Seguridad', margin, pageHeight - 10);
            
            // Fecha y hora de generacion
            const fechaGen = new Date().toLocaleString('es-AR', { 
                day: '2-digit', month: '2-digit', year: 'numeric',
                hour: '2-digit', minute: '2-digit', second: '2-digit'
            });
            doc.text('Informe generado: ' + fechaGen, margin, pageHeight - 6);
            
            // Numero de pagina a la derecha
            doc.text('Pagina ' + pageNum + ' de ' + total, pageWidth - margin, pageHeight - 8, { align: 'right' });
        }

        // ---- Fotos en PDF sin deformar ----
        // Dimensiones reales de la imagen (jsPDF las lee del propio archivo, de forma
        // sincrónica; no hace falta esperar a que cargue un <img>).
        function pdfImgSize(doc, data) {
            try { const p = doc.getImageProperties(data); if (p && p.width && p.height) return { w: p.width, h: p.height }; } catch (e) { /* sin datos */ }
            return null;
        }
        // Entra completa dentro de maxW x maxH, conservando la proporción. Devuelve {w,h} dibujados.
        function pdfAddImageFit(doc, data, x, y, maxW, maxH, align) {
            const sz = pdfImgSize(doc, data);
            if (!sz) return { w: 0, h: 0 };
            const k = Math.min(maxW / sz.w, maxH / sz.h);
            const w = sz.w * k, h = sz.h * k;
            const ox = align === 'right' ? x + maxW - w : (align === 'left' ? x : x + (maxW - w) / 2);
            try { doc.addImage(data, 'JPEG', ox, y, w, h); } catch (e) { return { w: 0, h: 0 }; }
            return { w: w, h: h };
        }
        // Llena un recuadro w x h recortando el sobrante (como object-fit: cover en la pantalla).
        // focusY: 0 = recorta abajo, 0.5 = centrado; en retratos conviene ~0.3 para no cortar la cabeza.
        function pdfAddImageCover(doc, data, x, y, w, h, focusY) {
            const sz = pdfImgSize(doc, data);
            if (!sz) return false;
            const k = Math.max(w / sz.w, h / sz.h);
            const dw = sz.w * k, dh = sz.h * k;
            const fy = (focusY === undefined) ? 0.5 : focusY;
            const ox = x - (dw - w) / 2, oy = y - (dh - h) * fy;
            try {
                doc.saveGraphicsState();
                doc.rect(x, y, w, h, null);
                doc.clip();
                doc.discardPath();
                doc.addImage(data, 'JPEG', ox, oy, dw, dh);
                doc.restoreGraphicsState();
            } catch (e) { try { doc.restoreGraphicsState(); } catch (e2) {} return false; }
            return true;
        }

        // ============= EXPORTAR / COMPARTIR / IMPRIMIR PDF =============
        /**
         * Punto único por el que pasan los ~34 exports de PDF de la app.
         * `mode` puede ser:
         * - undefined (default): en Desktop/Electron, muestra un pequeño
         *   panel preguntando "Guardar PDF" o "Imprimir" (ver
         *   askSaveOrPrintPdf) — así el mismo botón "Exportar PDF" de
         *   siempre cubre ambos casos, sin agregar botones nuevos ni
         *   alterar el espacio/orden de la interfaz. En Navegador/Android
         *   se comporta como 'save' directamente (sin preguntar).
         * - 'save': descarga en Navegador/Escritorio, panel de "Compartir"
         *   en Android.
         * - 'print': imprime directamente (sólo Desktop/Electron, usando
         *   el visor de PDF integrado de Chromium en una ventana oculta
         *   para abrir el diálogo de impresión nativo de Windows).
         */
        function askSaveOrPrintPdf(filename) {
            return new Promise((resolve) => {
                const overlay = document.createElement('div');
                overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:9000;display:flex;align-items:center;justify-content:center;padding:16px;';
                overlay.innerHTML = `
                    <div style="background:white;border-radius:14px;padding:24px;max-width:320px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,0.35);text-align:center;">
                        <i class="fas fa-file-pdf" style="font-size:2rem;color:#dc2626;margin-bottom:8px;display:block;"></i>
                        <p style="font-weight:700;color:#1f2937;margin-bottom:2px;">PDF generado</p>
                        <p style="font-size:11px;color:#9ca3af;margin-bottom:18px;word-break:break-all;">${filename}</p>
                        <div style="display:flex;flex-direction:column;gap:8px;">
                            <button id="__askSavePdf" style="background:#2563eb;color:white;padding:12px;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:14px;">
                                <i class="fas fa-download"></i>&nbsp; Guardar PDF
                            </button>
                            <button id="__askPrintPdf" style="background:#374151;color:white;padding:12px;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:14px;">
                                <i class="fas fa-print"></i>&nbsp; Imprimir
                            </button>
                            <button id="__askCancelPdf" style="background:transparent;color:#6b7280;padding:6px;border:none;font-weight:600;cursor:pointer;font-size:13px;">
                                Cancelar
                            </button>
                        </div>
                    </div>`;
                document.body.appendChild(overlay);

                function cleanup(result) {
                    overlay.remove();
                    document.removeEventListener('keydown', onKeydown);
                    resolve(result);
                }
                function onKeydown(e) {
                    if (e.key === 'Escape') cleanup(null);
                }
                overlay.addEventListener('click', (e) => { if (e.target === overlay) cleanup(null); });
                document.addEventListener('keydown', onKeydown);
                overlay.querySelector('#__askSavePdf').onclick = () => cleanup('save');
                overlay.querySelector('#__askPrintPdf').onclick = () => cleanup('print');
                overlay.querySelector('#__askCancelPdf').onclick = () => cleanup(null);
            });
        }

        async function exportPdf(pdfDoc, filename, mode) {
            try {
                const isElectron = !!(window.prohsAPI && window.prohsAPI.pdf);

                if (isElectron && !mode) {
                    mode = await askSaveOrPrintPdf(filename);
                    if (!mode) return; // el usuario canceló
                }

                if (mode === 'print') {
                    if (!window.prohsAPI || !window.prohsAPI.pdf) {
                        // No debería poder pasar (esta rama sólo se activa
                        // desde el panel de arriba, que sólo aparece en
                        // Electron), pero por las dudas caemos a guardar
                        // en vez de no hacer nada.
                        pdfDoc.save(filename);
                        return;
                    }
                    const dataUri = pdfDoc.output('datauristring');
                    const result = await window.prohsAPI.pdf.print(dataUri, filename);
                    if (!result || !result.ok) {
                        const reason = result && result.reason;
                        // Cancelar el diálogo de impresión también entra acá;
                        // sólo avisamos si parece un error real.
                        if (reason && !/cancel/i.test(reason)) {
                            alert('No se pudo imprimir: ' + reason);
                        }
                    }
                    return;
                }

                const isNative = window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform();
                if (!isNative) {
                    pdfDoc.save(filename);
                    return;
                }

                const plugins = window.Capacitor.Plugins || {};
                const { Filesystem, Share } = plugins;
                if (!Filesystem || !Share) {
                    console.warn('[exportPdf] Filesystem/Share no disponibles en este build; se usa doc.save() como respaldo.');
                    pdfDoc.save(filename);
                    return;
                }

                // jsPDF: obtenemos el contenido del PDF en base64
                const dataUri = pdfDoc.output('datauristring');
                const base64Data = dataUri.substring(dataUri.indexOf(',') + 1);

                await Filesystem.writeFile({
                    path: filename,
                    data: base64Data,
                    directory: 'CACHE'
                });

                const fileInfo = await Filesystem.getUri({
                    directory: 'CACHE',
                    path: filename
                });

                await Share.share({
                    title: filename,
                    text: 'PDF generado por el Sistema PROHS',
                    url: fileInfo.uri,
                    dialogTitle: 'Guardar o compartir PDF'
                });
            } catch (e) {
                console.error('Error al exportar/compartir/imprimir el PDF:', e);
                alert('No se pudo procesar el PDF: ' + (e && e.message ? e.message : e));
            }
        }


        // ============= NOTIFICACIONES GLOBALES (vencimientos) =============
        /**
         * Recorre TODOS los establecimientos (no sólo el que está
         * seleccionado) buscando vencimientos y próximos vencimientos:
         * extintores, exámenes médicos, mantenimiento de equipos y
         * acciones pendientes. Se usa para la botón Pendientes de la cabecera,
         * visible en las tres plataformas y que no cambia según el
         * establecimiento activo.
         */
        function computeGlobalAlerts() {
            // Misma fuente y mismo criterio que los números del menú y los avisos de cada módulo.
            const items = attnSort(attnCollect(null)).filter(function (it) { return it.estado !== 'sin_denunciar'; });
            return items.map(function (it) {
                const m = ATTN_MODS[it.mod] || { label: it.mod, icon: 'fa-clipboard-list' };
                const vencido = it.estado !== 'por_vencer';
                return {
                    categoria: m.label, icono: m.icon,
                    establecimiento: attnEstName(it.estId) || 'Establecimiento desconocido',
                    establecimientoId: it.estId, modulo: it.mod, itemId: it.id,
                    descripcion: it.titulo + (it.detalle ? ' — ' + it.detalle : ''),
                    fecha: it.fecha, estado: vencido ? 'vencido' : 'proximo',
                    dias: it.dias === null ? null : Math.abs(it.dias), texto: it.estado === 'faltante' ? 'Falta' : ''
                };
            });
        }

        // El botón «Pendientes» no lleva globo con número (siempre habría algo por vencer):
        // el detalle se ve al abrir el panel. Acá sólo se actualiza su descripción.
        function updateNotificationBadge() {
            const btn = document.getElementById('btnNotifications');
            if (!btn) return;
            const alerts = computeGlobalAlerts();
            const vencidos = alerts.filter(a => a.estado === 'vencido').length;
            const total = alerts.length;
            btn.title = total === 0
                ? 'Pendientes: sin vencimientos en ningún establecimiento'
                : 'Pendientes: ' + vencidos + ' vencidos o faltantes · ' + (total - vencidos) + ' por vencer (todos los establecimientos)';
        }

        function renderNotificationsPanel() {
            const panel = document.getElementById('notifPanel');
            if (!panel) return;
            const alerts = computeGlobalAlerts();

            if (alerts.length === 0) {
                panel.innerHTML = '<div class="p-6 text-center text-gray-500"><i class="fas fa-check-circle text-green-500 text-2xl mb-2"></i><p>Sin vencimientos pendientes en ningún establecimiento.</p></div>';
                return;
            }

            // Orden: primero lo vencido/faltante, luego lo próximo; dentro de cada grupo, de la fecha más antigua a la más reciente
            // (lo que no tiene fecha, como un faltante, va primero).
            const byFecha = (x, y) => {
                if (!x.fecha && !y.fecha) return 0;
                if (!x.fecha) return -1;
                if (!y.fecha) return 1;
                return String(x.fecha).localeCompare(String(y.fecha));
            };
            const venc = alerts.filter(a => a.estado === 'vencido').sort(byFecha);
            const prox = alerts.filter(a => a.estado !== 'vencido').sort(byFecha);
            const rowHtml = a => {
                const badgeClass = a.estado === 'vencido' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700';
                const badgeText = a.texto ? a.texto : (a.estado === 'vencido' ? ('Vencido hace ' + a.dias + ' día' + (a.dias === 1 ? '' : 's')) : (a.dias === 0 ? 'Vence hoy' : 'Vence en ' + a.dias + ' día' + (a.dias === 1 ? '' : 's')));
                // Usamos data-* en vez de armar el onclick como texto con
                // comillas interpoladas: si el nombre de un establecimiento
                // o una descripción tuviera una comilla, podía romper el
                // atributo onclick y dejar la fila sin funcionar, en
                // silencio. Con data-* + un solo listener delegado (ver
                // notifPanel.addEventListener más abajo) no hay ese riesgo.
                return `<div class="notif-row px-4 py-3 border-b border-gray-100 hover:bg-gray-50 cursor-pointer" data-est-id="${a.establecimientoId}" data-modulo="${a.modulo}" data-item-id="${safeText(String(a.itemId || ''))}" title="Ir a ${safeText(a.establecimiento)} — abre el módulo correspondiente">
                    <div class="flex items-start justify-between gap-2">
                        <div class="flex items-start gap-2 min-w-0">
                            <i class="fas ${a.icono} text-gray-400 mt-1"></i>
                            <div class="min-w-0">
                                <p class="text-sm font-semibold text-gray-800 truncate">${a.categoria}: ${safeText(a.descripcion)}</p>
                                <p class="text-xs text-gray-500">${safeText(a.establecimiento)}</p>
                            </div>
                        </div>
                        <span class="text-xs font-semibold px-2 py-1 rounded-full whitespace-nowrap ${badgeClass}">${badgeText}</span>
                    </div>
                </div>`;
            };
            const sec = (txt, cls) => `<div class="px-4 py-1 text-xs font-bold uppercase tracking-wide border-b ${cls}">${txt}</div>`;
            const rows = (venc.length ? sec('Vencidos y faltantes (' + venc.length + ')', 'bg-red-50 text-red-700 border-red-100') + venc.map(rowHtml).join('') : '') +
                         (prox.length ? sec('Próximos a vencer (' + prox.length + ')', 'bg-yellow-50 text-yellow-700 border-yellow-100') + prox.map(rowHtml).join('') : '');

            const vencidosCount = venc.length;
            const proximosCount = prox.length;
            const header = `<div class="px-4 py-2 bg-gray-50 border-b border-gray-200 text-xs text-gray-600 font-semibold">
                ${vencidosCount} vencido${vencidosCount === 1 ? '' : 's'} · ${proximosCount} próximo${proximosCount === 1 ? '' : 's'} a vencer — todos los establecimientos
            </div>`;

            panel.innerHTML = header + rows;
        }

        function anchorNotificationsPanel() {
            const panel = document.getElementById('notifPanel');
            const btn = document.getElementById('btnNotifications');
            if (!panel || !btn) return;
            const rect = btn.getBoundingClientRect();
            const panelWidth = Math.min(380, window.innerWidth - 24);
            panel.style.width = panelWidth + 'px';
            // Alineado a la derecha del botón, igual que antes, pero ahora
            // calculado en coordenadas de pantalla (position: fixed) para
            // no depender de ningún ancestro con overflow:hidden.
            let left = rect.right - panelWidth;
            if (left < 12) left = 12; // no se pise contra el borde izquierdo en pantallas chicas
            panel.style.left = left + 'px';
            panel.style.top = (rect.bottom + 8) + 'px';
            panel.style.right = 'auto';
        }

        /**
         * Un solo listener para todos los clics dentro del panel de
         * notificaciones (event delegation), en vez de un onclick por
         * fila. Se registra UNA vez porque el contenedor #notifPanel es
         * estable — sólo cambia su contenido interno en cada apertura.
         */
        function setupNotificationsPanelDelegation() {
            const panel = document.getElementById('notifPanel');
            if (!panel || panel.dataset.delegationBound === 'true') return;
            panel.dataset.delegationBound = 'true';
            panel.addEventListener('click', function (event) {
                const row = event.target.closest('.notif-row');
                if (!row) return;
                event.stopPropagation();
                // OJO: el id de un establecimiento puede ser un string tipo
                // "est-1737400000123" (creado a mano desde el formulario) o
                // un número puro (si vino de una importación). Por eso NO
                // convertimos con Number() acá — se compara como string en
                // goToAlert() para que funcione con los dos formatos.
                const estId = row.dataset.estId;
                const modulo = row.dataset.modulo;
                goToAlert(estId, modulo, row.dataset.itemId);
            });
        }

        /**
         * Al hacer clic en un elemento del panel Pendientes: selecciona
         * automáticamente el establecimiento correspondiente y abre el
         * módulo donde vive ese elemento (extintores, vigilancia de
         * salud, mantenimiento o acciones).
         */
        function goToAlert(establecimientoId, modulo, itemId) {
            try {
                // Comparar como string: el id de un establecimiento puede
                // ser un string ("est-...") o un número puro (si vino de
                // una importación), según cómo se haya creado.
                const idx = (appData.establishments || []).findIndex(e => String(e.id) === String(establecimientoId));
                if (idx === -1) {
                    alert('No se encontró el establecimiento (puede haber sido eliminado o modificado).\n\nID buscado: ' + establecimientoId);
                    return;
                }

                // Cerrar el panel de notificaciones
                const panel = document.getElementById('notifPanel');
                if (panel) panel.classList.add('hidden');
                document.removeEventListener('click', closeNotificationsPanelOnClickOutside);
                window.removeEventListener('resize', anchorNotificationsPanel);

                syncSelectorsToEstablishment(appData.establishments[idx]);
                // activateEstablishment() (dentro de syncSelectorsToEstablishment)
                // tiene su propia animación de carga (~400ms) antes de fijar
                // currentEstablishment; esperamos un poco más para que el
                // módulo ya encuentre el establecimiento activo.
                setTimeout(() => {
                    try {
                        showModule(modulo);
                        if (itemId) setTimeout(function () { attnFocus(modulo, itemId); }, 700);
                    } catch (e) {
                        console.error('[goToAlert] Error al abrir el módulo:', e);
                        alert('No se pudo abrir el módulo "' + modulo + '": ' + (e && e.message ? e.message : e));
                    }
                }, 450);
            } catch (e) {
                console.error('[goToAlert] Error inesperado:', e);
                alert('No se pudo ir al elemento seleccionado: ' + (e && e.message ? e.message : e));
            }
        }

        function toggleNotificationsPanel(event) {
            if (event) event.stopPropagation();
            const panel = document.getElementById('notifPanel');
            if (!panel) return;
            const isHidden = panel.classList.contains('hidden');
            if (isHidden) {
                renderNotificationsPanel();
                anchorNotificationsPanel();
                panel.classList.remove('hidden');
                document.addEventListener('click', closeNotificationsPanelOnClickOutside);
                window.addEventListener('resize', anchorNotificationsPanel);
            } else {
                panel.classList.add('hidden');
                document.removeEventListener('click', closeNotificationsPanelOnClickOutside);
                window.removeEventListener('resize', anchorNotificationsPanel);
            }
        }

        function closeNotificationsPanelOnClickOutside(event) {
            const panel = document.getElementById('notifPanel');
            const btn = document.getElementById('btnNotifications');
            if (!panel || panel.classList.contains('hidden')) return;
            if (panel.contains(event.target) || (btn && btn.contains(event.target))) return;
            panel.classList.add('hidden');
            document.removeEventListener('click', closeNotificationsPanelOnClickOutside);
            window.removeEventListener('resize', anchorNotificationsPanel);
        }

        // ============= EXPORTAR / COMPARTIR ARCHIVOS (no-PDF) =============
        /**
         * Análogo a exportPdf(), pero para archivos de texto (backups JSON,
         * CSV, TXT). Mismo problema, misma solución: en Android el enlace de
         * descarga (Blob + <a download>) no lo atiende nadie, así que hay que
         * escribirlo a la caché de la app y abrir el panel nativo de compartir.
         */
        async function exportFile(content, filename, mimeType) {
            try {
                const isNative = window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform();
                const plugins = (isNative && window.Capacitor.Plugins) || {};
                const { Filesystem, Share } = plugins;

                if (!isNative || !Filesystem || !Share) {
                    // Navegador / Escritorio (Electron): descarga estándar
                    const blob = new Blob([content], { type: mimeType || 'application/octet-stream' });
                    const url = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = filename;
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                    setTimeout(() => URL.revokeObjectURL(url), 1000);
                    return;
                }

                await Filesystem.writeFile({
                    path: filename,
                    data: content,
                    directory: 'CACHE',
                    encoding: 'utf8'
                });

                const fileInfo = await Filesystem.getUri({
                    directory: 'CACHE',
                    path: filename
                });

                await Share.share({
                    title: filename,
                    text: 'Archivo generado por el Sistema PROHS',
                    url: fileInfo.uri,
                    dialogTitle: 'Guardar o compartir archivo'
                });
            } catch (e) {
                console.error('Error al exportar/compartir el archivo:', e);
                alert('No se pudo generar/compartir el archivo: ' + (e && e.message ? e.message : e));
            }
        }

        // ============= INITIALIZATION =============
        async function initApp() {
            // Inicializar modo rendimiento ANTES de todo para aplicar CSS inmediatamente
            initPerformanceMode();

            // Versión hospedada: pedir usuario y contraseña antes de cargar cualquier dato (js/nube.js)
            if (window.prohsCloud) {
                try { await window.prohsCloud.ready(); } catch (e) { console.error('[nube]', e); }
            }
            
            // Splash screen - más corto en modo rendimiento
            const splashDelay = performanceMode ? 800 : 3000;
            setTimeout(() => {
                // Si corresponde, el selector de inicio aparece justo ahora, encima del splash
                if (window.prohsInicio) window.prohsInicio.splashEnding();
                const splashScreen = document.getElementById('splashScreen');
                if (splashScreen) {
                    if (performanceMode) {
                        splashScreen.style.display = 'none';
                        document.body.classList.remove('splash-active');
                    } else {
                        splashScreen.classList.add('fade-out');
                        setTimeout(() => {
                            splashScreen.style.display = 'none';
                            document.body.classList.remove('splash-active');
                        }, 1000);
                    }
                }
            }, splashDelay);
            
            // Inicializar app con manejo de errores
            try {
                initSidebarNav(); // menú por categorías + buscador (antes de cargar datos)
                await loadData();
                populateEmpresaSidebarSelect();
                populateEstablishments();
                updateOfflineIndicator();
                renderMainCalendar(); // Render calendar on load
                initPdfLogo(); // Inicializar logo para PDFs
                setActiveSidebarItem('home'); // Resaltar inicio en sidebar
                updateNotificationBadge(); // Vencimientos de todos los establecimientos
                updateSidebarAlerts(); // Pastillas de vencimientos en el menú
                setupNotificationsPanelDelegation(); // Un solo listener para todos los clics del panel
                
                // Check online status
                window.addEventListener('online', updateOfflineIndicator);
                window.addEventListener('offline', updateOfflineIndicator);

                // Todo salió bien: cancelamos el watchdog de seguridad,
                // no hace falta forzar nada.
                if (window.__prohsBootWatchdog) clearTimeout(window.__prohsBootWatchdog);

                // Pantalla de inicio: elegir empresa y luego establecimiento
                if (window.prohsInicio) window.prohsInicio.maybeShow();
            } catch (error) {
                console.error('Error durante la inicialización:', error);
                if (window.__prohsBootErrors) {
                    window.__prohsBootErrors.push((error && error.stack) || String(error));
                }
                // No dejamos la app trabada: mostramos igual la pantalla
                // principal (con el aviso de error arriba) en vez de
                // esperar los 8 segundos del watchdog.
                if (window.__prohsBootWatchdog) clearTimeout(window.__prohsBootWatchdog);
                if (typeof __prohsForceRevealApp === 'function') __prohsForceRevealApp();
            }
        }

        async function loadData() {
            try {
                await Storage.migrateFromLocalStorage();
                const stored = await Storage.getItem('higieneApp');
                if (stored) {
                    const loadedData = JSON.parse(stored);
                    // Merge con la estructura base para asegurar que todas las propiedades existan
                    appData = normalizeAppData(loadedData);
                    purgeOrphanSignedDocs();
                }
            } catch (e) {
                console.error('Error al cargar datos desde localStorage:', e);
                alert('Se detectó un error en los datos guardados. Se iniciará con datos vacíos. Puede intentar importar un backup si tiene uno.');
            }
        }

        function saveData() {
            // Nota: el guardado es asíncrono (IndexedDB / filesystem), pero se dispara
            // sin "await" para no tener que convertir en async las ~70 funciones que
            // llaman a saveData(). appData ya está actualizado en memoria de forma
            // inmediata; la persistencia en disco ocurre en segundo plano.
            try {
                Storage.setItem('higieneApp', JSON.stringify(appData)).catch(e => {
                    console.error('Error al guardar datos:', e);
                    alert('No se pudieron guardar los datos: ' + e.message + '\n\nSi el problema persiste, exporte un backup desde Ajustes.');
                });
            } catch (e) {
                console.error('Error al guardar datos:', e);
            }
            // Mantener el botón Pendientes de vencimientos al día ante cualquier
            // cambio (es una operación liviana, sólo recorre appData en memoria).
            if (typeof updateNotificationBadge === 'function') {
                try { updateNotificationBadge(); } catch (e) { /* noop */ }
                try { navScheduleAlerts(); } catch (e) { /* noop */ }
            }
        }

        /** Espera a que la última escritura pendiente termine (usar antes de cerrar la app o exportar). */
        async function flushPendingSave() {
            try { await Storage.flush(); } catch (e) { /* noop */ }
        }

        // Helper para proteger texto en PDFs contra valores null/undefined
        function safeText(value, fallback) {
            if (value === null || value === undefined) return fallback || 'N/A';
            return String(value);
        }
        
        // Helper para proteger doc.text contra valores null/undefined
        function safePdfText(doc, text, x, y, options) {
            const safeStr = (text === null || text === undefined) ? 'N/A' : String(text);
            if (options) {
                doc.text(safeStr, x, y, options);
            } else {
                doc.text(safeStr, x, y);
            }
        }

        function updateOfflineIndicator() {
            const indicator = document.getElementById('offlineIndicator');
            if (navigator.onLine) {
                indicator.className = 'offline-indicator bg-green-500 text-white';
                indicator.textContent = '';
                indicator.innerHTML = '<i class="fas fa-bolt"></i> Modo Online';
            } else {
                indicator.className = 'offline-indicator bg-orange-500 text-white';
                indicator.innerHTML = '<i class="fas fa-wifi-slash"></i> Modo Offline';
            }
        }

        // ============= MODO RENDIMIENTO =============
        let performanceMode = false;
        
        function togglePerformanceMode() {
            performanceMode = !performanceMode;
            document.body.classList.toggle('performance-mode', performanceMode);
            
            if (performanceMode) {
                localStorage.setItem('performanceMode', 'true');
                // Destruir gráficos activos para liberar memoria
                if (typeof dashboardCharts !== 'undefined') {
                    Object.keys(dashboardCharts).forEach(function(key) {
                        if (dashboardCharts[key]) {
                            dashboardCharts[key].destroy();
                            dashboardCharts[key] = null;
                        }
                    });
                }
            } else {
                localStorage.setItem('performanceMode', 'false');
            }
            updatePerformanceButton();
        }
        
        // Utilidad debounce para evitar renders excesivos en búsquedas
        function debounce(func, wait) {
            let timeout;
            return function() {
                const context = this, args = arguments;
                clearTimeout(timeout);
                timeout = setTimeout(function() { func.apply(context, args); }, wait);
            };
        }
        
        function initPerformanceMode() {
            // Verificar si estaba activado previamente
            if (localStorage.getItem('performanceMode') === 'true') {
                performanceMode = true;
                document.body.classList.add('performance-mode');
            }
            
            // Detectar hardware limitado automáticamente
            if (navigator.hardwareConcurrency && navigator.hardwareConcurrency <= 2) {
                if (localStorage.getItem('performanceMode') === null) {
                    performanceMode = true;
                    document.body.classList.add('performance-mode');
                    localStorage.setItem('performanceMode', 'true');
                }
            }
        }

        // ============= FIRMA DIGITAL (SIGNATURE PAD) =============
        const signaturePads = {};
        
        function initSignaturePad(canvasId, options) {
            const canvas = document.getElementById(canvasId);
            if (!canvas || signaturePads[canvasId]) return;
            
            const ctx = canvas.getContext('2d');
            const placeholder = document.getElementById(canvasId + 'Placeholder');
            const isFullscreen = options && options.fullscreen;
            const isRotated = options && options.rotated;
            var canvasCssW = 0, canvasCssH = 0;
            
            // Ajustar resolución del canvas al tamaño CSS visible
            function resizeCanvas() {
                var cssW, cssH;
                if (isFullscreen) {
                    var wrap = canvas.parentElement;
                    cssW = wrap.clientWidth;
                    cssH = wrap.clientHeight;
                } else {
                    var parentRect = canvas.parentElement.getBoundingClientRect();
                    cssW = parentRect.width;
                    cssH = 150;
                }
                
                canvasCssW = cssW;
                canvasCssH = cssH;
                
                var dpr = window.devicePixelRatio || 1;
                canvas.width = cssW * dpr;
                canvas.height = cssH * dpr;
                canvas.style.width = cssW + 'px';
                canvas.style.height = cssH + 'px';
                
                ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
                ctx.strokeStyle = '#1e3a5f';
                ctx.lineWidth = isFullscreen ? 3 : 2.5;
                ctx.lineCap = 'round';
                ctx.lineJoin = 'round';
                
                redrawStrokes(canvasId);
            }
            
            let isDrawing = false;
            let lastX = 0;
            let lastY = 0;
            let strokes = [];
            let currentStroke = [];
            
            function getPos(e) {
                const rect = canvas.getBoundingClientRect();
                let clientX, clientY;
                if (e.touches && e.touches.length > 0) {
                    clientX = e.touches[0].clientX;
                    clientY = e.touches[0].clientY;
                } else {
                    clientX = e.clientX;
                    clientY = e.clientY;
                }
                
                if (isRotated) {
                    // El overlay con CSS rotate(90deg) hace que el AABB
                    // tenga los ejes invertidos respecto al canvas local.
                    // Convertir de coordenadas AABB a coordenadas canvas local:
                    var relX = clientX - rect.left;
                    var relY = clientY - rect.top;
                    return {
                        x: (relY / rect.height) * canvasCssW,
                        y: (1 - relX / rect.width) * canvasCssH
                    };
                }
                
                return {
                    x: clientX - rect.left,
                    y: clientY - rect.top
                };
            }
            
            function startDraw(e) {
                e.preventDefault();
                isDrawing = true;
                canvas.classList.add('signing');
                if (placeholder) placeholder.classList.add('hidden');
                const pos = getPos(e);
                lastX = pos.x;
                lastY = pos.y;
                currentStroke = [{ x: pos.x, y: pos.y }];
                ctx.beginPath();
                ctx.moveTo(pos.x, pos.y);
            }
            
            function draw(e) {
                if (!isDrawing) return;
                e.preventDefault();
                const pos = getPos(e);
                ctx.beginPath();
                ctx.moveTo(lastX, lastY);
                ctx.lineTo(pos.x, pos.y);
                ctx.stroke();
                lastX = pos.x;
                lastY = pos.y;
                currentStroke.push({ x: pos.x, y: pos.y });
            }
            
            function endDraw(e) {
                if (!isDrawing) return;
                if (e && e.preventDefault) e.preventDefault();
                isDrawing = false;
                canvas.classList.remove('signing');
                if (currentStroke.length > 1) {
                    strokes.push([...currentStroke]);
                }
                currentStroke = [];
            }
            
            // --- Táctil: la firma se "activa" con un toque, así deslizar la pantalla ---
            // --- por encima del panel (para hacer scroll) no dibuja sin querer.     ---
            const coarse = !!(window.matchMedia && window.matchMedia('(pointer: coarse)').matches);
            const placeholderHtml = placeholder ? placeholder.innerHTML : '';
            let armed = !!isFullscreen;          // en pantalla completa se firma directo
            let armTimer = null;
            let tap = null;                      // seguimiento del toque mientras la firma está inactiva
            let lastTouchAt = 0;
            const ARM_IDLE_MS = 10000;

            function setPlaceholder(isArmed) {
                if (!placeholder || isFullscreen || !coarse) return;
                placeholder.innerHTML = isArmed
                    ? '<i class="fas fa-pen-fancy"></i><br>Firmá acá con el dedo'
                    : '<i class="fas fa-hand-pointer"></i><br>Tocá una vez para activar la firma';
            }
            function onOutsideTouch(ev) { if (!canvas.contains(ev.target)) disarm(); }
            function onAnyScroll() { if (!isDrawing) disarm(); }
            function bumpArmTimer() {
                clearTimeout(armTimer);
                armTimer = setTimeout(function () { if (!isDrawing) disarm(); }, ARM_IDLE_MS);
            }
            function arm() {
                if (armed) return;
                armed = true;
                canvas.classList.add('armed');
                setPlaceholder(true);
                document.addEventListener('touchstart', onOutsideTouch, true);
                document.addEventListener('scroll', onAnyScroll, true);
                bumpArmTimer();
            }
            function disarm() {
                if (isFullscreen || !armed) return;
                armed = false;
                clearTimeout(armTimer);
                canvas.classList.remove('armed');
                document.removeEventListener('touchstart', onOutsideTouch, true);
                document.removeEventListener('scroll', onAnyScroll, true);
                if (strokes.length === 0) setPlaceholder(false);
            }

            function touchStart(e) {
                lastTouchAt = Date.now();
                if (armed) { clearTimeout(armTimer); startDraw(e); return; }
                const t = e.touches[0];
                tap = { x: t.clientX, y: t.clientY, t: Date.now(), moved: e.touches.length > 1 };
            }
            function touchMove(e) {
                lastTouchAt = Date.now();
                if (armed) { draw(e); return; }
                if (tap && e.touches.length) {
                    const t = e.touches[0];
                    if (Math.hypot(t.clientX - tap.x, t.clientY - tap.y) > 10) tap.moved = true;
                }
            }
            function touchEnd(e) {
                lastTouchAt = Date.now();
                if (armed) { endDraw(e); bumpArmTimer(); return; }
                if (tap && !tap.moved && Date.now() - tap.t < 700) {
                    if (e.cancelable) e.preventDefault();   // evita el clic/mouse "fantasma" que dibujaría un punto
                    arm();
                }
                tap = null;
            }
            function touchCancel(e) {
                if (armed) { endDraw(e); bumpArmTimer(); }
                tap = null;
            }
            // Ignora los eventos de mouse que el navegador sintetiza después de un toque
            const mouseOk = function () { return Date.now() - lastTouchAt > 800; };

            canvas.addEventListener('mousedown', function (e) { if (mouseOk()) startDraw(e); });
            canvas.addEventListener('mousemove', function (e) { if (mouseOk()) draw(e); });
            canvas.addEventListener('mouseup', function (e) { if (mouseOk()) endDraw(e); });
            canvas.addEventListener('mouseleave', endDraw);
            canvas.addEventListener('touchstart', touchStart, { passive: false });
            canvas.addEventListener('touchmove', touchMove, { passive: false });
            canvas.addEventListener('touchend', touchEnd, { passive: false });
            canvas.addEventListener('touchcancel', touchCancel);
            if (!isFullscreen) setPlaceholder(false);
            
            signaturePads[canvasId] = {
                canvas: canvas,
                ctx: ctx,
                strokes: strokes,
                placeholder: placeholder,
                resize: resizeCanvas,
                isEmpty: function() { return strokes.length === 0; },
                destroy: function() { disarm(); },
                toDataURL: function() {
                    if (strokes.length === 0) return null;
                    return canvas.toDataURL('image/png');
                },
                clear: function() {
                    strokes.length = 0;
                    currentStroke = [];
                    var dpr = window.devicePixelRatio || 1;
                    ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
                    if (placeholder) placeholder.classList.remove('hidden');
                },
                undo: function() {
                    strokes.pop();
                    redrawStrokes(canvasId);
                    if (strokes.length === 0 && placeholder) {
                        placeholder.classList.remove('hidden');
                    }
                },
                loadFromDataURL: function(dataURL) {
                    if (!dataURL) return;
                    var img = new Image();
                    img.onload = function() {
                        var dpr = window.devicePixelRatio || 1;
                        ctx.clearRect(0, 0, canvas.width / dpr, canvas.height / dpr);
                        ctx.drawImage(img, 0, 0, canvas.width / dpr, canvas.height / dpr);
                        strokes.push([{x:0,y:0}]);
                        if (placeholder) placeholder.classList.add('hidden');
                    };
                    img.src = dataURL;
                }
            };
            
            resizeCanvas();
            return signaturePads[canvasId];
        }
        
        function redrawStrokes(canvasId) {
            const pad = signaturePads[canvasId];
            if (!pad) return;
            const ctx = pad.ctx;
            const dpr = window.devicePixelRatio || 1;
            // Resetear transform y reaplicar
            ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            ctx.clearRect(0, 0, pad.canvas.width / dpr, pad.canvas.height / dpr);
            ctx.strokeStyle = '#1e3a5f';
            ctx.lineWidth = 2.5;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';
            pad.strokes.forEach(function(stroke) {
                if (stroke.length < 2) return;
                ctx.beginPath();
                ctx.moveTo(stroke[0].x, stroke[0].y);
                for (let i = 1; i < stroke.length; i++) {
                    ctx.lineTo(stroke[i].x, stroke[i].y);
                }
                ctx.stroke();
            });
        }
        
        function clearSignature(canvasId) {
            if (signaturePads[canvasId]) {
                signaturePads[canvasId].clear();
            }
        }
        
        function undoSignature(canvasId) {
            if (signaturePads[canvasId]) {
                signaturePads[canvasId].undo();
            }
        }
        
        function getSignatureData(canvasId) {
            if (signaturePads[canvasId] && !signaturePads[canvasId].isEmpty()) {
                return signaturePads[canvasId].toDataURL();
            }
            return null;
        }
        
        function destroySignaturePad(canvasId) {
            if (signaturePads[canvasId]) {
                if (signaturePads[canvasId].destroy) signaturePads[canvasId].destroy();
                delete signaturePads[canvasId];
            }
        }
        
        // ============= FIRMA EN PANTALLA COMPLETA =============
        let fullscreenSignatureTarget = null;
        
        function openSignatureFullscreen(targetCanvasId) {
            fullscreenSignatureTarget = targetCanvasId;
            
            var isPortrait = window.innerHeight > window.innerWidth;
            
            var overlay = document.createElement('div');
            overlay.id = 'signatureFullscreenOverlay';
            overlay.className = 'signature-fullscreen-overlay' + (isPortrait ? ' sig-rotated' : '');
            overlay.innerHTML = 
                '<div class="sig-fs-header">' +
                    '<h3><i class="fas fa-signature"></i> Firma' + (isPortrait ? ' <span style="font-weight:400;font-size:0.75rem;opacity:0.8">(girada para mayor comodidad)</span>' : '') + '</h3>' +
                    '<button onclick="closeSignatureFullscreen(false)"><i class="fas fa-times"></i> Cancelar</button>' +
                '</div>' +
                '<div class="sig-fs-canvas-wrap">' +
                    '<canvas id="signatureFullscreenCanvas"></canvas>' +
                '</div>' +
                '<div class="sig-fs-actions">' +
                    '<button onclick="clearSignature(\'signatureFullscreenCanvas\')" style="background:#fee2e2;color:#991b1b;"><i class="fas fa-eraser"></i> Borrar</button>' +
                    '<button onclick="undoSignature(\'signatureFullscreenCanvas\')" style="background:#e0e7ff;color:#3730a3;"><i class="fas fa-undo"></i> Deshacer</button>' +
                    '<button onclick="closeSignatureFullscreen(true)" style="background:#16a34a;color:#fff;"><i class="fas fa-check"></i> Confirmar</button>' +
                '</div>';
            
            document.body.appendChild(overlay);
            document.body.style.overflow = 'hidden';
            // Guardar si se abrió rotado para saber al cerrar
            window._sigFsRotated = isPortrait;
            
            function sizeAndInitCanvas() {
                destroySignaturePad('signatureFullscreenCanvas');
                initSignaturePad('signatureFullscreenCanvas', { fullscreen: true, rotated: isPortrait });
            }
            
            setTimeout(function() {
                sizeAndInitCanvas();
                
                var existingPad = signaturePads[targetCanvasId];
                if (existingPad && !existingPad.isEmpty()) {
                    signaturePads['signatureFullscreenCanvas'].loadFromDataURL(existingPad.toDataURL());
                }
            }, 200);
            
            window._sigFsResizeHandler = function() {
                setTimeout(sizeAndInitCanvas, 250);
            };
            window.addEventListener('resize', window._sigFsResizeHandler);
        }
        
        function closeSignatureFullscreen(doConfirm) {
            if (doConfirm && fullscreenSignatureTarget) {
                var fsPad = signaturePads['signatureFullscreenCanvas'];
                
                if (fsPad && !fsPad.isEmpty()) {
                    // getPos ya mapea las coordenadas correctamente,
                    // así que el canvas interno tiene la firma en orientación correcta
                    var finalDataURL = fsPad.toDataURL();
                    
                    if (finalDataURL && signaturePads[fullscreenSignatureTarget]) {
                        signaturePads[fullscreenSignatureTarget].clear();
                        signaturePads[fullscreenSignatureTarget].loadFromDataURL(finalDataURL);
                    }
                }
            }
            
            if (window._sigFsResizeHandler) {
                window.removeEventListener('resize', window._sigFsResizeHandler);
                delete window._sigFsResizeHandler;
            }
            
            destroySignaturePad('signatureFullscreenCanvas');
            var overlay = document.getElementById('signatureFullscreenOverlay');
            if (overlay) overlay.remove();
            document.body.style.overflow = '';
            fullscreenSignatureTarget = null;
            delete window._sigFsRotated;
        }
        
        // ============= PANTALLA COMPLETA (FULLSCREEN API) =============
        async function toggleFullscreen() {
            // En Electron (Desktop) usamos el control nativo de la ventana vía IPC:
            // más confiable que la API de Fullscreen del navegador dentro de una
            // app empaquetada, y además responde al atajo F11 manejado en main.js.
            if (window.prohsAPI && window.prohsAPI.fullscreen) {
                await window.prohsAPI.fullscreen.toggle();
                return;
            }
            // Navegador / Capacitor: API estándar de Fullscreen
            if (!document.fullscreenElement && !document.webkitFullscreenElement) {
                var el = document.documentElement;
                if (el.requestFullscreen) {
                    el.requestFullscreen();
                } else if (el.webkitRequestFullscreen) {
                    el.webkitRequestFullscreen();
                }
            } else {
                if (document.exitFullscreen) {
                    document.exitFullscreen();
                } else if (document.webkitExitFullscreen) {
                    document.webkitExitFullscreen();
                }
            }
        }
        
        function updateFullscreenButton(forcedState) {
            var btn = document.getElementById('btnFullscreen');
            if (!btn) return;
            var isActive = (typeof forcedState === 'boolean')
                ? forcedState
                : !!(document.fullscreenElement || document.webkitFullscreenElement);
            if (isActive) {
                btn.innerHTML = '<i class="fas fa-compress"></i> Desactivar';
                btn.className = 'bg-orange-600 hover:bg-orange-700 text-white px-5 py-3 rounded-lg font-semibold transition text-sm';
            } else {
                btn.innerHTML = '<i class="fas fa-expand"></i> Activar';
                btn.className = 'bg-blue-600 hover:bg-blue-700 text-white px-5 py-3 rounded-lg font-semibold transition text-sm';
            }
        }
        
        document.addEventListener('fullscreenchange', function () { updateFullscreenButton(); });
        document.addEventListener('webkitfullscreenchange', function () { updateFullscreenButton(); });

        // En Electron: mantener el botón sincronizado también cuando la
        // pantalla completa se activa/desactiva por F11 o por controles de Windows.
        if (window.prohsAPI && window.prohsAPI.fullscreen && window.prohsAPI.fullscreen.onChange) {
            window.prohsAPI.fullscreen.onChange(function (isFull) { updateFullscreenButton(isFull); });
        }
        
        // ============= MÓDULO DE AJUSTES =============
        async function loadSettingsView() {
            // Actualizar botón de rendimiento
            updatePerformanceButton();
            var chkIni = document.getElementById('chkInicioMostrar');
            if (chkIni && window.prohsInicio) chkIni.checked = window.prohsInicio.getMostrar();
            
            // Calcular almacenamiento (según backend real: IndexedDB, disco de Electron, o dispositivo)
            try {
                const usage = await Storage.getUsageInfo();
                const infoEl = document.getElementById('storageInfo');
                const barEl = document.getElementById('storageBar');

                if (usage.usedMB !== null && usage.quotaMB) {
                    // Tenemos MB usados y cuota (típico de IndexedDB con navigator.storage.estimate)
                    const pct = Math.min((usage.usedMB / usage.quotaMB) * 100, 100);
                    const color = pct > 80 ? 'text-red-600' : pct > 50 ? 'text-orange-600' : 'text-green-600';
                    if (infoEl) {
                        infoEl.innerHTML = '<p>Espacio utilizado: <strong class="' + color + '">' + usage.usedMB.toFixed(2) + ' MB</strong> de ~' + usage.quotaMB.toFixed(0) + ' MB disponibles</p>' +
                            '<p class="mt-1">Establecimientos: ' + (appData.establishments ? appData.establishments.length : 0) + ' | ' +
                            'Registros totales: ' + countTotalRecords() + '</p>';
                    }
                    if (barEl) {
                        barEl.style.width = pct + '%';
                        barEl.className = 'h-3 rounded-full transition-all ' + (pct > 80 ? 'bg-red-500' : pct > 50 ? 'bg-orange-500' : 'bg-blue-600');
                    }
                } else if (usage.usedMB !== null) {
                    // Tenemos MB usados pero sin cuota fija (Electron: solo limitado por el disco)
                    if (infoEl) {
                        infoEl.innerHTML = '<p>Espacio utilizado: <strong class="text-green-600">' + usage.usedMB.toFixed(2) + ' MB</strong> (' + usage.backend + ', sin límite de navegador)</p>' +
                            '<p class="mt-1">Establecimientos: ' + (appData.establishments ? appData.establishments.length : 0) + ' | ' +
                            'Registros totales: ' + countTotalRecords() + '</p>';
                    }
                    if (barEl) {
                        barEl.style.width = '100%';
                        barEl.className = 'h-3 rounded-full transition-all bg-blue-600';
                    }
                } else {
                    // Sin información de tamaño disponible en este entorno
                    if (infoEl) {
                        infoEl.innerHTML = '<p>Almacenamiento: <strong class="text-green-600">' + usage.backend + '</strong></p>' +
                            '<p class="mt-1">Establecimientos: ' + (appData.establishments ? appData.establishments.length : 0) + ' | ' +
                            'Registros totales: ' + countTotalRecords() + '</p>';
                    }
                    if (barEl) {
                        barEl.style.width = '0%';
                    }
                }
            } catch (e) { console.error('Error al calcular almacenamiento:', e); }
            
            // Info del dispositivo
            var devEl = document.getElementById('deviceInfo');
            if (devEl) {
                var isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
                var cores = navigator.hardwareConcurrency || 'N/D';
                var online = navigator.onLine ? 'Si' : 'No';
                devEl.innerHTML = 
                    '<p><strong>Tipo:</strong> ' + (isMobile ? 'Dispositivo movil' : 'PC / Escritorio') + '</p>' +
                    '<p><strong>Nucleos CPU:</strong> ' + cores + '</p>' +
                    '<p><strong>Conexion:</strong> ' + online + '</p>' +
                    '<p><strong>Pantalla:</strong> ' + screen.width + 'x' + screen.height + 'px</p>' +
                    '<p><strong>Navegador:</strong> ' + navigator.userAgent.split(') ').pop().split('/')[0] + '</p>';
            }
            
            updateFullscreenButton();
        }
        
        function countTotalRecords() {
            var total = 0;
            var arrays = ['inspections', 'actions', 'extinguishers', 'risks', 'trainings', 'incidents', 'ppe', 'jsas', 'chemicals', 'measurements', 'drills', 'contractors', 'maintenances', 'medicals', 'documents', 'vehicles', 'machinery', 'wastes', 'audits', 'surveys', 'nonconformities', 'protocols', 'personnel', 'inductions', 'communications', 'signedDocs', 'envRecs'];
            arrays.forEach(function(key) {
                if (appData[key]) total += appData[key].length;
            });
            return total;
        }
        
        function updatePerformanceButton() {
            var btn = document.getElementById('btnPerformanceSettings');
            var label = document.getElementById('perfModeLabelSettings');
            var status = document.getElementById('perfModeStatus');
            if (!btn) return;
            
            if (performanceMode) {
                btn.className = 'bg-green-600 hover:bg-green-700 text-white px-5 py-3 rounded-lg font-semibold transition text-sm';
                if (label) label.textContent = 'Desactivar';
                if (status) status.innerHTML = '<span class="text-green-600"><i class="fas fa-check-circle"></i> Modo liviano activado - animaciones y efectos deshabilitados</span>';
            } else {
                btn.className = 'bg-gray-500 hover:bg-gray-600 text-white px-5 py-3 rounded-lg font-semibold transition text-sm';
                if (label) label.textContent = 'Activar';
                if (status) status.innerHTML = '<span class="text-gray-400">Modo normal - todos los efectos visuales activos</span>';
            }
        }

        // ============= NAVIGATION =============
        function setActiveSidebarItem(moduleName) {
            // Remover clase active de todos los items
            document.querySelectorAll('.sidebar-nav-item').forEach(function(item) {
                item.classList.remove('active');
            });
            // Agregar clase active al item correspondiente
            const activeItem = document.querySelector('.sidebar-nav-item[data-module="' + moduleName + '"]');
            if (activeItem) {
                activeItem.classList.add('active');
            }
            // Abre la categoría del módulo activo y suma el uso (alimenta "Más usados")
            if (typeof navSyncActive === 'function') {
                navSyncActive(moduleName);
                navRecordUse(moduleName);
            }
        }

        function showHome() {
            // Limpiar módulo activo al volver al inicio
            currentActiveModule = null;
            
            const currentView = document.querySelector('[id$="View"]:not(.hidden):not(#homeView)');
            const homeView = document.getElementById('homeView');
            
            // PREPARAR todos los elementos del home para animación de llenado
            // 1. Títulos
            const titles = homeView.querySelectorAll('h1, h2, h3, .text-2xl, .text-xl');
            titles.forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'translateY(-8px)';
                el.style.transition = 'none';
            });
            
            // 2. Module cards
            const moduleCards = homeView.querySelectorAll('.module-card');
            moduleCards.forEach(card => {
                card.style.opacity = '0';
                card.style.transform = 'scale(0.9) translateY(12px)';
                card.style.transition = 'none';
            });
            
            // 3. Calendario y otros contenedores
            const containers = homeView.querySelectorAll('.bg-white.rounded-lg.shadow-md:not(.module-card), .bg-white.rounded-xl');
            containers.forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'translateY(10px)';
                el.style.transition = 'none';
            });
            
            // 4. Botones
            const buttons = homeView.querySelectorAll('button');
            buttons.forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'scale(0.9)';
                el.style.transition = 'none';
            });
            
            if (currentView) {
                currentView.style.animation = 'slideOutLeft 0.2s ease-out forwards';
                setTimeout(() => {
                    currentView.classList.add('hidden');
                    currentView.style.animation = '';
                    showHomeAnimated();
                }, 200);
            } else {
                hideAllViews();
                showHomeAnimated();
            }
            
            function showHomeAnimated() {
                homeView.classList.remove('hidden');
                homeView.style.animation = 'slideInRight 0.3s ease-out forwards';
                
                // Animar progresivamente (efecto llenado)
                
                // 1. Títulos primero
                titles.forEach((el, index) => {
                    setTimeout(() => {
                        el.style.transition = 'opacity 0.25s ease-out, transform 0.25s ease-out';
                        el.style.opacity = '1';
                        el.style.transform = 'translateY(0)';
                    }, 30 + index * 25);
                });
                
                // 2. Module cards con cascada
                moduleCards.forEach((card, index) => {
                    setTimeout(() => {
                        card.style.transition = 'opacity 0.3s ease-out, transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                        card.style.opacity = '1';
                        card.style.transform = 'scale(1) translateY(0)';
                    }, 80 + index * 30);
                });
                
                // 3. Contenedores (calendario, etc)
                containers.forEach((el, index) => {
                    setTimeout(() => {
                        el.style.transition = 'opacity 0.3s ease-out, transform 0.3s ease-out';
                        el.style.opacity = '1';
                        el.style.transform = 'translateY(0)';
                    }, 200 + index * 50);
                });
                
                // 4. Botones
                buttons.forEach((el, index) => {
                    setTimeout(() => {
                        el.style.transition = 'opacity 0.2s ease-out, transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                        el.style.opacity = '1';
                        el.style.transform = 'scale(1)';
                    }, 150 + index * 20);
                });
                
                setTimeout(() => {
                    homeView.style.animation = '';
                }, 350);
                
                renderMainCalendar();
                updateDashboardIfVisible();
                setActiveSidebarItem('home');
            }
        }

        function showModule(moduleName) {
            // Scroll hacia arriba al abrir cualquier módulo
            window.scrollTo({ top: 0, behavior: 'smooth' });
            
            // Los módulos de gestión de datos y acerca de no requieren establecimiento seleccionado
            if (!currentEstablishment && moduleName !== 'datamanagement' && moduleName !== 'about') {
                alert('Por favor, seleccione un establecimiento primero.');
                return;
            }
            
            // Guardar módulo activo actual
            currentActiveModule = moduleName;
            
            // Obtener vista actual
            const currentView = document.querySelector('[id$="View"]:not(.hidden)');
            const viewId = moduleName + 'View';
            const newView = document.getElementById(viewId);
            
            if (!newView) return;
            
            // PREPARAR todos los elementos para animación de llenado
            prepareElementsForAnimation(newView);
            
            // Si hay vista actual, animarla hacia afuera
            if (currentView && currentView.id !== viewId) {
                currentView.style.animation = 'slideOutLeft 0.2s ease-out forwards';
                setTimeout(() => {
                    currentView.classList.add('hidden');
                    currentView.style.animation = '';
                    showNewView();
                }, 200);
            } else {
                hideAllViews();
                showNewView();
            }
            
            function showNewView() {
                _attnOpen[moduleName] = false; // el cuadro de avisos arranca siempre condensado
                setActiveSidebarItem(moduleName);
                newView.classList.remove('hidden');
                newView.style.animation = 'slideInRight 0.3s ease-out forwards';
                
                // Animar elementos progresivamente (efecto llenado)
                animateModuleElements(newView);
                
                // Limpiar animación del contenedor después
                setTimeout(() => {
                    newView.style.animation = '';
                }, 350);
                
                // Load module-specific data
                switch(moduleName) {
                    case 'checklist': loadInspectionHistory(); break;
                    case 'actions': loadActions(); break;
                    case 'extinguishers': loadExtinguishers(); break;
                    case 'riskmatrix': loadRisks(); break;
                    case 'training': loadTrainings(); break;
                    case 'incidents': loadIncidents(); break;
                    case 'ppe': loadPPE(); break;
                    case 'dashboard': updateDashboard(); break;
                    case 'jsa': loadJSAs(); break;
                    case 'sds': loadChemicals(); break;
                    case 'environmental': loadMeasurements(); break;
                    case 'evacuation': loadDrills(); break;
                    case 'contractors': loadContractors(); break;
                    case 'maintenance': loadMaintenances(); break;
                    case 'medical': loadMedicals(); break;
                    case 'documents': loadDocuments(); break;
                    case 'protocols': loadProtocols(); break;
                    case 'personnel': loadPersonnel(); break;
                    case 'rgrl': initRGRL(); break;
                    case 'rgrlObras': initRGRLObras(); break;
                    case 'niosh': break;
                    case 'datamanagement': populateExportEstablishmentSelect(); break;
                    case 'about': break;
                    case 'settings': loadSettingsView(); break;
                    case 'vehicles': loadVehicles(); break;
                    case 'machinery': loadMachinery(); break;
                    case 'iso9001': calculateISO9001Compliance(); break;
                    case 'waste': loadWastes(); break;
                    case 'ambgest': loadAmbgest(); break;
                    case 'audits': loadAudits(); break;
                    case 'satisfaction': loadSurveys(); break;
                    case 'nonconformity': loadNonconformities(); break;
                }
                // El cuadro "Requiere atención" se arma ya, junto con el resto del
                // módulo, para que entre con la misma animación y no unos
                // instantes después.
                try { if (typeof attnRefresh === 'function') attnRefresh(); } catch (e) { console.warn('[attn]', e); }
            }
        }
        
        // Preparar todos los elementos para animación de llenado
        function prepareElementsForAnimation(container) {
            // 1. Títulos principales (h1, h2, h3)
            const titles = container.querySelectorAll('h1, h2, h3, .text-2xl, .text-xl');
            titles.forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'translateY(-8px)';
                el.style.transition = 'none';
            });
            
            // 2. Cards de estadísticas grandes
            const statCards = container.querySelectorAll('.grid > .bg-white, .grid > .bg-gradient-to-r, .grid > .bg-gradient-to-br, .grid > .rounded-lg, .grid > .rounded-xl');
            statCards.forEach((card, index) => {
                if (index < 12) {
                    card.style.opacity = '0';
                    card.style.transform = 'translateY(15px) scale(0.95)';
                    card.style.transition = 'none';
                }
            });
            
            // 3. Botones
            const buttons = Array.from(container.querySelectorAll('button, .btn')).filter(el => !el.closest('.attn-bar'));
            buttons.forEach(el => {
                el.style.opacity = '0';
                el.style.transform = 'scale(0.9)';
                el.style.transition = 'none';
            });
            
            // 4. Selectores, inputs y filtros
            const inputs = container.querySelectorAll('select, input, .filter, label');
            inputs.forEach(el => {
                el.style.opacity = '0';
                el.style.transition = 'none';
            });
            
            // 5. Tablas completas
            const tables = container.querySelectorAll('table');
            tables.forEach(table => {
                table.style.opacity = '0';
                table.style.transform = 'translateY(10px)';
                table.style.transition = 'none';
            });
            
            // 6. Filas de tablas
            const tableRows = container.querySelectorAll('table tbody tr');
            tableRows.forEach((row, index) => {
                if (index < 15) {
                    row.style.opacity = '0';
                    row.style.transform = 'translateX(-8px)';
                    row.style.transition = 'none';
                }
            });
            
            // 7. Contenedores secundarios
            const containers = container.querySelectorAll('.bg-white.rounded-lg.shadow, .bg-white.rounded-xl.shadow, .bg-gray-50, .border.rounded');
            containers.forEach(el => {
                el.style.opacity = '0';
                el.style.transition = 'none';
            });
        }
        
        // Función para animar elementos progresivamente (efecto llenado)
        function animateModuleElements(container) {
            // 1. Títulos primero (aparecen rápido)
            const titles = container.querySelectorAll('h1, h2, h3, .text-2xl, .text-xl');
            titles.forEach((el, index) => {
                setTimeout(() => {
                    el.style.transition = 'opacity 0.25s ease-out, transform 0.25s ease-out';
                    el.style.opacity = '1';
                    el.style.transform = 'translateY(0)';
                }, 50 + index * 30);
            });
            
            // 2. Cards de estadísticas (con escala)
            const statCards = container.querySelectorAll('.grid > .bg-white, .grid > .bg-gradient-to-r, .grid > .bg-gradient-to-br, .grid > .rounded-lg, .grid > .rounded-xl');
            statCards.forEach((card, index) => {
                if (index < 12) {
                    setTimeout(() => {
                        card.style.transition = 'opacity 0.3s ease-out, transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0) scale(1)';
                    }, 100 + index * 40);
                }
            });
            
            // 3. Botones (pop in)
            const buttons = Array.from(container.querySelectorAll('button, .btn')).filter(el => !el.closest('.attn-bar'));
            buttons.forEach((el, index) => {
                setTimeout(() => {
                    el.style.transition = 'opacity 0.2s ease-out, transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275)';
                    el.style.opacity = '1';
                    el.style.transform = 'scale(1)';
                }, 150 + index * 20);
            });
            
            // 4. Inputs y selectores
            const inputs = container.querySelectorAll('select, input, .filter, label');
            inputs.forEach((el, index) => {
                setTimeout(() => {
                    el.style.transition = 'opacity 0.2s ease-out';
                    el.style.opacity = '1';
                }, 180 + index * 15);
            });
            
            // 5. Tablas (estructura)
            const tables = container.querySelectorAll('table');
            tables.forEach((table, index) => {
                setTimeout(() => {
                    table.style.transition = 'opacity 0.25s ease-out, transform 0.25s ease-out';
                    table.style.opacity = '1';
                    table.style.transform = 'translateY(0)';
                }, 200 + index * 50);
            });
            
            // 6. Filas de tablas (escalonado)
            const tableRows = container.querySelectorAll('table tbody tr');
            tableRows.forEach((row, index) => {
                if (index < 15) {
                    setTimeout(() => {
                        row.style.transition = 'opacity 0.2s ease-out, transform 0.2s ease-out';
                        row.style.opacity = '1';
                        row.style.transform = 'translateX(0)';
                    }, 280 + index * 25);
                }
            });
            
            // 7. Contenedores secundarios
            const containers = container.querySelectorAll('.bg-white.rounded-lg.shadow, .bg-white.rounded-xl.shadow, .bg-gray-50, .border.rounded');
            containers.forEach((el, index) => {
                setTimeout(() => {
                    el.style.transition = 'opacity 0.3s ease-out';
                    el.style.opacity = '1';
                }, 120 + index * 30);
            });
        }

        function hideAllViews() {
            const views = ['homeView', 'newEstablishmentView', 'editEstablishmentView', 'checklistView', 'actionsView', 
                          'fireloadView', 'extinguishersView', 'riskmatrixView', 'trainingView',
                          'incidentsView', 'ppeView', 'dashboardView', 'jsaView', 'sdsView',
                          'environmentalView', 'evacuationView', 'contractorsView', 'maintenanceView',
                          'medicalView', 'nioshView', 'datamanagementView', 'aboutView', 'settingsView', 'documentsView', 'annualPlanView', 'rgrlView', 'rgrlObrasView', 'vehiclesView', 'machineryView', 'iso9001View', 'wasteView', 'ambgestView', 'auditsView', 'satisfactionView', 'nonconformityView', 'protocolsView', 'personnelView'];
            views.forEach(id => {
                const el = document.getElementById(id);
                if (el) {
                    el.classList.add('hidden');
                    el.classList.remove('active', 'exiting', 'module-view');
                }
            });
        }

        // ============= ESTABLISHMENTS =============
        // Navegación en dos niveles:
        //   1) #empresaSidebarSelect (arriba, en el sidebar): lista las
        //      EMPRESAS ("establecimiento madre"). Elegir una acá muestra
        //      directamente sus propios módulos (datos generales de la
        //      empresa), sin necesidad de que aparezca como una opción más
        //      del otro selector.
        //   2) #establishmentSelect (abajo): lista sólo las OBRAS/otros
        //      establecimientos que pertenecen a la empresa elegida arriba.
        //      Dejarlo en blanco equivale a "datos generales de la empresa".
        // El value de cada <option>, en ambos selectores, es el índice en
        // appData.establishments (salvo el valor especial '__orphans__' para
        // obras sin empresa madre válida).
        function populateEmpresaSidebarSelect() {
            const select = document.getElementById('empresaSidebarSelect');
            if (!select) return;
            select.innerHTML = '<option value="">Seleccionar empresa...</option>';

            appData.establishments.forEach((est, idx) => {
                if (!esEmpresa(est)) return;
                const opt = document.createElement('option');
                opt.value = idx;
                opt.textContent = est.nombre;
                select.appendChild(opt);
            });

            // Obras cuya empresa madre no existe: se agrupan bajo un valor
            // especial para no perderlas de vista.
            const hayHuerfanas = appData.establishments.some(e => esObra(e) && !getEmpresaMadre(e));
            if (hayHuerfanas) {
                const opt = document.createElement('option');
                opt.value = '__orphans__';
                opt.textContent = '⚠️ Sin empresa asignada';
                select.appendChild(opt);
            }

            // Reflejar la empresa "dueña" del establecimiento activo (si hay).
            if (currentEstablishment) {
                if (esObra(currentEstablishment) && !getEmpresaMadre(currentEstablishment)) {
                    select.value = '__orphans__';
                } else {
                    const ownerId = getOwnerEmpresaId(currentEstablishment);
                    const ownerIdx = appData.establishments.findIndex(e => e.id === ownerId);
                    select.value = ownerIdx !== -1 ? String(ownerIdx) : '';
                }
            } else {
                select.value = '';
            }
        }

        function populateEstablishments() {
            const select = document.getElementById('establishmentSelect');
            const empresaSelect = document.getElementById('empresaSidebarSelect');
            const empresaVal = empresaSelect ? empresaSelect.value : '';

            if (empresaVal === '') {
                select.innerHTML = '<option value="">Seleccione una empresa arriba...</option>';
                select.disabled = true;
                return;
            }

            if (empresaVal === '__orphans__') {
                select.disabled = false;
                select.innerHTML = '<option value="">Seleccionar obra...</option>';
                appData.establishments.forEach((est, idx) => {
                    if (esObra(est) && !getEmpresaMadre(est)) {
                        const opt = document.createElement('option');
                        opt.value = idx;
                        opt.textContent = est.nombre + ' (obra huérfana)';
                        select.appendChild(opt);
                    }
                });
                if (currentEstablishment) {
                    const idx = appData.establishments.findIndex(e => e.id === currentEstablishment.id);
                    select.value = (idx !== -1 && esObra(currentEstablishment)) ? String(idx) : '';
                } else {
                    select.value = '';
                }
                return;
            }

            const empresa = appData.establishments[empresaVal];
            if (!empresa) {
                select.innerHTML = '<option value="">Seleccione una empresa arriba...</option>';
                select.disabled = true;
                return;
            }

            select.disabled = false;
            select.innerHTML = '<option value="">— Datos generales de ' + empresa.nombre + ' —</option>';
            appData.establishments.forEach((obra, idx) => {
                if (esObra(obra) && obra.empresaPadreId === empresa.id) {
                    const opt = document.createElement('option');
                    opt.value = idx;
                    opt.textContent = obra.nombre;
                    select.appendChild(opt);
                }
            });

            if (currentEstablishment && esObra(currentEstablishment) && currentEstablishment.empresaPadreId === empresa.id) {
                select.value = String(appData.establishments.findIndex(e => e.id === currentEstablishment.id));
            } else {
                select.value = '';
            }
        }

        // Se llama al elegir una empresa en el selector de arriba: repuebla
        // el selector de obras (ahora acotado a esa empresa) y activa
        // directamente los datos generales de la empresa elegida.
        function onEmpresaSidebarChange() {
            const empresaSelect = document.getElementById('empresaSidebarSelect');
            const val = empresaSelect ? empresaSelect.value : '';
            populateEstablishments();
            // Elegir una empresa siempre parte de sus "datos generales": el
            // selector de obras se resetea en blanco aunque, antes de este
            // cambio, hubiera una obra de esa misma empresa seleccionada
            // (populateEstablishments() la habría dejado marcada porque en
            // ese momento currentEstablishment todavía era la obra anterior).
            const bottomSelect = document.getElementById('establishmentSelect');
            if (bottomSelect) bottomSelect.value = '';
            if (val === '' || val === '__orphans__') {
                activateEstablishment(null);
            } else {
                activateEstablishment(appData.establishments[val]);
            }
        }

        // Fija ambos selectores (empresa arriba, obra abajo) para reflejar un
        // establecimiento concreto y lo activa. Se usa después de crear,
        // editar, eliminar o importar establecimientos, y al saltar a uno
        // desde una notificación, para no dejar la UI desincronizada.
        function syncSelectorsToEstablishment(est) {
            const empresaSelect = document.getElementById('empresaSidebarSelect');

            if (!est) {
                populateEmpresaSidebarSelect();
                if (empresaSelect) empresaSelect.value = '';
                populateEstablishments();
                activateEstablishment(null);
                return;
            }

            populateEmpresaSidebarSelect();
            if (esObra(est) && !getEmpresaMadre(est)) {
                if (empresaSelect) empresaSelect.value = '__orphans__';
            } else {
                const ownerId = getOwnerEmpresaId(est);
                const ownerIdx = appData.establishments.findIndex(e => e.id === ownerId);
                if (empresaSelect) empresaSelect.value = ownerIdx !== -1 ? String(ownerIdx) : '';
            }

            populateEstablishments();
            const bottomSelect = document.getElementById('establishmentSelect');
            if (bottomSelect) {
                const estIdx = appData.establishments.findIndex(e => e.id === est.id);
                bottomSelect.value = esEmpresa(est) ? '' : String(estIdx);
            }

            activateEstablishment(est);
        }

        // Muestra/oculta el selector de "empresa a la que pertenece" según el
        // tipo de establecimiento elegido, y completa su required dinámicamente.
        function toggleEmpresaPadreField(tipoSelectEl, containerId, empresaSelectId) {
            const container = document.getElementById(containerId);
            const empresaSelect = document.getElementById(empresaSelectId);
            const esObraSeleccionada = tipoSelectEl.value === 'obra';
            container.classList.toggle('hidden', !esObraSeleccionada);
            if (empresaSelect) empresaSelect.required = esObraSeleccionada;
        }

        // Muestra/oculta el bloque de "Identificación de la obra" (propietario,
        // documento del propietario, nomenclatura catastral) según el tipo de
        // establecimiento elegido: sólo tiene sentido para 'obra', ya que una
        // 'empresa' ya se identifica con su propio CUIT.
        function toggleObraDatosField(tipoSelectEl, containerId) {
            const container = document.getElementById(containerId);
            if (!container) return;
            const esObraSeleccionada = tipoSelectEl.value === 'obra';
            container.classList.toggle('hidden', !esObraSeleccionada);
        }

        // Llena un <select> con las empresas existentes (tipo 'empresa' o sin
        // tipo definido), excluyendo opcionalmente un id (para no permitir que
        // un establecimiento sea padre de sí mismo al editarlo).
        function populateEmpresaPadreSelect(selectId, excludeId, selectedId) {
            const select = document.getElementById(selectId);
            if (!select) return;
            select.innerHTML = '<option value="">Seleccionar empresa...</option>';
            appData.establishments.forEach(function(est) {
                if (!esEmpresa(est) || est.id === excludeId) return;
                const option = document.createElement('option');
                option.value = est.id;
                option.textContent = est.nombre;
                if (selectedId && est.id === selectedId) option.selected = true;
                select.appendChild(option);
            });
        }

        // Se dispara al cambiar el selector de obras/establecimientos (abajo).
        // Un valor vacío ya NO significa "ningún establecimiento": significa
        // "datos generales de la empresa elegida arriba" (si hay alguna
        // elegida), para que la empresa siempre siga mostrando sus módulos
        // al dejar el selector de obras en blanco.
        function loadEstablishment() {
            const idx = document.getElementById('establishmentSelect').value;
            const empresaSelect = document.getElementById('empresaSidebarSelect');
            const empresaVal = empresaSelect ? empresaSelect.value : '';

            if (idx === '') {
                if (empresaVal !== '' && empresaVal !== '__orphans__') {
                    activateEstablishment(appData.establishments[empresaVal]);
                } else {
                    activateEstablishment(null);
                }
                return;
            }

            activateEstablishment(appData.establishments[idx]);
        }

        // Fija currentEstablishment al establecimiento dado (o lo limpia con
        // null) y actualiza toda la UI dependiente: ficha de detalles,
        // resaltado de módulos prioritarios de obra, contexto empresa/obra y
        // recarga de datos del módulo activo. No toca los <select> del
        // sidebar: quien la llama es responsable de dejarlos sincronizados
        // (ver loadEstablishment, onEmpresaSidebarChange, syncSelectorsToEstablishment).
        function activateEstablishment(est) {
            if (!est) {
                currentEstablishment = null;
                document.getElementById('currentEstablishment').classList.add('hidden');
                updateObraPriorityHighlights();
                updateEstablishmentContextUI();
                return;
            }

            // Mostrar loading overlay
            showLoadingOverlay();

            // Simular pequeña demora para que se vea la animación
            setTimeout(() => {
                currentEstablishment = est;
                const details = document.getElementById('establishmentDetails');

                // Crear enlace de Google Maps con la dirección
                const mapsUrl = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(currentEstablishment.direccion)}`;
                const madreActual = getEmpresaMadre(currentEstablishment);

                const fotoHtml = currentEstablishment.foto
                    ? `<div class="md:col-span-2"><button type="button" class="est-hero" onclick="estFotoView()" title="Tocar para ampliar"><img src="${currentEstablishment.foto}" alt="Foto de identificación de ${protoEsc(currentEstablishment.nombre)}"><span class="est-hero-cap"><i class="fas fa-search-plus"></i> Foto de identificación</span></button></div>`
                    : `<div class="md:col-span-2"><button type="button" class="est-hero-add" onclick="editEstablishment()"><i class="fas fa-camera"></i> Agregar foto de identificación <small>(fachada o cartel de obra)</small></button></div>`;
                details.innerHTML = `
                    ${fotoHtml}
                    <div><strong>Nombre:</strong> ${currentEstablishment.nombre}</div>
                    ${esObra(currentEstablishment) ? `<div class="md:col-span-2"><span class="inline-flex items-center px-3 py-1 rounded-full text-sm font-semibold bg-blue-100 text-blue-800"><i class="fas fa-building mr-1"></i> Obra de: ${madreActual ? madreActual.nombre : 'empresa no encontrada'}</span></div>` : `<div class="md:col-span-2"><span class="inline-flex items-center px-3 py-1 rounded-full text-sm font-semibold bg-slate-100 text-slate-800"><i class="fas fa-building mr-1"></i> Empresa</span></div>`}
                    <div><strong>CUIT:</strong> ${currentEstablishment.cuit}</div>
                    <div class="flex items-center gap-2">
                        <span><strong>Dirección:</strong> ${currentEstablishment.direccion}</span>
                        <a href="${mapsUrl}" target="_blank" rel="noopener noreferrer" class="text-blue-600 hover:text-blue-800 text-lg" title="Ver en Google Maps">
                            <i class="fas fa-map-marker-alt"></i>
                        </a>
                    </div>
                    <div><strong>Actividad:</strong> ${currentEstablishment.actividad}</div>
                    <div><strong>Superficie:</strong> ${currentEstablishment.superficie_m2} m²</div>
                    <div><strong>Empleados:</strong> ${currentEstablishment.empleados || 'N/A'}</div>
                    ${currentEstablishment.telefono ? `<div><strong><i class="fas fa-phone text-blue-600"></i> Teléfono:</strong> <a href="tel:${currentEstablishment.telefono}" class="text-blue-600 hover:text-blue-800">${currentEstablishment.telefono}</a></div>` : ''}
                    ${currentEstablishment.email ? `<div><strong><i class="fas fa-envelope text-blue-600"></i> Email:</strong> <a href="mailto:${currentEstablishment.email}" class="text-blue-600 hover:text-blue-800">${currentEstablishment.email}</a></div>` : ''}
                    ${currentEstablishment.obra_construccion ? `<div class="md:col-span-2"><span class="inline-flex items-center px-3 py-1 rounded-full text-sm font-semibold bg-orange-100 text-orange-800"><i class="fas fa-hard-hat mr-1"></i> Obra en Construcción</span></div>` : ''}
                    ${esObra(currentEstablishment) && (currentEstablishment.propietario_obra || currentEstablishment.propietario_documento || currentEstablishment.nomenclatura_catastral) ? `
                    <div class="md:col-span-2 bg-orange-50 border border-orange-200 rounded-lg p-3 mt-1">
                        <div class="text-xs font-bold text-orange-800 mb-1"><i class="fas fa-hard-hat"></i> Identificación de la obra</div>
                        ${currentEstablishment.propietario_obra ? `<div><strong>Propietario:</strong> ${currentEstablishment.propietario_obra}</div>` : ''}
                        ${currentEstablishment.propietario_documento ? `<div><strong>CUIT/DNI propietario:</strong> ${currentEstablishment.propietario_documento}</div>` : ''}
                        ${currentEstablishment.nomenclatura_catastral ? `<div><strong>Nomenclatura catastral:</strong> ${currentEstablishment.nomenclatura_catastral}</div>` : ''}
                    </div>` : ''}
                `;
                document.getElementById('currentEstablishment').classList.remove('hidden');
                updateObraPriorityHighlights();
                updateEstablishmentContextUI();
                sidebarEstSet(true); // ya se eligió: el selector se contrae para dejar lugar al menú

                // Recargar datos del módulo activo si hay uno visible
                if (currentActiveModule) {
                    reloadActiveModuleData(currentActiveModule);
                }

                // Ocultar loading overlay
                hideLoadingOverlay();
            }, 400);
        }

