            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('RESUMEN DEL PROGRAMA', margin, yPos);
            yPos += 7;
            
            doc.setFont(undefined, 'normal');
            doc.setFontSize(9);
            doc.text('Indicadores del programa de capacitacion:', margin, yPos);
