            // DETALLE
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('REGISTRO DETALLADO', margin, yPos);
            yPos += 6;
            
            // Tabla de capacitaciones
            const tableData = trainings.map(training => [
                training.fecha || '',
                training.titulo || '',
                training.instructor || 'N/A',
                `${training.duracion || 0} hs`,
                (training.participantes?.length || 0).toString()
            ]);
            
            doc.autoTable({
                startY: yPos,
                head: [['Fecha', 'Tema', 'Instructor', 'Duracion', 'Asist.']],
                body: tableData,
                theme: 'grid',
                headStyles: { fillColor: [15, 115, 197], textColor: 255, fontSize: 8 },
                styles: { 
                    fontSize: 8, 
                    cellPadding: 2,
                    overflow: 'linebreak',
                    cellWidth: 'wrap'
                },
                columnStyles: {
                    0: { cellWidth: 20 },
                    1: { cellWidth: 68 },
                    2: { cellWidth: 42 },
                    3: { cellWidth: 20, halign: 'center' },
                    4: { cellWidth: 18, halign: 'center' }
                }
            });
            
            yPos = doc.lastAutoTable.finalY + 10;
            
            // Calcular espacio necesario para conclusiones (aprox 40 pts)
            const espacioConclusion = 45;
            
            // CONCLUSIONES - solo agregar página si realmente no hay espacio
            if (yPos + espacioConclusion > pageHeight - 25) {
                doc.addPage();
                yPos = addPdfHeader(doc, 'Registro de Capacitaciones');
            }
            
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('CONCLUSIONES Y RECOMENDACIONES', margin, yPos);
            yPos += 6;
            
