        let _docCat = 'laboralSeguridad', _docEstId = null;
        function loadDocuments() {
            if (!currentEstablishment) return;
            
            // Cargar documentos para cada categoría
            const categories = ['laboralSeguridad', 'habilitacion', 'incendios', 'ambiental', 'sanitario', 'salud', 'complementaria'];
            
            categories.forEach(category => {
                const docs = appData.documents.filter(d => 
                    d.establecimiento_id === currentEstablishment.id && d.categoria === category
                );
                const rank = { faltante: 0, vencido: 1, por_vencer: 2, en_tramite: 3, vigente: 4 };
                docs.sort((a, b) => { const x = docEffectiveStatus(a), y = docEffectiveStatus(b); return (rank[x.estado] - rank[y.estado]) || ((x.dias === null ? 1e9 : x.dias) - (y.dias === null ? 1e9 : y.dias)); });
                displayDocuments(docs, category);
            });
            
            // Mantener la categoría que se estaba mirando (la primera, si es la primera vez o cambió el establecimiento)
            if (_docEstId !== currentEstablishment.id) { _docEstId = currentEstablishment.id; _docCat = 'laboralSeguridad'; _docGroupOpen = null; _rgOpen = false; _rgFilter = 'todos'; const rgc = document.getElementById('rgCard'); if (rgc) rgc.classList.remove('open'); }
            showDocCategory(_docCat);
            
            // Actualizar estadísticas
            updateDocumentStats();
            
            // Guía de requisitos: resumen del encabezado y, si está abierta, la lista
            try { if (_rgOpen) rgRender(); else rgRenderHead(rgCompute()); } catch (e) { console.error('Guía de requisitos:', e); }
        }

        function displayDocuments(documents, category) {
            const container = document.getElementById(`${category}List`);
            if (!container) return;
            
            if (documents.length === 0) {
                container.innerHTML = '<p class="text-gray-500 text-center py-8">No hay documentos registrados en esta categoría</p>';
                return;
            }
            
            container.innerHTML = documents.map(doc => {
                const statusColors = {
                    vigente: 'bg-green-50 border-green-200 text-green-800',
                    por_vencer: 'bg-yellow-50 border-yellow-200 text-yellow-800',
                    vencido: 'bg-red-50 border-red-200 text-red-800',
                    faltante: 'bg-gray-50 border-gray-200 text-gray-800',
                    en_tramite: 'bg-blue-50 border-blue-200 text-blue-800'
                };
                
                const statusIcons = {
                    vigente: '<i class="fas fa-check-circle text-green-600"></i>',
                    por_vencer: '<i class="fas fa-exclamation-triangle text-yellow-600"></i>',
                    vencido: '<i class="fas fa-times-circle text-red-600"></i>',
                    faltante: '<i class="fas fa-inbox"></i>',
                    en_tramite: '<i class="fas fa-sync"></i>'
                };
                
                const statusLabels = {
                    vigente: 'Vigente',
                    por_vencer: 'Por vencer',
                    vencido: 'Vencido',
                    faltante: 'Faltante',
                    en_tramite: 'En trámite'
                };
                
                const eff = docEffectiveStatus(doc);
                const est = statusColors[eff.estado] ? eff.estado : 'vigente';
                let daysUntilExpiration = '';
                if (eff.dias !== null && est !== 'faltante') {
                    if (eff.dias < 0) daysUntilExpiration = `<span class="text-xs text-red-600"> (${attnWhen(eff.dias)})</span>`;
                    else if (eff.dias <= 90) daysUntilExpiration = `<span class="text-xs ${eff.dias <= 30 ? 'text-red-600' : 'text-yellow-600'}"> (${attnWhen(eff.dias)})</span>`;
                }
                const registrado = (doc.estado && doc.estado !== est && ['vigente', 'por_vencer', 'vencido'].indexOf(doc.estado) !== -1)
                    ? `<span class="text-xs text-gray-500"> · figura cargado como «${statusLabels[doc.estado]}», pero la fecha indica ${statusLabels[est].toLowerCase()}</span>` : '';
                
                return `
                    <div class="doc-card border ${statusColors[est]} rounded-lg p-4" data-attn-id="${doc.id}" data-doc-id="${doc.id}">
                        <div class="flex items-start justify-between mb-2 flex-wrap gap-y-2">
                            <div class="doc-card-main">
                                <h4 class="font-bold text-gray-800">${statusIcons[est]} ${doc.tipo}</h4>
                                <div class="text-sm text-gray-600 mt-1 space-y-1">
                                    <div><strong>Estado:</strong> ${statusLabels[est]}${daysUntilExpiration}${registrado}</div>
                                    ${doc.fecha_emision ? `<div><strong>Emisión:</strong> ${formatDate(doc.fecha_emision)}</div>` : ''}
                                    ${doc.fecha_vencimiento ? `<div><strong>Vencimiento:</strong> ${formatDate(doc.fecha_vencimiento)}</div>` : ''}
                                    ${doc.responsable ? `<div><strong>Responsable:</strong> ${doc.responsable}</div>` : ''}
                                    ${doc.numero_expediente ? `<div><strong>Expediente:</strong> ${doc.numero_expediente}</div>` : ''}
                                    ${doc.organismo ? `<div><strong>Organismo:</strong> ${doc.organismo}</div>` : ''}
                                    ${doc.observaciones ? `<div class="mt-2 text-xs italic">${doc.observaciones}</div>` : ''}
                                    ${doc.archivo ? `<div class="mt-2"><button type="button" onclick="viewDocumentFile('${doc.id}')" title="Ver el archivo adjunto" class="inline-flex items-center gap-1 bg-blue-100 hover:bg-blue-200 text-blue-800 text-xs px-2 py-1 rounded max-w-full min-w-0"><i class="fas fa-paperclip flex-shrink-0"></i> <span class="truncate">${protoEsc(doc.archivoNombre || 'Archivo adjunto')}</span></button></div>` : ''}
                                </div>
                            </div>
                            <div class="flex gap-3 ml-auto sm:ml-4 items-center text-lg flex-shrink-0">
                                <button title="Ver la información del documento" onclick="viewDocumentDetail('${doc.id}')" class="text-teal-600 hover:text-teal-800"><i class="fas fa-info-circle"></i></button>
                                ${doc.archivo ? `<button title="Ver archivo adjunto" onclick="viewDocumentFile('${doc.id}')" class="text-indigo-600 hover:text-indigo-800"><i class="fas fa-eye"></i></button>
                                <button title="Descargar archivo adjunto" onclick="downloadDocumentFile('${doc.id}')" class="text-green-600 hover:text-green-800"><i class="fas fa-download"></i></button>` : ''}
                                <button title="Editar" onclick="editDocument('${doc.id}')" class="text-blue-600 hover:text-blue-800"><i class="fas fa-edit"></i></button>
                                <button title="Eliminar" onclick="deleteDocument('${doc.id}')" class="text-red-600 hover:text-red-800"><i class="fas fa-trash"></i></button>
                            </div>
                        </div>
                    </div>
                `;
            }).join('');
        }

        function showDocCategory(category) {
            _docCat = category;
            // Ocultar todas las categorías
            const allCategories = ['laboralSeguridad', 'habilitacion', 'incendios', 'ambiental', 'sanitario', 'salud', 'complementaria'];
            allCategories.forEach(cat => {
                const content = document.getElementById(`docContent-${cat}`);
                const tab = document.getElementById(`tab-${cat}`);
                if (content) content.classList.add('hidden');
                if (tab) {
                    tab.classList.remove('bg-teal-600', 'text-white');
                    tab.classList.add('text-gray-600', 'hover:bg-gray-100');
                }
            });
            
            // Mostrar la categoría seleccionada
            const selectedContent = document.getElementById(`docContent-${category}`);
            const selectedTab = document.getElementById(`tab-${category}`);
            if (selectedContent) selectedContent.classList.remove('hidden');
            if (selectedTab) {
                selectedTab.classList.add('bg-teal-600', 'text-white');
                selectedTab.classList.remove('text-gray-600', 'hover:bg-gray-100');
            }
        }

        function showAddDocument(category, tipo) {
            document.getElementById('documentModalTitle').textContent = 'Agregar Documento';
            document.getElementById('documentForm').reset();
            document.getElementById('documentId').value = '';
            document.getElementById('documentCategory').value = category;
            
            // Cargar tipos de documentos según la categoría
            const typeSelect = document.getElementById('documentType');
            typeSelect.innerHTML = '<option value="">Seleccionar...</option>' +
                documentTypes[category].map(type => 
                    `<option value="${type}"${type === tipo ? ' selected' : ''}>${type}</option>`
                ).join('');
            
            document.getElementById('documentModal').classList.remove('hidden');
        }

        function editDocument(id) {
            const doc = appData.documents.find(d => d.id === id);
            if (!doc) return;
            
            document.getElementById('documentModalTitle').textContent = 'Editar Documento';
            document.getElementById('documentId').value = doc.id;
            document.getElementById('documentCategory').value = doc.categoria;
            
            // Cargar tipos de documentos según la categoría
            const typeSelect = document.getElementById('documentType');
            typeSelect.innerHTML = '<option value="">Seleccionar...</option>' +
                documentTypes[doc.categoria].map(type => 
                    `<option value="${type}" ${type === doc.tipo ? 'selected' : ''}>${type}</option>`
                ).join('');
            
            // Llenar el formulario con los datos del documento
            const form = document.getElementById('documentForm');
            form.elements.tipo.value = doc.tipo;
            form.elements.estado.value = doc.estado;
            form.elements.fecha_emision.value = doc.fecha_emision || '';
            form.elements.fecha_vencimiento.value = doc.fecha_vencimiento || '';
            form.elements.responsable.value = doc.responsable || '';
            form.elements.numero_expediente.value = doc.numero_expediente || '';
            form.elements.organismo.value = doc.organismo || '';
            form.elements.observaciones.value = doc.observaciones || '';
            
            if (doc.archivo) {
                document.getElementById('documentFilePreview').innerHTML = 
                    '<div class="text-xs text-green-600"><i class="fas fa-paperclip"></i> Archivo actual: ' + protoEsc(doc.archivoNombre || '') + ' (se conserva si no subís otro)</div>';
            }
            
            document.getElementById('documentModal').classList.remove('hidden');
        }

        function saveDocument(event) {
            event.preventDefault();
            
            if (!currentEstablishment) {
                alert('Por favor seleccione un establecimiento primero');
                return;
            }
            
            const formData = new FormData(event.target);
            const id = formData.get('id');
            const categoria = formData.get('category');
            
            const docData = {
                id: id || Date.now().toString(),
                establecimiento_id: currentEstablishment.id,
                categoria: categoria,
                tipo: formData.get('tipo'),
                estado: formData.get('estado'),
                fecha_emision: formData.get('fecha_emision'),
                fecha_vencimiento: formData.get('fecha_vencimiento'),
                responsable: formData.get('responsable'),
                numero_expediente: formData.get('numero_expediente'),
                organismo: formData.get('organismo'),
                observaciones: formData.get('observaciones'),
                fecha_registro: new Date().toISOString()
            };
            // al editar se conserva la fecha de registro original y el archivo ya adjunto
            if (id) {
                const prevDoc = (appData.documents || []).find(d => String(d.id) === String(id));
                if (prevDoc) {
                    if (prevDoc.fecha_registro) docData.fecha_registro = prevDoc.fecha_registro;
                    docData.fecha_modificacion = new Date().toISOString();
                }
            }
            
            // Procesar archivo adjunto
            const fileInput = document.getElementById('documentFileInput');
            if (fileInput.files.length > 0) {
                const file = fileInput.files[0];
                if (file.size > 5 * 1024 * 1024) {
                    alert('El archivo es demasiado grande. Máximo 5MB.');
                    return;
                }
                
                const reader = new FileReader();
                reader.onload = function(e) {
                    docData.archivo = e.target.result;
                    docData.archivoNombre = file.name;
                    docData.archivoTipo = file.type;
                    finalizeSaveDocument(docData, id);
                };
                reader.readAsDataURL(file);
            } else {
                // Si estamos editando y no se subió nuevo archivo, mantener el existente
                if (id) {
                    const existingDoc = appData.documents.find(d => d.id === id);
                    if (existingDoc && existingDoc.archivo) {
                        docData.archivo = existingDoc.archivo;
                        docData.archivoNombre = existingDoc.archivoNombre;
                        docData.archivoTipo = existingDoc.archivoTipo;
                    }
                }
                finalizeSaveDocument(docData, id);
            }
        }

        function finalizeSaveDocument(docData, id) {
            if (id) {
                // Actualizar documento existente
                const index = appData.documents.findIndex(d => d.id === id);
                if (index !== -1) {
                    appData.documents[index] = Object.assign({}, appData.documents[index], docData);
                }
            } else {
                // Agregar nuevo documento
                appData.documents.push(docData);
            }
            
            saveData();
            loadDocuments();
            closeDocumentModal();
            
            alert('✅ Documento guardado correctamente');
        }

        async function deleteDocument(id) {
            if (!await appConfirm('¿Está seguro de que desea eliminar este documento?')) return;
            
            appData.documents = appData.documents.filter(d => d.id !== id);
            saveData();
            loadDocuments();
            
            alert('✅ Documento eliminado');
        }

        function closeDocumentModal() {
            document.getElementById('documentModal').classList.add('hidden');
            document.getElementById('documentForm').reset();
            document.getElementById('documentFilePreview').innerHTML = '';
        }

        const DOC_CAT_NAMES = { laboralSeguridad: 'Laboral y H&S', habilitacion: 'Habilitaciones', incendios: 'Incendios', ambiental: 'Ambiental', sanitario: 'Sanitario', salud: 'Salud', complementaria: 'SGC / ISO 9001' };
        let _docGroupOpen = null;
        // Agrupa los documentos del establecimiento con el estado REAL (la fecha manda sobre lo tipeado a mano).
        function docGroups() {
            const g = { ok: [], por_vencer: [], vencido: [], en_tramite: [] };
            if (!currentEstablishment) return g;
            (appData.documents || []).filter(d => d.establecimiento_id === currentEstablishment.id).forEach(doc => {
                const e = docEffectiveStatus(doc);
                const k = e.estado === 'faltante' ? 'vencido' : (e.estado === 'vigente' ? 'ok' : e.estado);
                (g[k] || g.ok).push({ doc: doc, eff: e });
            });
            return g;
        }
        function updateDocumentStats() {
            if (!currentEstablishment) return;
            const g = docGroups();
            const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
            set('docCompleteCount', g.ok.length);
            set('docPendingCount', g.por_vencer.length);
            set('docExpiredCount', g.vencido.length);
            set('docTramiteCount', g.en_tramite.length);
            // contador de problemas en cada pestaña de categoría
            Object.keys(DOC_CAT_NAMES).forEach(cat => {
                const tab = document.getElementById('tab-' + cat);
                if (!tab) return;
                let b = tab.querySelector('.doc-tab-badge');
                const rojos = g.vencido.filter(x => x.doc.categoria === cat).length;
                const ambar = g.por_vencer.filter(x => x.doc.categoria === cat).length;
                if (!rojos && !ambar) { if (b) b.remove(); return; }
                if (!b) { b = document.createElement('span'); tab.appendChild(b); }
                b.className = 'doc-tab-badge ' + (rojos ? 'doc-tab-badge-v' : 'doc-tab-badge-p');
                b.title = [rojos ? rojos + (rojos === 1 ? ' vencido o faltante' : ' vencidos o faltantes') : '', ambar ? ambar + ' por vencer (30 días)' : ''].filter(Boolean).join(' · ');
                b.textContent = rojos + ambar;
            });
            if (_docGroupOpen) renderDocGroupPanel(_docGroupOpen); else {
                const panel = document.getElementById('docGroupPanel'); if (panel) panel.classList.add('hidden');
            }
            ['ok', 'por_vencer', 'vencido', 'en_tramite'].forEach(k => {
                const c = document.getElementById('docCard-' + k);
                if (c) { c.classList.toggle('active', _docGroupOpen === k); c.setAttribute('aria-pressed', _docGroupOpen === k ? 'true' : 'false'); }
            });
        }
        function showDocGroup(key) {
            _docGroupOpen = (_docGroupOpen === key) ? null : key;
            updateDocumentStats();
            if (_docGroupOpen) {
                const panel = document.getElementById('docGroupPanel');
                if (panel) panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
            }
        }
        function renderDocGroupPanel(key) {
            const panel = document.getElementById('docGroupPanel'); if (!panel) return;
            const meta = {
                ok: { t: 'Documentos al día', c: 'green', ic: 'fa-check-circle', vacio: 'No hay documentos al día todavía.' },
                por_vencer: { t: 'Por vencer en los próximos 30 días', c: 'yellow', ic: 'fa-exclamation-triangle', vacio: 'No hay documentos por vencer. 👍' },
                vencido: { t: 'Vencidos o faltantes', c: 'red', ic: 'fa-times-circle', vacio: 'No hay documentos vencidos ni faltantes. 👍' },
                en_tramite: { t: 'En trámite', c: 'blue', ic: 'fa-sync', vacio: 'No hay documentos en trámite.' }
            }[key];
            let list = docGroups()[key].slice();
            list.sort((a, b) => (a.eff.dias === null ? -1e9 : a.eff.dias) - (b.eff.dias === null ? -1e9 : b.eff.dias));
            const rows = list.map(x => {
                const d = x.doc, e = x.eff;
                let when;
                if (e.estado === 'faltante') when = 'Falta presentar';
                else if (e.dias !== null) when = attnWhen(e.dias).replace(/^./, c => c.toUpperCase()) + ' · ' + attnFmt(d.fecha_vencimiento);
                else when = e.estado === 'vencido' ? 'Vencido (sin fecha cargada)' : (e.estado === 'por_vencer' ? 'Por vencer (sin fecha cargada)' : 'Sin fecha de vencimiento');
                return '<div class="doc-group-row">' +
                    '<div class="doc-group-main"><div class="doc-group-title">' + protoEsc(d.tipo) + '</div>' +
                    '<div class="doc-group-sub"><span class="doc-group-cat">' + protoEsc(DOC_CAT_NAMES[d.categoria] || d.categoria) + '</span> ' + protoEsc(when) +
                    (d.responsable ? ' · Resp.: ' + protoEsc(d.responsable) : '') + '</div></div>' +
                    '<div class="doc-group-actions">' +
                    '<button type="button" class="doc-group-link" onclick="docGoTo(\'' + d.id + '\')"><i class="fas fa-arrow-right"></i> Ir al documento</button>' +
                    '<button type="button" class="doc-group-edit" onclick="viewDocumentDetail(\'' + d.id + '\')" title="Ver la información del documento"><i class="fas fa-info-circle"></i></button>' +
                    (d.archivo ? '<button type="button" class="doc-group-edit" onclick="viewDocumentFile(\'' + d.id + '\')" title="Ver archivo adjunto"><i class="fas fa-paperclip"></i></button>' : '') +
                    '<button type="button" class="doc-group-edit" onclick="editDocument(\'' + d.id + '\')" title="Editar"><i class="fas fa-edit"></i></button></div></div>';
            }).join('');
            panel.className = 'doc-group-panel doc-group-' + meta.c;
            panel.innerHTML = '<div class="doc-group-head"><span><i class="fas ' + meta.ic + '"></i> ' + meta.t + ' (' + list.length + ')</span>' +
                '<button type="button" onclick="showDocGroup(\'' + key + '\')" class="doc-group-close" title="Cerrar"><i class="fas fa-times"></i></button></div>' +
                (rows || '<p class="doc-group-empty">' + meta.vacio + '</p>');
        }
        // ---------- Ficha del documento y visor del archivo adjunto ----------
        function docFindById(id) { return (appData.documents || []).find(d => String(d.id) === String(id)); }
        function docFileKind(d) {
            const t = String((d && d.archivoTipo) || '').toLowerCase();
            const n = String((d && d.archivoNombre) || '').toLowerCase();
            if (t.indexOf('image/') === 0 || /\.(png|jpe?g|gif|webp|bmp)$/.test(n)) return 'image';
            if (t === 'application/pdf' || /\.pdf$/.test(n)) return 'pdf';
            return 'other';
        }
        function docFileSizeText(d) {
            const data = String((d && d.archivo) || '');
            const i = data.indexOf(',');
            if (i < 0) return '';
            const bytes = Math.floor((data.length - i - 1) * 3 / 4);
            return bytes >= 1048576 ? (bytes / 1048576).toFixed(1).replace('.', ',') + ' MB' : Math.max(1, Math.round(bytes / 1024)) + ' KB';
        }
        function docFileName(d) { return d.archivoNombre || ((d.tipo || 'documento').replace(/[^\wáéíóúñÁÉÍÓÚÑ ]+/g, '').replace(/\s+/g, '_') + '.pdf'); }

        function viewDocumentDetail(id) {
            const d = docFindById(id);
            if (!d) { alert('No se encontró el documento'); return; }
            const eff = docEffectiveStatus(d);
            const labels = { vigente: 'Vigente', por_vencer: 'Por vencer', vencido: 'Vencido', faltante: 'Faltante', en_tramite: 'En trámite' };
            const colors = { vigente: 'bg-green-100 text-green-800', por_vencer: 'bg-yellow-100 text-yellow-800', vencido: 'bg-red-100 text-red-800', faltante: 'bg-gray-200 text-gray-800', en_tramite: 'bg-blue-100 text-blue-800' };
            const icons = { vigente: 'fa-check-circle', por_vencer: 'fa-exclamation-triangle', vencido: 'fa-times-circle', faltante: 'fa-inbox', en_tramite: 'fa-sync' };
            const est = labels[eff.estado] ? eff.estado : 'vigente';
            let cuando = '';
            if (eff.dias !== null && est !== 'faltante') cuando = ' · ' + attnWhen(eff.dias);
            const fmtTs = ts => { if (!ts) return ''; const x = new Date(ts); return isNaN(x) ? '' : x.toLocaleDateString('es-AR') + ' ' + x.toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' }); };
            const field = (label, value) => value ? '<div class="bg-gray-50 rounded-lg p-3"><div class="text-xs font-semibold text-gray-500 uppercase tracking-wide">' + label + '</div><div class="text-sm text-gray-800 mt-1 break-words">' + protoEsc(value) + '</div></div>' : '';
            const registrado = (d.estado && d.estado !== est && ['vigente', 'por_vencer', 'vencido'].indexOf(d.estado) !== -1)
                ? '<p class="text-xs text-gray-500 mt-2">Figura cargado como «' + labels[d.estado] + '», pero la fecha de vencimiento indica ' + labels[est].toLowerCase() + '.</p>' : '';
            const archivoHtml = d.archivo
                ? '<div class="border border-blue-200 bg-blue-50 rounded-lg p-4 flex flex-wrap items-center justify-between gap-3">' +
                    '<div class="min-w-0"><div class="text-sm font-semibold text-blue-900 truncate"><i class="fas fa-paperclip"></i> ' + protoEsc(d.archivoNombre || 'Archivo adjunto') + '</div>' +
                    '<div class="text-xs text-blue-700 mt-1">' + (docFileSizeText(d) ? docFileSizeText(d) : '') + '</div></div>' +
                    '<div class="flex gap-2"><button type="button" onclick="viewDocumentFile(\'' + d.id + '\')" class="bg-indigo-600 hover:bg-indigo-700 text-white px-3 py-2 rounded-lg text-sm font-semibold transition"><i class="fas fa-eye"></i> Ver archivo</button>' +
                    '<button type="button" onclick="downloadDocumentFile(\'' + d.id + '\')" class="bg-green-600 hover:bg-green-700 text-white px-3 py-2 rounded-lg text-sm font-semibold transition"><i class="fas fa-download"></i> Descargar</button></div></div>'
                : '<div class="border border-dashed border-gray-300 rounded-lg p-4 text-sm text-gray-500"><i class="fas fa-paperclip"></i> Todavía no hay un archivo adjunto. Podés cargarlo desde «Editar».</div>';
            const contenido =
                '<div class="space-y-4">' +
                    '<div><div class="text-xs font-semibold text-gray-500 uppercase tracking-wide">' + protoEsc(DOC_CAT_NAMES[d.categoria] || d.categoria || '') + '</div>' +
                    '<h3 class="text-xl sm:text-2xl font-bold text-gray-800 mt-1">' + protoEsc(d.tipo || 'Documento') + '</h3>' +
                    '<span class="inline-block mt-2 px-3 py-1 rounded-full text-sm font-semibold ' + colors[est] + '"><i class="fas ' + icons[est] + '"></i> ' + labels[est] + protoEsc(cuando) + '</span>' + registrado + '</div>' +
                    '<div class="grid sm:grid-cols-2 gap-3">' +
                        field('Emisión', d.fecha_emision ? formatDate(d.fecha_emision) : '') +
                        field('Vencimiento', d.fecha_vencimiento ? formatDate(d.fecha_vencimiento) : '') +
                        field('Responsable', d.responsable) +
                        field('N° de expediente', d.numero_expediente) +
                        field('Organismo', d.organismo) +
                        field('Establecimiento', attnEstName(d.establecimiento_id)) +
                    '</div>' +
                    (d.observaciones ? '<div class="bg-blue-50 rounded-lg p-4"><div class="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-1">Observaciones</div><p class="text-sm text-gray-700 whitespace-pre-wrap">' + protoEsc(d.observaciones) + '</p></div>' : '') +
                    archivoHtml +
                    '<div class="text-xs text-gray-400">' + (fmtTs(d.fecha_registro) ? 'Registrado: ' + fmtTs(d.fecha_registro) : '') + (fmtTs(d.fecha_modificacion) ? ' · Modificado: ' + fmtTs(d.fecha_modificacion) : '') + '</div>' +
                    '<div class="flex flex-wrap justify-end gap-2 pt-2 border-t border-gray-200">' +
                        '<button type="button" onclick="closeDocumentDetail(); editDocument(\'' + d.id + '\')" class="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-semibold transition"><i class="fas fa-edit"></i> Editar</button>' +
                        '<button type="button" onclick="closeDocumentDetail()" class="bg-gray-200 hover:bg-gray-300 text-gray-800 px-4 py-2 rounded-lg font-semibold transition">Cerrar</button>' +
                    '</div>' +
                '</div>';
            document.getElementById('documentDetailContent').innerHTML = contenido;
            openModalAnimated('documentDetailModal');
        }
        function closeDocumentDetail() { closeModalAnimated('documentDetailModal'); }

        function downloadDocumentFile(id) {
            const d = docFindById(id);
            if (!d || !d.archivo) { alert('Este documento no tiene archivo adjunto'); return; }
            downloadStoredFile(d.archivo, docFileName(d));
        }

        let _docViewerUrl = null;
        // Visor en pantalla de cualquier archivo guardado (data URI): PDF e imágenes se ven
        // dentro de la app; otros formatos (Word, etc.) se descargan / comparten.
        function storedFileKind(nombre, tipo, dataUri) {
            const t = String(tipo || '').toLowerCase();
            const n = String(nombre || '').toLowerCase();
            const head = String(dataUri || '').substring(0, 40).toLowerCase();
            if (t.indexOf('image/') === 0 || /\.(png|jpe?g|gif|webp|bmp)$/.test(n) || head.indexOf('data:image/') === 0) return 'image';
            if (t === 'application/pdf' || /\.pdf$/.test(n) || head.indexOf('data:application/pdf') === 0) return 'pdf';
            return 'other';
        }
        function viewStoredFile(dataUri, nombre, tipo) {
            if (!dataUri) { alert('Este registro no tiene archivo adjunto'); return; }
            nombre = nombre || 'archivo';
            const kind = storedFileKind(nombre, tipo, dataUri);
            const isNative = window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform();
            // En el celular no hay visor de PDF incrustado: se abre con la app del teléfono (compartir / abrir con)
            if (kind === 'other') { downloadStoredFile(dataUri, nombre); return; }
            const usePdfJs = kind === 'pdf' && (isNative || window.PROHS_FORCE_PDFJS);
            const body = document.getElementById('docFileViewerBody');
            document.getElementById('docFileViewerTitle').innerHTML = '<i class="fas fa-paperclip"></i> ' + protoEsc(nombre);
            document.getElementById('docFileViewerDownload').onclick = function () { downloadStoredFile(dataUri, nombre); };
            body.innerHTML = '';
            try {
                if (kind === 'image') {
                    const img = document.createElement('img');
                    img.src = dataUri; img.alt = nombre;
                    img.className = 'max-w-full max-h-full object-contain';
                    body.appendChild(img);
                } else if (usePdfJs) {
                    // Celular: el WebView no trae visor de PDF incrustado, así que se dibuja con PDF.js (incluido en libs/pdfjs)
                    body.innerHTML = '<div class="text-gray-500 text-sm p-6"><i class="fas fa-spinner fa-spin"></i> Cargando PDF…</div>';
                    renderPdfInViewer(dataUri, body).catch(function (e) {
                        console.error('[visor PDF.js]', e);
                        closeDocFileViewer();
                        downloadStoredFile(dataUri, nombre);
                    });
                } else {
                    const bin = atob(dataUri.substring(dataUri.indexOf(',') + 1));
                    const bytes = new Uint8Array(bin.length);
                    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                    if (_docViewerUrl) { URL.revokeObjectURL(_docViewerUrl); _docViewerUrl = null; }
                    _docViewerUrl = URL.createObjectURL(new Blob([bytes], { type: 'application/pdf' }));
                    const frame = document.createElement('iframe');
                    frame.src = _docViewerUrl; frame.title = nombre;
                    frame.className = 'w-full h-full border-0 bg-white';
                    body.appendChild(frame);
                }
            } catch (e) {
                console.error('[visor de archivo]', e);
                downloadStoredFile(dataUri, nombre);
                return;
            }
            openModalAnimated('docFileViewerModal');
        }
        // ---------- PDF.js (visor de PDF propio para el celular) ----------
        let _pdfjsLoading = null, _pdfjsDoc = null, _pdfjsToken = 0;
        function loadPdfJs() {
            if (window.pdfjsLib) return Promise.resolve(window.pdfjsLib);
            if (_pdfjsLoading) return _pdfjsLoading;
            _pdfjsLoading = new Promise(function (resolve, reject) {
                const sc = document.createElement('script');
                sc.src = 'libs/pdfjs/pdf.min.js';
                sc.onload = function () {
                    window.pdfjsLib.GlobalWorkerOptions.workerSrc = 'libs/pdfjs/pdf.worker.min.js';
                    resolve(window.pdfjsLib);
                };
                sc.onerror = function () { _pdfjsLoading = null; reject(new Error('No se pudo cargar PDF.js')); };
                document.head.appendChild(sc);
            });
            return _pdfjsLoading;
        }
        function destroyPdfViewer() {
            _pdfjsToken++;
            if (_pdfjsDoc) { try { _pdfjsDoc.destroy(); } catch (e) { /* noop */ } _pdfjsDoc = null; }
        }
        async function renderPdfInViewer(dataUri, body) {
            const token = ++_pdfjsToken;
            const lib = await loadPdfJs();
            const bin = atob(dataUri.substring(dataUri.indexOf(',') + 1));
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
            if (_pdfjsDoc) { try { _pdfjsDoc.destroy(); } catch (e) { /* noop */ } _pdfjsDoc = null; }
            const pdf = await lib.getDocument({ data: bytes }).promise;
            if (token !== _pdfjsToken) { try { pdf.destroy(); } catch (e) { /* noop */ } return; }
            _pdfjsDoc = pdf;

            body.innerHTML = '';
            body.style.alignItems = 'stretch';
            const wrap = document.createElement('div');
            wrap.className = 'pdfjs-wrap';
            const pages = document.createElement('div');
            pages.className = 'pdfjs-pages';
            const bar = document.createElement('div');
            bar.className = 'pdfjs-bar';
            bar.innerHTML = '<button type="button" class="pdfjs-btn" data-act="out" aria-label="Alejar"><i class="fas fa-minus"></i></button>' +
                '<span class="pdfjs-info">1 / ' + pdf.numPages + '</span>' +
                '<button type="button" class="pdfjs-btn" data-act="in" aria-label="Acercar"><i class="fas fa-plus"></i></button>';
            wrap.appendChild(pages); body.appendChild(wrap); body.appendChild(bar);

            let zoom = 1;
            const dpr = Math.min(window.devicePixelRatio || 1, 2);
            const slots = [];
            const infoEl = bar.querySelector('.pdfjs-info');
            const baseW = function () { return Math.max(200, wrap.clientWidth - 16); };

            function layout() {
                const w = baseW() * zoom;
                slots.forEach(function (sl) {
                    const k = w / sl.w1;
                    sl.el.style.width = Math.round(w) + 'px';
                    sl.el.style.height = Math.round(sl.h1 * k) + 'px';
                    sl.scale = k;
                    if (sl.canvas) { sl.canvas.remove(); sl.canvas = null; }
                    sl.state = 0; sl.gen = (sl.gen || 0) + 1;
                });
                renderVisible();
            }
            async function renderSlot(sl) {
                if (sl.state) return; sl.state = 1;
                const gen = sl.gen || 0;
                const page = await pdf.getPage(sl.n);
                if (token !== _pdfjsToken) return;
                const vp = page.getViewport({ scale: sl.scale * dpr });
                const cv = document.createElement('canvas');
                cv.width = Math.floor(vp.width); cv.height = Math.floor(vp.height);
                cv.style.width = '100%'; cv.style.height = '100%'; cv.style.display = 'block';
                await page.render({ canvasContext: cv.getContext('2d'), viewport: vp }).promise;
                if (token !== _pdfjsToken || sl.state !== 1 || (sl.gen || 0) !== gen) return;
                sl.el.innerHTML = ''; sl.el.appendChild(cv); sl.canvas = cv; sl.state = 2;
            }
            function renderVisible() {
                const top = wrap.scrollTop, h = wrap.clientHeight;
                let cur = 1;
                slots.forEach(function (sl) {
                    const y = sl.el.offsetTop - pages.offsetTop, b = y + sl.el.offsetHeight;
                    if (y <= top + h / 3) cur = sl.n;
                    if (b > top - h && y < top + h * 2) renderSlot(sl).catch(function (e) { console.error('[PDF.js página]', e); });
                });
                infoEl.textContent = cur + ' / ' + pdf.numPages + (zoom !== 1 ? ' · ' + Math.round(zoom * 100) + '%' : '');
            }
            for (let n = 1; n <= pdf.numPages; n++) {
                const pg = await pdf.getPage(n);
                if (token !== _pdfjsToken) return;
                const v = pg.getViewport({ scale: 1 });
                const el = document.createElement('div');
                el.className = 'pdfjs-page';
                pages.appendChild(el);
                slots.push({ n: n, el: el, w1: v.width, h1: v.height, scale: 1, state: 0, canvas: null });
            }
            wrap.addEventListener('scroll', renderVisible, { passive: true });
            bar.addEventListener('click', function (e) {
                const b = e.target.closest('button[data-act]'); if (!b) return;
                const old = zoom;
                zoom = Math.max(1, Math.min(4, zoom + (b.getAttribute('data-act') === 'in' ? 0.5 : -0.5)));
                if (zoom !== old) layout();
            });
            // Pellizcar para ampliar
            let d0 = 0, z0 = 1;
            const dist = function (t) { return Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY); };
            wrap.addEventListener('touchstart', function (e) { if (e.touches.length === 2) { d0 = dist(e.touches); z0 = zoom; } }, { passive: true });
            wrap.addEventListener('touchend', function (e) {
                if (d0 && e.touches.length < 2) {
                    d0 = 0; renderVisible();
                }
            }, { passive: true });
            wrap.addEventListener('touchmove', function (e) {
                if (e.touches.length === 2 && d0) {
                    const nz = Math.max(1, Math.min(4, z0 * dist(e.touches) / d0));
                    if (Math.abs(nz - zoom) > 0.04) { zoom = nz; layout(); }
                }
            }, { passive: true });
            layout();
        }

        function viewDocumentFile(id) {
            const d = docFindById(id);
            if (!d || !d.archivo) { alert('Este documento no tiene archivo adjunto'); return; }
            viewStoredFile(d.archivo, docFileName(d), d.archivoTipo);
        }
        function closeDocFileViewer() {
            closeModalAnimated('docFileViewerModal', function () {
                destroyPdfViewer();
                const vb = document.getElementById('docFileViewerBody'); vb.innerHTML = ''; vb.style.alignItems = '';
                if (_docViewerUrl) { URL.revokeObjectURL(_docViewerUrl); _docViewerUrl = null; }
                const det = document.getElementById('documentDetailModal');
                if (det && !det.classList.contains('hidden')) document.body.style.overflow = 'hidden';
            });
        }

        function docGoTo(id) {
            const d = (appData.documents || []).find(x => String(x.id) === String(id));
            if (!d) return;
            showDocCategory(d.categoria);
            setTimeout(function () {
                const el = document.querySelector('#documentsView [data-doc-id="' + id + '"]');
                if (el) attnFlash(el);
            }, 80);
        }

        // ============= GUÍA DE REQUISITOS Y HABILITACIONES (por provincia y rubro) =============
        // Datos en js/requisitos.js (REQ_PROVS, REQ_RUBROS, REQ_ITEMS). Es una guía
        // orientativa: cruza lo que "debería tener" el establecimiento con lo que ya
        // está cargado en Gestión Documental y en los módulos de PROHS.
        let _rgOpen = false, _rgFilter = 'todos';

        function rgNorm(t) { return String(t || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); }

        function rgGuess() {
            const est = currentEstablishment || {};
            const txt = rgNorm((est.direccion || '') + ' ' + (est.nombre || ''));
            let prov = '';
            if (/caba|capital federal|ciudad autonoma|ciudad de buenos aires/.test(txt)) prov = 'caba';
            else {
                const hit = REQ_PROVS.filter(p => p.k !== 'caba').find(p => txt.indexOf(rgNorm(p.n)) !== -1);
                if (hit) prov = hit.k;
            }
            let rubros = [];
            if (est.obra_construccion || est.tipo === 'obra') rubros.push('construccion');
            else {
                const act = rgNorm(est.actividad || '');
                const sc = [];
                if (act) REQ_RUBROS.forEach(function (r) {
                    if (r.k === 'construccion') return;
                    const n = rgNorm(r.h).split(/\s+/).filter(w => w.length > 3 && act.indexOf(w) !== -1).length;
                    if (n) sc.push({ k: r.k, n: n });
                });
                const best = sc.reduce((m, x) => Math.max(m, x.n), 0);
                rubros = sc.filter(x => x.n === best).map(x => x.k);
            }
            return { prov: prov, rubros: rubros.slice(0, 2) };
        }

        function rgRecord(create) {
            if (!currentEstablishment) return null;
            if (!Array.isArray(appData.reqGuide)) appData.reqGuide = [];
            let r = appData.reqGuide.find(x => String(x.establecimiento_id) === String(currentEstablishment.id));
            if (!r && create) {
                const g = rgGuess();
                r = { id: 'rg-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6), establecimiento_id: currentEstablishment.id, provincia: g.prov, rubros: g.rubros, estados: {}, actualizado: new Date().toISOString() };
                appData.reqGuide.push(r);
            }
            return r || null;
        }
        function rgView() {
            const r = rgRecord(false);
            if (r) return { prov: r.provincia || '', rubros: r.rubros || [], estados: r.estados || {}, guessed: false };
            const g = rgGuess();
            return { prov: g.prov, rubros: g.rubros, estados: {}, guessed: !!(g.prov || g.rubros.length) };
        }
        function rgSave(r) { r.actualizado = new Date().toISOString(); saveData(); }

        function rgItemsFor(view) {
            const prov = REQ_PROVS.find(p => p.k === view.prov);
            return REQ_ITEMS.filter(it => !it.r || it.r.some(k => view.rubros.indexOf(k) !== -1)).map(function (it) {
                const o = Object.assign({}, it);
                if (it.nk && prov) o.n = prov[it.nk];
                return o;
            });
        }

        // Estado automático según lo cargado en la app.
        function rgAuto(it) {
            const estId = currentEstablishment.id;
            if (it.m) {
                const docs = (appData.documents || []).filter(d => String(d.establecimiento_id) === String(estId) && it.m.test(d.tipo || ''));
                if (docs.length) {
                    const sts = docs.map(d => docEffectiveStatus(d).estado);
                    const st = sts.indexOf('vigente') !== -1 ? 'ok' : sts.indexOf('por_vencer') !== -1 ? 'warn' : sts.indexOf('en_tramite') !== -1 ? 'tramite' : sts.indexOf('faltante') !== -1 && sts.every(x => x === 'faltante') ? 'falta' : 'venc';
                    return { st: st, docs: docs };
                }
            }
            if (it.mc) {
                let rows = (appData[it.mc[0]] || []).filter(x => String(x.establecimiento_id) === String(estId));
                if (it.mc[1]) rows = rows.filter(x => new RegExp(it.mc[1], 'i').test(x.tipo || ''));
                if (rows.length) return { st: 'ok', n: rows.length };
            }
            return { st: 'falta' };
        }
        function rgEval(it, estados) {
            const man = estados[it.id];
            const a = rgAuto(it);
            if (man === 'na') return { st: 'na', man: man, auto: a };
            if (man === 'cumple') return { st: 'ok', man: man, auto: a };
            if (man === 'tramite') return { st: 'tramite', man: man, auto: a };
            return { st: a.st, man: '', auto: a };
        }
        const RG_ST = {
            ok: ['Cumple', 'fa-check-circle'], warn: ['Por vencer', 'fa-exclamation-triangle'], venc: ['Vencido', 'fa-times-circle'],
            tramite: ['En trámite', 'fa-sync'], falta: ['Falta', 'fa-circle'], na: ['No aplica', 'fa-ban']
        };
        const RG_LV = { nacional: ['Nacional', 'fa-flag'], provincial: ['Provincial', 'fa-map-marker-alt'], municipal: ['Municipal', 'fa-city'] };

        function rgToggle(force) {
            if (!currentEstablishment) return;
            _rgOpen = typeof force === 'boolean' ? force : !_rgOpen;
            const card = document.getElementById('rgCard');
            if (!card) return;
            if (_rgOpen) rgRender();
            card.classList.toggle('open', _rgOpen);
            const head = document.getElementById('rgHead');
            if (head) head.setAttribute('aria-expanded', _rgOpen ? 'true' : 'false');
        }

        function rgSetProv(k) {
            const r = rgRecord(true); const v = rgView();
            r.provincia = k; r.rubros = v.rubros.slice();
            rgSave(r); rgRender();
        }
        function rgToggleRubro(k) {
            const r = rgRecord(true); const v = rgView();
            r.provincia = v.prov;
            const i = r.rubros.indexOf(k);
            if (i === -1) r.rubros.push(k); else r.rubros.splice(i, 1);
            rgSave(r); rgRender();
        }
        function rgSetState(id, val) {
            const r = rgRecord(true); const v = rgView();
            if (!r.provincia) r.provincia = v.prov;
            if (!r.rubros || !r.rubros.length) r.rubros = v.rubros.slice();
            if (!r.estados) r.estados = {};
            if (val) r.estados[id] = val; else delete r.estados[id];
            rgSave(r); rgRender();
        }
        function rgSetFilter(f) { _rgFilter = f; rgRender(); }
        function rgAddDoc(id) {
            const it = REQ_ITEMS.find(x => x.id === id); if (!it) return;
            const cat = it.c;
            showDocCategory(cat);
            showAddDocument(cat, it.dt || '');
        }
        function rgGo(mod) { if (mod === 'rgrl' && currentEstablishment && currentEstablishment.obra_construccion) mod = 'rgrlObras'; showModule(mod); }
        function rgOpenDocs(id) {
            const it = REQ_ITEMS.find(x => x.id === id); if (!it) return;
            const a = rgAuto(it);
            if (a.docs && a.docs[0]) { showDocCategory(a.docs[0].categoria); const d = a.docs[0]; setTimeout(function () { const el = document.querySelector('#documentsView [data-doc-id="' + d.id + '"]'); if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } }, 60); }
        }

        function rgCompute() {
            const v = rgView();
            const items = (v.prov && v.rubros.length) ? rgItemsFor(v) : [];
            const rows = items.map(it => ({ it: it, ev: rgEval(it, v.estados) }));
            const cnt = { ok: 0, warn: 0, venc: 0, tramite: 0, falta: 0, na: 0 };
            rows.forEach(r => { cnt[r.ev.st]++; });
            const applic = rows.length - cnt.na;
            const done = cnt.ok + cnt.warn;
            return { v: v, rows: rows, cnt: cnt, applic: applic, done: done, pct: applic ? Math.round(done * 100 / applic) : 0 };
        }

        function rgRenderHead(c) {
            const el = document.getElementById('rgHeadSummary'); if (!el) return;
            if (!c.rows.length) { el.innerHTML = '<span class="rg-pill rg-pill-idle">Elegí provincia y rubro</span>'; return; }
            const faltan = c.cnt.falta + c.cnt.venc;
            el.innerHTML = '<span class="rg-pill ' + (faltan ? 'rg-pill-bad' : 'rg-pill-ok') + '">' + (faltan ? faltan + ' por revisar' : 'Todo cubierto') + '</span>';
        }

        function rgRender() {
            const body = document.getElementById('rgBody');
            if (!body || !currentEstablishment) return;
            const c = rgCompute(); const v = c.v;
            const prov = REQ_PROVS.find(p => p.k === v.prov);
            const rubroTxt = v.rubros.map(k => (REQ_RUBROS.find(r => r.k === k) || {}).n).filter(Boolean).join(' + ');
            let h = '<p class="rg-intro">Elegí <strong>dónde</strong> está la obra o la empresa y <strong>qué rubro</strong> es: la guía lista los requisitos y habilitaciones habituales y los cruza con lo que ya cargaste, para que veas qué puede estar faltando.</p>';
            h += '<div class="rg-controls"><label class="rg-field"><span>Provincia</span><select onchange="rgSetProv(this.value)" aria-label="Provincia"><option value="">Seleccionar…</option>' +
                REQ_PROVS.map(p => '<option value="' + p.k + '"' + (p.k === v.prov ? ' selected' : '') + '>' + protoEsc(p.n) + '</option>').join('') + '</select></label>' +
                '<div class="rg-field rg-field-wide"><span>Rubro <em>(podés elegir más de uno)</em></span><div class="rg-chips">' +
                REQ_RUBROS.map(r => '<button type="button" class="rg-chip' + (v.rubros.indexOf(r.k) !== -1 ? ' on' : '') + '" onclick="rgToggleRubro(\'' + r.k + '\')" aria-pressed="' + (v.rubros.indexOf(r.k) !== -1) + '"><i class="fas ' + r.ic + '"></i> ' + protoEsc(r.n) + '</button>').join('') + '</div></div></div>';
            if (v.guessed) h += '<p class="rg-hint"><i class="fas fa-magic"></i> Selección sugerida a partir de la dirección y la actividad del establecimiento. Cambiala si no coincide.</p>';

            if (!c.rows.length) {
                h += '<div class="rg-empty"><i class="fas fa-hand-point-up"></i> Seleccioná una provincia y al menos un rubro para ver el listado.</div>';
                body.innerHTML = h; rgRenderHead(c); return;
            }

            // Resumen
            h += '<div class="rg-summary"><div class="rg-sum-top"><div><strong>' + protoEsc(prov ? prov.n : '') + '</strong> · ' + protoEsc(rubroTxt) + '</div><div class="rg-pct">' + c.pct + '% cubierto</div></div>' +
                '<div class="rg-bar" role="progressbar" aria-valuenow="' + c.pct + '" aria-valuemin="0" aria-valuemax="100"><i style="width:' + c.pct + '%"></i></div>' +
                '<div class="rg-counts">' +
                ['ok', 'warn', 'venc', 'tramite', 'falta', 'na'].map(k => '<span class="rg-count rg-c-' + k + '"><b>' + c.cnt[k] + '</b> ' + RG_ST[k][0] + '</span>').join('') + '</div></div>';

            // Normativa ambiental de la provincia
            if (prov) {
                h += '<details class="rg-prov"><summary><i class="fas fa-leaf"></i> Normativa ambiental y de aguas de ' + protoEsc(prov.n) + (prov.ok ? '' : ' <span class="rg-tag rg-tag-warn">sin relevar</span>') + '</summary>' +
                    '<ul><li><strong>Impacto ambiental:</strong> ' + protoEsc(prov.eia) + '</li><li><strong>Residuos peligrosos:</strong> ' + protoEsc(prov.rp) + '</li><li><strong>Aguas y efluentes:</strong> ' + protoEsc(prov.ag) + '</li></ul>' +
                    (prov.ok ? '' : '<p class="rg-note">Para esta jurisdicción no se relevó el detalle legal: consulte a la autoridad ambiental provincial.</p>') + '</details>';
            }

            // Filtros
            const filters = [['todos', 'Todos'], ['faltan', 'Lo que falta'], ['nacional', 'Nacional'], ['provincial', 'Provincial'], ['municipal', 'Municipal']];
            h += '<div class="rg-filters" role="tablist">' + filters.map(f => '<button type="button" class="rg-filter' + (_rgFilter === f[0] ? ' on' : '') + '" onclick="rgSetFilter(\'' + f[0] + '\')">' + f[1] + '</button>').join('') + '</div>';

            const pass = function (r) {
                if (_rgFilter === 'faltan') return r.ev.st === 'falta' || r.ev.st === 'venc' || r.ev.st === 'warn';
                if (_rgFilter === 'nacional' || _rgFilter === 'provincial' || _rgFilter === 'municipal') return r.it.lv === _rgFilter;
                return true;
            };
            const shown = c.rows.filter(pass);
            if (!shown.length) h += '<div class="rg-empty"><i class="fas fa-check-circle"></i> No hay requisitos en este filtro.</div>';
            ['nacional', 'provincial', 'municipal'].forEach(function (lv) {
                const g = shown.filter(r => r.it.lv === lv);
                if (!g.length) return;
                h += '<div class="rg-group"><div class="rg-group-h"><i class="fas ' + RG_LV[lv][1] + '"></i> ' + RG_LV[lv][0] + ' <span>' + g.length + '</span></div>';
                g.forEach(function (r) {
                    const it = r.it, ev = r.ev;
                    const sel = ev.man || '';
                    let via = '';
                    if (!ev.man && ev.auto.docs) via = '<div class="rg-via"><i class="fas fa-paperclip"></i> Cargado en Gestión Documental: ' + protoEsc(ev.auto.docs.map(d => d.tipo).slice(0, 2).join(' · ')) + (ev.auto.docs.length > 2 ? ' (+' + (ev.auto.docs.length - 2) + ')' : '') + '</div>';
                    else if (!ev.man && ev.auto.n) via = '<div class="rg-via"><i class="fas fa-link"></i> Hay ' + ev.auto.n + ' registro' + (ev.auto.n > 1 ? 's' : '') + ' cargado' + (ev.auto.n > 1 ? 's' : '') + ' en el módulo correspondiente.</div>';
                    else if (ev.man && ev.man !== 'na') via = '<div class="rg-via"><i class="fas fa-user-check"></i> Marcado manualmente.</div>';
                    else if (!ev.man && ev.st === 'falta') via = '<div class="rg-via rg-via-none"><i class="fas fa-search"></i> No hay documento ni registro cargado en PROHS' + (it.dt || it.mc || it.go ? '' : ' (verifíquelo y márquelo manualmente)') + '.</div>';
                    h += '<div class="rg-item rg-st-' + ev.st + '" data-rg="' + it.id + '">' +
                        '<div class="rg-item-top"><span class="rg-badge rg-b-' + ev.st + '"><i class="fas ' + RG_ST[ev.st][1] + '"></i> ' + RG_ST[ev.st][0] + '</span>' +
                        (it.si ? '<span class="rg-tag">' + protoEsc(it.si) + '</span>' : '') + '</div>' +
                        '<div class="rg-title">' + protoEsc(it.t) + '</div>' +
                        '<div class="rg-desc">' + protoEsc(it.d) + '</div>' +
                        '<div class="rg-meta">' + (it.n ? '<span><i class="fas fa-gavel"></i> ' + protoEsc(it.n) + '</span>' : '') + (it.o ? '<span><i class="fas fa-landmark"></i> ' + protoEsc(it.o) + '</span>' : '') + '</div>' + via +
                        '<div class="rg-actions"><select aria-label="Estado de cumplimiento" onchange="rgSetState(\'' + it.id + '\', this.value)">' +
                        '<option value=""' + (sel === '' ? ' selected' : '') + '>Estado: automático</option><option value="cumple"' + (sel === 'cumple' ? ' selected' : '') + '>Cumple</option><option value="tramite"' + (sel === 'tramite' ? ' selected' : '') + '>En trámite</option><option value="na"' + (sel === 'na' ? ' selected' : '') + '>No aplica</option></select>' +
                        (ev.auto.docs && !ev.man ? '<button type="button" class="rg-btn" onclick="rgOpenDocs(\'' + it.id + '\')"><i class="fas fa-eye"></i> Ver documento</button>' : '') +
                        (it.dt && ev.st !== 'na' && ev.st !== 'ok' ? '<button type="button" class="rg-btn rg-btn-primary" onclick="rgAddDoc(\'' + it.id + '\')"><i class="fas fa-plus-circle"></i> Cargar documento</button>' : '') +
                        (it.go ? '<button type="button" class="rg-btn" onclick="rgGo(\'' + it.go + '\')"><i class="fas fa-arrow-right"></i> Ir al módulo</button>' : '') +
                        '</div></div>';
                });
                h += '</div>';
            });

            h += '<div class="rg-foot"><button type="button" class="rg-btn rg-btn-primary" onclick="rgExportPdf()"><i class="fas fa-file-pdf"></i> Exportar guía en PDF</button>' +
                '<p><i class="fas fa-info-circle"></i> <strong>Guía orientativa</strong> (datos revisados en ' + protoEsc(REQ_REVISION) + '). No reemplaza el asesoramiento profesional: las normas, categorías y trámites cambian y varían según el municipio y la actividad. Confirme siempre con el organismo de control. Fuentes: normativa nacional (argentina.gob.ar/normativa) y normativa ambiental provincial (Agencia I+D+i, argentina.gob.ar/ciencia/agencia).</p></div>';

            // Conserva la posición de scroll de la lista al re-renderizar
            const sy = window.scrollY;
            body.innerHTML = h;
            window.scrollTo(0, sy);
            rgRenderHead(c);
        }

        function rgExportPdf(mode) {
            if (!currentEstablishment) return;
            const c = rgCompute();
            if (!c.rows.length) { appAlert('Primero elija la provincia y el rubro.'); return; }
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const W = doc.internal.pageSize.getWidth();
            const clean = t => String(t || '').replace(/[–—]/g, '-').replace(/[…]/g, '...');
            const prov = REQ_PROVS.find(p => p.k === c.v.prov);
            let y = addPdfHeader(doc, 'Guia de requisitos y habilitaciones');
            doc.setFontSize(9); doc.setFont('helvetica', 'normal');
            const rubroTxt = c.v.rubros.map(k => (REQ_RUBROS.find(r => r.k === k) || {}).n).filter(Boolean).join(' + ');
            doc.text(clean('Provincia: ' + (prov ? prov.n : '') + '   |   Rubro: ' + rubroTxt), 15, y + 2); y += 7;
            doc.text('Cobertura: ' + c.pct + '%  (Cumple ' + c.cnt.ok + ', Por vencer ' + c.cnt.warn + ', Vencido ' + c.cnt.venc + ', En tramite ' + c.cnt.tramite + ', Falta ' + c.cnt.falta + ', No aplica ' + c.cnt.na + ')', 15, y + 2); y += 8;
            const body = c.rows.map(r => [RG_ST[r.ev.st][0], clean(RG_LV[r.it.lv][0]), clean(r.it.t + (r.it.si ? ' (' + r.it.si + ')' : '')), clean(r.it.n || ''), clean(r.it.o || '')]);
            doc.autoTable({
                startY: y, head: [['Estado', 'Nivel', 'Requisito', 'Norma', 'Organismo']], body: body, theme: 'grid',
                headStyles: { fillColor: [15, 115, 197], fontSize: 8 }, bodyStyles: { fontSize: 7.5, valign: 'top' },
                columnStyles: { 0: { cellWidth: 20 }, 1: { cellWidth: 19 }, 2: { cellWidth: 60 }, 3: { cellWidth: 45 } },
                margin: { left: 15, right: 15, top: 28, bottom: 20 },
                didParseCell: function (d) {
                    if (d.section === 'body' && d.column.index === 0) {
                        const t = d.cell.raw; d.cell.styles.fontStyle = 'bold';
                        d.cell.styles.textColor = t === 'Cumple' ? [22, 130, 70] : t === 'Falta' || t === 'Vencido' ? [200, 40, 40] : t === 'No aplica' ? [120, 120, 120] : [190, 120, 0];
                    }
                }
            });
            y = doc.lastAutoTable.finalY + 6;
            if (y > 255) { doc.addPage(); y = addPdfHeader(doc, 'Guia de requisitos y habilitaciones'); }
            doc.setFontSize(7.5); doc.setTextColor(90, 90, 90);
            const note = doc.splitTextToSize('Guia orientativa (datos revisados en ' + REQ_REVISION + '). No reemplaza el asesoramiento profesional: las normas, categorias y tramites cambian y varian segun el municipio y la actividad. Confirme siempre con el organismo de control.', W - 30);
            doc.text(note, 15, y);
            const total = doc.internal.getNumberOfPages();
            for (let i = 1; i <= total; i++) { doc.setPage(i); addPdfFooter(doc, i, total); }
            exportPdf(doc, 'guia-requisitos-' + (currentEstablishment.nombre || 'Sin_nombre').replace(/\s+/g, '-') + '-' + new Date().toISOString().split('T')[0] + '.pdf', mode);
        }

        function exportDocumentsSummary(mode) {
            if (!currentEstablishment) {
                alert('Seleccione un establecimiento primero');
                return;
            }
            
            const establishment = appData.establishments.find(e => e.id === currentEstablishment.id);
            const docs = appData.documents.filter(d => d.establecimiento_id === currentEstablishment.id);
            
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const pageWidth = doc.internal.pageSize.getWidth();
            const margin = 15;
            
            // Header con membrete azul
            addPdfHeader(doc, 'Informe de Gestion Documental');
            
            let yPos = 35;
            let pageNumber = 1;
            
            // Calcular estadisticas
            let completeCount = 0;
            let pendingCount = 0;
            let expiredCount = 0;
            const hoy = new Date();
            
            // Mismo criterio que el módulo Gestión Documental (docEffectiveStatus)
            docs.forEach(d => {
                const st = docEffectiveStatus(d).estado;
                if (st === 'vigente') completeCount++;
                else if (st === 'por_vencer' || st === 'en_tramite') pendingCount++;
                else expiredCount++;
            });
            
            // SECCION: INTRODUCCION
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('INTRODUCCION', margin, yPos);
            yPos += 7;
            
            doc.setFont(undefined, 'normal');
            doc.setFontSize(9);
            doc.text('Situacion de la documentacion legal y administrativa de ' + establishment.nombre + '.', margin, yPos);
            yPos += 4;
            doc.text('El seguimiento de vencimientos de habilitaciones, certificados y permisos previene multas', margin, yPos);
            yPos += 4;
            doc.text('e interrupciones operativas, asegurando la continuidad del negocio.', margin, yPos);
            yPos += 10;
            
            // SECCION: RESUMEN ESTADISTICO
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('RESUMEN ESTADISTICO', margin, yPos);
            yPos += 7;
            
            doc.setFont(undefined, 'normal');
            doc.setFontSize(9);
            doc.text('Total de documentos registrados: ' + docs.length, margin, yPos);
            yPos += 5;
            
            doc.setTextColor(22, 163, 74);
            doc.text('Documentos al dia: ' + completeCount, margin, yPos);
            yPos += 5;
            
            doc.setTextColor(234, 179, 8);
            doc.text('Por vencer o en tramite: ' + pendingCount, margin, yPos);
            yPos += 5;
            
            doc.setTextColor(220, 38, 38);
            doc.text('Vencidos o faltantes: ' + expiredCount, margin, yPos);
            yPos += 10;
            
            doc.setTextColor(0, 0, 0);
            
            // SECCION: DETALLE POR CATEGORIA
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('DETALLE POR CATEGORIA', margin, yPos);
            yPos += 7;
            
            const categories = {
                laboralSeguridad: 'Laboral y Higiene y Seguridad',
                habilitacion: 'Habilitacion Comercial y Edilicia',
                incendios: 'Prevencion de Incendios',
                ambiental: 'Cuestiones Ambientales',
                sanitario: 'Aspectos Sanitarios y OSSE',
                salud: 'Salud Laboral',
                complementaria: 'SGC / ISO 9001'
            };
            
            Object.entries(categories).forEach(([key, label]) => {
                const categoryDocs = docs.filter(d => d.categoria === key);
                
                if (yPos > 250) {
                    addPdfFooter(doc, pageNumber, doc.internal.getNumberOfPages() + 1);
                    doc.addPage();
                    pageNumber++;
                    yPos = 20;
                }
                
                doc.setFontSize(9);
                doc.setFont(undefined, 'bold');
                doc.setFillColor(240, 240, 240);
                doc.rect(margin, yPos - 3, pageWidth - 2 * margin, 6, 'F');
                doc.text(label + ' (' + categoryDocs.length + ')', margin + 2, yPos);
                yPos += 8;
                
                doc.setFont(undefined, 'normal');
                doc.setFontSize(8);
                
                if (categoryDocs.length === 0) {
                    doc.setTextColor(128, 128, 128);
                    doc.text('Sin documentos registrados en esta categoria', margin + 5, yPos);
                    doc.setTextColor(0, 0, 0);
                    yPos += 6;
                } else {
                    categoryDocs.forEach(d => {
                        if (yPos > 270) {
                            addPdfFooter(doc, pageNumber, doc.internal.getNumberOfPages() + 1);
                            doc.addPage();
                            pageNumber++;
                            yPos = 20;
                        }
                        
                        // Calcular estado real basado en fecha de vencimiento
                        const estadoReal = docEffectiveStatus(d).estado;
                        
                        const statusLabels = {
                            vigente: 'Vigente',
                            por_vencer: 'Por vencer',
                            vencido: 'Vencido',
                            faltante: 'Faltante',
                            en_tramite: 'En tramite'
                        };
                        
                        const statusColors = {
                            vigente: [22, 163, 74],
                            por_vencer: [234, 179, 8],
                            vencido: [220, 38, 38],
                            faltante: [220, 38, 38],
                            en_tramite: [59, 130, 246]
                        };
                        
                        doc.setTextColor(0, 0, 0);
                        doc.text('- ' + d.tipo, margin + 3, yPos);
                        
                        const color = statusColors[estadoReal] || [0, 0, 0];
                        doc.setTextColor(color[0], color[1], color[2]);
                        doc.text('[' + (statusLabels[estadoReal] || estadoReal) + ']', margin + 90, yPos);
                        
                        if (d.fecha_vencimiento) {
                            doc.setTextColor(0, 0, 0);
                            doc.text('Venc: ' + formatDate(d.fecha_vencimiento), margin + 130, yPos);
                        }
                        yPos += 5;
                    });
                }
                yPos += 4;
            });
            
            // SECCION: OBSERVACIONES
            if (yPos > 240) {
                addPdfFooter(doc, pageNumber, doc.internal.getNumberOfPages() + 1);
                doc.addPage();
                pageNumber++;
                yPos = 20;
            }
            
            yPos += 5;
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('OBSERVACIONES', margin, yPos);
            yPos += 7;
            
            doc.setFont(undefined, 'normal');
            doc.setFontSize(9);
            
            if (expiredCount > 0) {
                doc.text((expiredCount === 1 ? 'Se detecto 1 documento vencido o faltante que requiere' : 'Se detectaron ' + expiredCount + ' documentos vencidos o faltantes que requieren') + ' atencion inmediata.', margin, yPos);
                yPos += 5;
            }
            if (pendingCount > 0) {
                doc.text((pendingCount === 1 ? 'Existe 1 documento' : 'Existen ' + pendingCount + ' documentos') + ' por vencer (proximos 30 dias) o en tramite.', margin, yPos);
                yPos += 5;
            }
            if (expiredCount === 0 && pendingCount === 0) {
                doc.text('Toda la documentacion se encuentra al dia. Continuar con el seguimiento periodico.', margin, yPos);
                yPos += 5;
            }
            
            // Footer en todas las paginas
            const totalPages = doc.internal.getNumberOfPages();
            for (let i = 1; i <= totalPages; i++) {
                doc.setPage(i);
                addPdfFooter(doc, i, totalPages);
            }
            
            exportPdf(doc, 'gestion-documental-' + (establishment.nombre || 'Sin_nombre').replace(/\s+/g, '-') + '-' + new Date().toISOString().split('T')[0] + '.pdf', mode);
        }

        async function resetAllData() {
            if (!await appConfirm('⚠️ ATENCIÓN: Esta acción eliminará TODOS los datos de forma PERMANENTE.\n\n¿Está seguro de que desea continuar?')) {
                return;
            }

            if (!await appConfirm('⚠️ ÚLTIMA CONFIRMACIÓN: Se borrarán:\n\n' +
                         `• ${appData.establishments.length} establecimientos\n` +
                         `• ${appData.inspections.length} inspecciones\n` +
                         `• ${appData.actions.length} acciones\n` +
                         `• ${appData.fireloads.length} cargas de fuego\n` +
                         `• ${appData.extinguishers.length} extintores\n` +
                         `• ${appData.risks.length} riesgos\n` +
                         `• ${appData.trainings.length} capacitaciones\n` +
                         `• ${appData.incidents.length} incidentes\n` +
                         `• ${appData.ppe.length} entregas de EPP\n\n` +
                         'Esta acción NO se puede deshacer.\n\n¿Confirmar eliminación?')) {
                return;
            }

            // Los RGRL viven fuera de appData: también se borran
            for (const est of (appData.establishments || [])) {
                try { await Storage.removeItem('rgrl_list_' + est.id); } catch (e) { /* noop */ }
            }
            try { await Storage.removeItem('rgrlObrasFormularios'); } catch (e) { /* noop */ }

            // Resetear todos los datos
            appData = normalizeAppData({});

            saveData();
            await flushPendingSave();
            syncSelectorsToEstablishment(null);
            showHome();

            alert('✅ Todos los datos han sido eliminados correctamente.');
        }

