        function updateRGRLResponse(key, field, value) {
            // Esta función maneja dos tipos de respuestas:
            // 1. Para Planillas A, B, C: field='value', guarda el valor directamente como string ('si' o 'no')
            // 2. Para formulario principal: field='respuesta' o 'fecha', guarda como objeto { respuesta: '...', fecha: '...' }
            
            if (!rgrlResponses[key]) {
                rgrlResponses[key] = {};
            }
            
            if (field === 'value') {
                // Para Planillas A, B, C guardamos el valor directamente como string
                rgrlResponses[key] = value;
            } else {
                // Para el formulario principal guardamos como objeto con campos
                rgrlResponses[key][field] = value;
            }
        }

        async function saveRGRLForm() {
            if (!currentEstablishment) {
                alert('⚠️ Seleccione un establecimiento primero');
                return;
            }
            
            // Validar campos requeridos
            const nombre = document.getElementById('rgrlEmpresaNombre').value.trim();
            const cuit = document.getElementById('rgrlCuit').value.trim();
            const ciiu = document.getElementById('rgrlCiiu').value.trim();
            const descActividad = document.getElementById('rgrlDescActividad').value.trim();
            const domicilio = document.getElementById('rgrlDomicilio').value.trim();
            
            if (!nombre || !cuit || !ciiu || !descActividad || !domicilio) {
                alert('⚠️ Por favor complete todos los campos requeridos (*) de Datos Generales del Establecimiento');
                return;
            }
            
            // Recopilar datos del establecimiento
            const datosEstablecimiento = {
                nombre: nombre,
                cuit: cuit,
                numEstablecimiento: document.getElementById('rgrlNumEstablecimiento').value,
                ciiu: ciiu,
                superficie: document.getElementById('rgrlSuperficie').value,
                codigoActividad: document.getElementById('rgrlCodigoActividad').value,
                cantTrabajadores: document.getElementById('rgrlCantTrabajadores').value,
                descActividad: descActividad,
                domicilio: domicilio,
                provincia: document.getElementById('rgrlProvincia').value,
                codigoPostal: document.getElementById('rgrlCodigoPostal').value,
                localidad: document.getElementById('rgrlLocalidad').value,
                telefono: document.getElementById('rgrlTelefono').value
            };
            
            // Crear o actualizar formulario
            const formId = currentRGRLId || `rgrl_${Date.now()}`;
            const formData = {
                id: formId,
                fecha: new Date().toISOString(),
                datosEstablecimiento: datosEstablecimiento,
                responses: JSON.parse(JSON.stringify(rgrlResponses)), // Copia profunda para evitar referencias
                establecimiento: currentEstablishment.id
            };
            
            // Obtener lista de formularios
            const listKey = `rgrl_list_${currentEstablishment.id}`;
            const savedList = await Storage.getItem(listKey);
            let formularios = savedList ? JSON.parse(savedList) : [];
            
            // Actualizar o agregar formulario
            const existingIndex = formularios.findIndex(f => f.id === formId);
            if (existingIndex >= 0) {
                formularios[existingIndex] = formData;
                alert('✅ Formulario RGRL actualizado correctamente');
            } else {
                formularios.push(formData);
                alert('✅ Formulario RGRL guardado correctamente');
            }
            
            // Guardar
            try {
                await Storage.setItem(listKey, JSON.stringify(formularios));
            } catch (e) {
                alert('❌ Error al guardar: ' + e.message);
                return;
            }
            
            // Resetear el ID actual y volver a la lista
            currentRGRLId = null;
            rgrlResponses = {};
            document.getElementById('rgrlListContainer').classList.remove('hidden');
            document.getElementById('rgrlFormContainer').classList.add('hidden');
            loadRGRLList();
        }

        function loadRGRLData() {
            // Esta función ya no se usa, se reemplazó por loadRGRLList
        }

        // ============= PDF DEL RGRL (mismo formato de tablas y puntos que la página) =============
        // cfg: { titulo, subtitulo, estLine, datos{...}, sections[{title,questions[{num,text,normativa}]}],
        //        resp(key) -> {respuesta, fecha} | valor de planilla, planillaA[], planillaB[], planillaC[{nombre,umbral}],
        //        colorSeccion:[r,g,b] }
        function rgrlBuildPdf(cfg) {
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const pageW = doc.internal.pageSize.getWidth();
            const drawn = {};
            const GRAY_HEAD = [229, 231, 235], PURPLE = [243, 232, 255], YELLOW_50 = [254, 252, 232];

            function header() {
                const pn = doc.internal.getCurrentPageInfo().pageNumber;
                if (drawn[pn]) return;
                drawn[pn] = true;
                doc.setFillColor(15, 115, 197);
                doc.rect(0, 0, pageW, 24, 'F');
                if (pdfLogoBase64) { try { doc.addImage(pdfLogoBase64, 'JPEG', 5, 4, 28, 12); } catch (e) { /* sin logo */ } }
                doc.setTextColor(255, 255, 255);
                doc.setFont('helvetica', 'bold'); doc.setFontSize(12);
                doc.text(cfg.titulo, 36, 9);
                doc.setFontSize(9);
                doc.text(cfg.subtitulo, 36, 15);
                doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
                doc.text(cfg.estLine, 36, 20.5);
                doc.setTextColor(0, 0, 0);
            }
            header();

            const base = {
                theme: 'grid',
                margin: { top: 30, left: 15, right: 15, bottom: 20 },
                styles: { fontSize: 7.5, cellPadding: 1.6, lineColor: [190, 195, 202], lineWidth: 0.2, textColor: [0, 0, 0], valign: 'middle', overflow: 'linebreak', minCellHeight: 6.2 },
                headStyles: { fillColor: GRAY_HEAD, textColor: [0, 0, 0], fontStyle: 'bold', fontSize: 7.5, lineColor: [190, 195, 202], lineWidth: 0.2 },
                didDrawPage: header
            };
            function titleRow(text, color, span) {
                return [{ content: text, colSpan: span, styles: { fillColor: color, fontStyle: 'bold', fontSize: 9, halign: 'left', cellPadding: 2.4 } }];
            }
            // Puntos de selección (como los radio de la página): hueco = sin marcar, relleno = elegido
            function radios(cols) {
                return function (data) {
                    if (data.section !== 'body' || cols.indexOf(data.column.index) === -1) return;
                    const cx = data.cell.x + data.cell.width / 2, cy = data.cell.y + data.cell.height / 2;
                    doc.setDrawColor(70, 80, 95); doc.setLineWidth(0.3);
                    doc.circle(cx, cy, 1.7, 'S');
                    if (data.cell.raw && data.cell.raw.sel) { doc.setFillColor(15, 115, 197); doc.circle(cx, cy, 1.0, 'F'); }
                };
            }
            const sel = (v) => ({ content: '', sel: !!v });
            const norm = (v) => { const s = String(v || '').toLowerCase().replace(/[\s-]/g, '_'); return s === 'no_aplica' || s === 'na' || s === 'n/a' ? 'na' : s; };
            const nextY = () => doc.lastAutoTable.finalY + 6;
            const D = cfg.datos;

            // ---- Datos generales ----
            const lab = (t) => ({ content: t, styles: { fontStyle: 'bold', fillColor: [243, 244, 246] } });
            const val = (v, span) => ({ content: String(v === undefined || v === null || v === '' ? '' : v), colSpan: span || 1 });
            doc.autoTable(Object.assign({}, base, {
                startY: 30,
                head: [titleRow(cfg.tituloDatos, YELLOW_50, 4)],
                body: [
                    [lab('Nombre de la empresa'), val(D.nombre, 3)],
                    [lab('CUIT / CUIP'), val(D.cuit), lab('N° de establecimiento'), val(D.numEstablecimiento)],
                    [lab('CIIU (Revisión 3)'), val(D.ciiu), lab('Superficie (m²)'), val(D.superficie)],
                    [lab('Código de actividad (Form. AFIP N° 150)'), val(D.codigoActividad), lab('Cantidad de trabajadores'), val(D.cantTrabajadores)],
                    [lab('Descripción de la actividad'), val(D.descActividad, 3)],
                    [lab('Domicilio'), val(D.domicilio, 3)],
                    [lab('Provincia'), val(D.provincia), lab('Código postal'), val(D.codigoPostal)],
                    [lab('Localidad'), val(D.localidad), lab('Teléfono'), val(D.telefono)]
                ],
                columnStyles: { 0: { cellWidth: 44 }, 1: { cellWidth: 46 }, 2: { cellWidth: 44 }, 3: { cellWidth: 46 } }
            }));

            // ---- Secciones (tablas) ----
            const colHead = ['N°', 'Condición a Cumplir', 'SÍ', 'NO', 'NO APLICA', 'Fecha Regular.', 'Normativa'];
            cfg.sections.forEach(function (section) {
                const body = section.questions.map(function (q) {
                    const r = cfg.resp('q' + q.num) || {};
                    const a = norm(r.respuesta);
                    return [
                        { content: String(q.num), styles: { halign: 'center', fontStyle: 'bold' } },
                        q.text,
                        sel(a === 'si'), sel(a === 'no'), sel(a === 'na'),
                        { content: r.fecha ? formatDate(r.fecha) : '', styles: { halign: 'center' } },
                        { content: q.normativa || '', styles: { fontSize: 6.5 } }
                    ];
                });
                doc.autoTable(Object.assign({}, base, {
                    startY: nextY(),
                    head: [titleRow(section.title, cfg.colorSeccion, 7), colHead.map(function (h, i) { return { content: h, styles: { halign: (i >= 2 && i <= 5) || i === 0 ? 'center' : 'left' } }; })],
                    body: body,
                    columnStyles: { 0: { cellWidth: 9 }, 1: { cellWidth: 69 }, 2: { cellWidth: 11 }, 3: { cellWidth: 11 }, 4: { cellWidth: 17 }, 5: { cellWidth: 22 }, 6: { cellWidth: 41 } },
                    didDrawCell: radios([2, 3, 4])
                }));
            });

            // ---- Planillas A, B y C ----
            function planilla(titulo, items, withUmbral, prefix) {
                const head = withUmbral ? ['Descripción', 'Cantidad Umbral (TN)', 'SÍ', 'NO'] : ['Descripción', 'SÍ', 'NO'];
                const body = items.map(function (it, i) {
                    const v = norm(cfg.resp(prefix + '_' + i));
                    return withUmbral
                        ? [it.nombre, { content: String(it.umbral), styles: { halign: 'center' } }, sel(v === 'si'), sel(v === 'no')]
                        : [it, sel(v === 'si'), sel(v === 'no')];
                });
                const cols = withUmbral ? { 0: { cellWidth: 118 }, 1: { cellWidth: 30 }, 2: { cellWidth: 16 }, 3: { cellWidth: 16 } } : { 0: { cellWidth: 148 }, 1: { cellWidth: 16 }, 2: { cellWidth: 16 } };
                doc.autoTable(Object.assign({}, base, {
                    startY: nextY(),
                    head: [titleRow(titulo, PURPLE, head.length), head.map(function (h, i) { return { content: h, styles: { halign: i === 0 ? 'left' : 'center' } }; })],
                    body: body,
                    columnStyles: cols,
                    didDrawCell: radios(withUmbral ? [2, 3] : [1, 2])
                }));
            }
            planilla('PLANILLA A | LISTADO DE SUSTANCIAS Y AGENTES CANCERÍGENOS', cfg.planillaA, false, 'planillaA');
            planilla('PLANILLA B | DIFENILOS POLICLORADOS (PCBs)', cfg.planillaB, false, 'planillaB');
            planilla('PLANILLA C | SUSTANCIAS QUÍMICAS A DECLARAR', cfg.planillaC, true, 'planillaC');

            // ---- Firmas ----
            let y = nextY() + 4;
            if (y > 235) { doc.addPage(); header(); y = 40; }
            doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor(0, 0, 0);
            doc.text('Lugar y fecha: ______________________________________', 15, y);
            y += 22;
            doc.setDrawColor(90, 90, 90); doc.setLineWidth(0.3);
            doc.line(15, y, 95, y); doc.line(115, y, 195, y);
            doc.setFontSize(7.5);
            doc.text('Firma, aclaración y cargo del Empleador / Representante legal', 55, y + 4, { align: 'center' });
            doc.text('Firma, aclaración y matrícula del Profesional de Higiene y Seguridad', 155, y + 4, { align: 'center' });

            const total = doc.internal.getNumberOfPages();
            for (let i = 1; i <= total; i++) { doc.setPage(i); addPdfFooter(doc, i, total); }
            return doc;
        }

        function exportRGRLToPDF(mode) {
            if (!currentEstablishment) {
                alert('Seleccione un establecimiento primero');
                return;
            }
            const g = (id) => (document.getElementById(id) || {}).value || '';
            const nombre = g('rgrlEmpresaNombre').trim();
            const cuit = g('rgrlCuit').trim();
            if (!nombre || !cuit) {
                alert('⚠️ Por favor complete los datos del establecimiento antes de exportar');
                return;
            }
            const doc = rgrlBuildPdf({
                titulo: 'RELEVAMIENTO GENERAL DE RIESGOS LABORALES',
                subtitulo: 'FORMULARIO A - RGRL',
                estLine: 'Fecha: ' + formatDate(new Date().toISOString().split('T')[0]) + ' | ' + nombre,
                tituloDatos: 'DATOS GENERALES DEL ESTABLECIMIENTO',
                datos: {
                    nombre: nombre, cuit: cuit, numEstablecimiento: g('rgrlNumEstablecimiento'), ciiu: g('rgrlCiiu'),
                    superficie: g('rgrlSuperficie'), codigoActividad: g('rgrlCodigoActividad'), cantTrabajadores: g('rgrlCantTrabajadores'),
                    descActividad: g('rgrlDescActividad'), domicilio: g('rgrlDomicilio'), provincia: g('rgrlProvincia'),
                    codigoPostal: g('rgrlCodigoPostal'), localidad: g('rgrlLocalidad'), telefono: g('rgrlTelefono')
                },
                sections: RGRL_DATA.sections,
                resp: (k) => rgrlResponses[k],
                planillaA: RGRL_DATA.planillaA, planillaB: RGRL_DATA.planillaB, planillaC: RGRL_DATA.planillaC,
                colorSeccion: [243, 244, 246]
            });
            const fileName = `RGRL-${nombre.replace(/\s+/g, '-')}-${new Date().toISOString().split('T')[0]}.pdf`;
            exportPdf(doc, fileName, mode);
        }

        // ============= RGRL OBRAS FUNCTIONS =============
        
        async function loadRGRLObrasFromLocalStorage() {
            const savedForms = JSON.parse(await Storage.getItem('rgrlObrasFormularios')) || [];
            const container = document.getElementById('rgrlObrasFormsList');
            
            if (savedForms.length === 0) {
                container.innerHTML = '<p class="text-gray-500 italic">No hay formularios guardados</p>';
                return;
            }
            
            container.innerHTML = savedForms.map((form, index) => `
                <div class="border border-gray-300 rounded-lg p-4 bg-white hover:shadow-md transition">
                    <div class="flex items-center justify-between">
                        <div class="flex-1">
                            <h4 class="font-bold text-lg">${form.datosGenerales.empresaNombre}</h4>
                            <p class="text-sm text-gray-600">CUIT: ${form.datosGenerales.cuit} | Fecha: ${new Date(form.fechaCreacion).toLocaleDateString()}</p>
                            <p class="text-sm text-gray-600">Domicilio: ${form.datosGenerales.domicilio}</p>
                        </div>
                        <div class="flex gap-2">
                            <button onclick="editRGRLObrasForm(${index})" class="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-semibold transition text-sm">
                                ✏️ Editar
                            </button>
                            <button onclick="exportRGRLObrasFormToPDF(${index})" class="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded-lg font-semibold transition text-sm">
                                <i class="fas fa-file-alt"></i> PDF
                            </button>
                            <button onclick="deleteRGRLObrasForm(${index})" class="bg-red-600 hover:bg-red-700 text-white px-4 py-2 rounded-lg font-semibold transition text-sm">
                                🗑️ Eliminar
                            </button>
                        </div>
                    </div>
                </div>
            `).join('');
        }
        
