        async function deleteVehicleInspection(vehicleId, inspectionId) {
            if (!await appConfirm('¿Está seguro de eliminar esta inspección? Esta acción no se puede deshacer.')) {
                return;
            }

            const vehicle = appData.vehicles.find(v => v.id === vehicleId);
            if (!vehicle) {
                alert('Vehículo no encontrado');
                return;
            }

            const index = vehicle.inspecciones.findIndex(i => i.id === inspectionId);
            if (index !== -1) {
                vehicle.inspecciones.splice(index, 1);
                saveData();
                alert('Inspección eliminada exitosamente');
                
                // Cerrar el modal actual y volver a cargar el detalle
                closeModal();
                viewVehicleDetail(vehicleId);
            } else {
                alert('Inspección no encontrada');
            }
        }

