        function previewInspectionPhotos(input) {
            const files = input.files;
            if (!files || files.length === 0) return;

            const previewDiv = document.getElementById('inspectionPhotosPreview');
            inspectionPhotosData = [];

            Array.from(files).forEach((file, index) => {
                compressImage(file).then(compressedDataURL => {
                    inspectionPhotosData.push(compressedDataURL);
                    
                    const photoElement = document.createElement('div');
                    photoElement.className = 'relative';
                    photoElement.innerHTML = `
                        <img src="${compressedDataURL}" class="w-full h-24 object-cover rounded border" alt="Foto ${index + 1}">
                        <button type="button" onclick="removeInspectionPhoto(${index})" class="absolute top-1 right-1 bg-red-600 hover:bg-red-700 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">
                            ×
                        </button>
                    `;
                    previewDiv.appendChild(photoElement);
                });
            });
        }

        function removeInspectionPhoto(index) {
            inspectionPhotosData.splice(index, 1);
            const previewDiv = document.getElementById('inspectionPhotosPreview');
            if (previewDiv) {
                previewDiv.innerHTML = '';
                inspectionPhotosData.forEach((photo, idx) => {
                    const photoElement = document.createElement('div');
                    photoElement.className = 'relative';
                    photoElement.innerHTML = `
                        <img src="${photo}" class="w-full h-24 object-cover rounded border" alt="Foto ${idx + 1}">
                        <button type="button" onclick="removeInspectionPhoto(${idx})" class="absolute top-1 right-1 bg-red-600 hover:bg-red-700 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs font-bold">
                            ×
                        </button>
                    `;
                    previewDiv.appendChild(photoElement);
                });
            }
        }

        async function exportVehiclesPDF(mode) {
            if (!currentEstablishment) {
                alert('Seleccione un establecimiento primero');
                return;
            }

            const vehicles = getActivosVisibles('vehicles', currentEstablishment);
            if (vehicles.length === 0) {
                alert('No hay vehículos registrados para exportar');
                return;
            }

            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            
            const pageHeight = doc.internal.pageSize.height;
            const pageWidth = doc.internal.pageSize.width;
            const margin = 15;

            // Función auxiliar para verificar espacio y agregar página
            function checkPageBreak(needed = 20) {
                if (yPos + needed > pageHeight - 20) {
                    doc.addPage();
                    yPos = 20;
                    return true;
                }
                return false;
            }

            // Función para calcular vencimientos
            function getVencimientoStatus(fechaVencimiento) {
                if (!fechaVencimiento) return { text: 'No especificado', color: [150, 150, 150] };
                
                const hoy = new Date();
                const vencimiento = new Date(fechaVencimiento);
                const diasDiferencia = Math.floor((vencimiento - hoy) / (1000 * 60 * 60 * 24));
                
                if (diasDiferencia < 0) {
                    return { text: 'VENCIDO', color: [220, 38, 38] };
                } else if (diasDiferencia <= 30) {
                    return { text: 'PROXIMO A VENCER', color: [234, 179, 8] };
                } else {
                    return { text: 'VIGENTE', color: [22, 163, 74] };
                }
            }

            // PORTADA con logo
            let yPos = addPdfHeader(doc, 'Informe de Flota Vehicular');
            doc.setTextColor(0, 0, 0);

            // SECCION: INTRODUCCION
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('INTRODUCCION', margin, yPos);
            yPos += 7;
            
            doc.setFont(undefined, 'normal');
            doc.setFontSize(9);
            doc.text('Estado de la flota vehicular de ' + currentEstablishment.nombre + '. Este registro centraliza', margin, yPos);
            yPos += 4;
            doc.text('la documentacion habilitante (cedula, seguro, VTV) y las inspecciones tecnicas de cada', margin, yPos);
            yPos += 4;
            doc.text('unidad, facilitando el control preventivo y la planificacion del mantenimiento.', margin, yPos);
            yPos += 10;

            // SECCION: ESTADISTICAS GENERALES
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('ESTADISTICAS GENERALES', margin, yPos);
            yPos += 10;

            // Calcular estadísticas
            const totalVehiculos = vehicles.length;
            const activos = vehicles.filter(v => v.estado === 'activo').length;
            const enMantenimiento = vehicles.filter(v => v.estado === 'mantenimiento').length;
            const inactivos = vehicles.filter(v => v.estado === 'inactivo').length;
            
            const tiposCounts = {};
            vehicles.forEach(v => {
                tiposCounts[v.tipo] = (tiposCounts[v.tipo] || 0) + 1;
            });
            
            const totalInspecciones = vehicles.reduce((sum, v) => 
                sum + (v.inspecciones ? v.inspecciones.length : 0), 0);
            const vehiculosConInspeccion = vehicles.filter(v => 
                v.inspecciones && v.inspecciones.length > 0).length;

            // Vencimientos próximos
            const hoy = new Date();
            const vencimientosProximos = [];
            vehicles.forEach(v => {
                if (v.cedula_vencimiento) {
                    const dias = Math.floor((new Date(v.cedula_vencimiento) - hoy) / (1000 * 60 * 60 * 24));
                    if (dias >= 0 && dias <= 30) {
                        vencimientosProximos.push({ patente: v.patente, tipo: 'Cédula', dias });
                    }
                }
                if (v.seguro_vencimiento) {
                    const dias = Math.floor((new Date(v.seguro_vencimiento) - hoy) / (1000 * 60 * 60 * 24));
                    if (dias >= 0 && dias <= 30) {
                        vencimientosProximos.push({ patente: v.patente, tipo: 'Seguro', dias });
                    }
                }
                if (v.vtv_vencimiento) {
                    const dias = Math.floor((new Date(v.vtv_vencimiento) - hoy) / (1000 * 60 * 60 * 24));
                    if (dias >= 0 && dias <= 30) {
                        vencimientosProximos.push({ patente: v.patente, tipo: 'VTV', dias });
                    }
                }
            });

            // Cuadros de estadísticas
            const boxWidth = (pageWidth - 2 * margin - 10) / 3;
            const boxHeight = 18;
            
            // Total Vehículos
            doc.setFillColor(15, 115, 197);
            doc.rect(margin, yPos, boxWidth, boxHeight, 'F');
            doc.setTextColor(255, 255, 255);
            doc.setFontSize(20);
            doc.setFont(undefined, 'bold');
            doc.text(totalVehiculos.toString(), margin + boxWidth / 2, yPos + 9, { align: 'center' });
            doc.setFontSize(9);
            doc.setFont(undefined, 'normal');
            doc.text('Total Vehículos', margin + boxWidth / 2, yPos + 15, { align: 'center' });
            
            // Activos
            doc.setFillColor(22, 163, 74);
            doc.rect(margin + boxWidth + 5, yPos, boxWidth, boxHeight, 'F');
            doc.setFontSize(20);
            doc.setFont(undefined, 'bold');
            doc.text(activos.toString(), margin + boxWidth + 5 + boxWidth / 2, yPos + 9, { align: 'center' });
            doc.setFontSize(9);
            doc.setFont(undefined, 'normal');
            doc.text('Activos', margin + boxWidth + 5 + boxWidth / 2, yPos + 15, { align: 'center' });
            
            // Inspecciones
            doc.setFillColor(147, 51, 234);
            doc.rect(margin + 2 * boxWidth + 10, yPos, boxWidth, boxHeight, 'F');
            doc.setFontSize(20);
            doc.setFont(undefined, 'bold');
            doc.text(totalInspecciones.toString(), margin + 2 * boxWidth + 10 + boxWidth / 2, yPos + 9, { align: 'center' });
            doc.setFontSize(9);
            doc.setFont(undefined, 'normal');
            doc.text('Inspecciones Totales', margin + 2 * boxWidth + 10 + boxWidth / 2, yPos + 15, { align: 'center' });
            
            yPos += boxHeight + 12;
            doc.setTextColor(0, 0, 0);

            // Detalle de estados
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.text('Distribución por Estado:', margin, yPos);
            yPos += 6;
            doc.setFont(undefined, 'normal');
            doc.text(`Activos: ${activos} (${(activos/totalVehiculos*100).toFixed(1)}%)`, margin + 5, yPos);
            doc.text(`En Mantenimiento: ${enMantenimiento} (${(enMantenimiento/totalVehiculos*100).toFixed(1)}%)`, margin + 70, yPos);
            doc.text(`Inactivos: ${inactivos} (${(inactivos/totalVehiculos*100).toFixed(1)}%)`, margin + 140, yPos);
            yPos += 8;

            // Distribución por tipo
            doc.setFont(undefined, 'bold');
            doc.text('Distribución por Tipo:', margin, yPos);
            yPos += 6;
            doc.setFont(undefined, 'normal');
            let xOffset = margin + 5;
            Object.entries(tiposCounts).forEach(([tipo, count]) => {
                const tipoLabel = vehicleTypeLabel(tipo);
                doc.text(`${tipoLabel}: ${count}`, xOffset, yPos);
                xOffset += 60;
                if (xOffset > pageWidth - margin - 60) {
                    xOffset = margin + 5;
                    yPos += 5;
                }
            });
            yPos += 10;

            // Alertas de vencimientos
            if (vencimientosProximos.length > 0) {
                checkPageBreak(30);
                doc.setFillColor(254, 226, 226);
                doc.rect(margin, yPos, pageWidth - 2 * margin, 25, 'F');
                doc.setDrawColor(220, 38, 38);
                doc.setLineWidth(0.5);
                doc.rect(margin, yPos, pageWidth - 2 * margin, 25);
                
                doc.setTextColor(220, 38, 38);
                doc.setFontSize(11);
                doc.setFont(undefined, 'bold');
                doc.text('ALERTA: VENCIMIENTOS PRÓXIMOS (30 días)', margin + 3, yPos + 6);
                doc.setFontSize(9);
                doc.setFont(undefined, 'normal');
                doc.setTextColor(0, 0, 0);
                yPos += 12;
                
                vencimientosProximos.slice(0, 3).forEach(v => {
                    doc.text('- ' + safeText(v.patente) + ': ' + safeText(v.tipo) + ' vence en ' + v.dias + ' dias', margin + 5, yPos);
                    yPos += 4;
                });
                
                if (vencimientosProximos.length > 3) {
                    doc.setFont(undefined, 'italic');
                    doc.text(`... y ${vencimientosProximos.length - 3} alertas más (ver detalle)`, margin + 5, yPos);
                }
                yPos += 10;
                doc.setTextColor(0, 0, 0);
            }

            // TABLA RESUMEN DE VEHÍCULOS
            doc.addPage();
            yPos = addPdfHeader(doc, 'Informe de Flota Vehicular');
            
            doc.setFontSize(10);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('LISTADO DE VEHICULOS', margin, yPos);
            yPos += 8;

            // Headers de tabla
            doc.setFillColor(230, 230, 235);
            doc.rect(margin, yPos, pageWidth - 2 * margin, 8, 'F');
            doc.setFontSize(8);
            doc.setFont(undefined, 'bold');
            doc.setTextColor(0, 0, 0);
            doc.text('Nº', margin + 2, yPos + 5);
            doc.text('Patente', margin + 10, yPos + 5);
            doc.text('Marca/Modelo', margin + 32, yPos + 5);
            doc.text('Tipo', margin + 70, yPos + 5);
            doc.text('Estado', margin + 95, yPos + 5);
            doc.text('Km', margin + 120, yPos + 5);
            doc.text('Insp.', margin + 145, yPos + 5);
            doc.text('Últ. VTV', margin + 163, yPos + 5);
            yPos += 10;

            // Filas de tabla
            doc.setFont(undefined, 'normal');
            doc.setFontSize(7);
            vehicles.forEach((vehicle, idx) => {
                if (checkPageBreak(6)) {
                    // Repetir headers
                    doc.setFillColor(230, 230, 235);
                    doc.rect(margin, yPos, pageWidth - 2 * margin, 8, 'F');
                    doc.setFontSize(8);
                    doc.setFont(undefined, 'bold');
                    doc.text('Nº', margin + 2, yPos + 5);
                    doc.text('Patente', margin + 10, yPos + 5);
                    doc.text('Marca/Modelo', margin + 32, yPos + 5);
                    doc.text('Tipo', margin + 70, yPos + 5);
                    doc.text('Estado', margin + 95, yPos + 5);
                    doc.text('Km', margin + 120, yPos + 5);
                    doc.text('Insp.', margin + 145, yPos + 5);
                    doc.text('Últ. VTV', margin + 163, yPos + 5);
                    yPos += 10;
                    doc.setFont(undefined, 'normal');
                    doc.setFontSize(7);
                }
                
                // Fila alternada
                if (idx % 2 === 0) {
                    doc.setFillColor(250, 250, 252);
                    doc.rect(margin, yPos - 4, pageWidth - 2 * margin, 6, 'F');
                }
                
                doc.text((idx + 1).toString(), margin + 2, yPos);
                doc.text(safeText(vehicle.patente), margin + 10, yPos);
                const marcaModelo = `${vehicle.marca} ${vehicle.modelo}`.substring(0, 22);
                doc.text(marcaModelo, margin + 32, yPos);
                doc.text(vehicle.tipo ? vehicleTypeLabel(vehicle.tipo).substring(0, 12) : 'N/A', margin + 70, yPos);
                doc.text(vehicle.estado ? vehicle.estado.substring(0, 10) : 'N/A', margin + 95, yPos);
                doc.text(vehicle.kilometraje ? parseInt(vehicle.kilometraje).toLocaleString('es-AR').substring(0, 12) : 'N/D', margin + 120, yPos);
                doc.text(vehicle.inspecciones ? vehicle.inspecciones.length.toString() : '0', margin + 145, yPos);
                doc.text(vehicle.vtv_vencimiento ? new Date(vehicle.vtv_vencimiento).toLocaleDateString('es-AR') : 'N/D', margin + 163, yPos);
                
                yPos += 6;
            });

            // DETALLE COMPLETO DE CADA VEHÍCULO
            for (let idx = 0; idx < vehicles.length; idx++) {
                const vehicle = vehicles[idx];
                
                doc.addPage();
                yPos = 20;
                
                // Header del vehículo con logo (formato compacto)
                doc.setFillColor(15, 115, 197); // #0f73c5
                doc.rect(0, 0, pageWidth, 22, 'F');
                
                // Logo
                if (pdfLogoBase64) {
                    try {
                        doc.addImage(pdfLogoBase64, 'JPEG', 5, 4, 30, 13);
                    } catch (e) {}
                }
                
                doc.setTextColor(255, 255, 255);
                doc.setFontSize(12);
                doc.setFont(undefined, 'bold');
                doc.text(`VEHÍCULO ${idx + 1} DE ${vehicles.length}`, 38, 9);
                doc.setFontSize(10);
                doc.text(safeText(vehicle.patente) + ' - ' + safeText(vehicle.marca) + ' ' + safeText(vehicle.modelo), 38, 17);
                
                yPos = 30;
                doc.setTextColor(0, 0, 0);

                // Sección de datos principales con foto
                const dataStartY = yPos;
                let maxSectionHeight = 0;

                // Título
                doc.setFontSize(12);
                doc.setFont(undefined, 'bold');
                doc.setTextColor(30, 58, 138);
                doc.text('INFORMACIÓN GENERAL', margin, yPos);
                yPos += 8;

                // Datos principales (columna izquierda)
                doc.setFontSize(9);
                doc.setFont(undefined, 'normal');
                doc.setTextColor(0, 0, 0);
                
                doc.setFont(undefined, 'bold');
                doc.text('Patente:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.patente, margin + 25, yPos);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Marca:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.marca, margin + 25, yPos);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Modelo:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.modelo, margin + 25, yPos);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Año:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.anio ? vehicle.anio.toString() : 'No especificado', margin + 25, yPos);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Tipo:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicleTypeLabel(vehicle.tipo), margin + 25, yPos);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Estado:', margin, yPos);
                doc.setFont(undefined, 'normal');
                const estadoColor = vehicle.estado === 'activo' ? [22, 163, 74] : 
                                   vehicle.estado === 'mantenimiento' ? [234, 179, 8] : [150, 150, 150];
                doc.setTextColor(estadoColor[0], estadoColor[1], estadoColor[2]);
                doc.text(vehicle.estado ? vehicle.estado.charAt(0).toUpperCase() + vehicle.estado.slice(1) : 'N/A', margin + 25, yPos);
                doc.setTextColor(0, 0, 0);
                yPos += 5;
                
                doc.setFont(undefined, 'bold');
                doc.text('Kilometraje:', margin, yPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.kilometraje ? `${parseInt(vehicle.kilometraje).toLocaleString('es-AR')} km` : 'No especificado', margin + 25, yPos);
                yPos += 5;
                
                if (vehicle.combustible) {
                    doc.setFont(undefined, 'bold');
                    doc.text('Combustible:', margin, yPos);
                    doc.setFont(undefined, 'normal');
                    doc.text(vehicle.combustible.charAt(0).toUpperCase() + vehicle.combustible.slice(1), margin + 25, yPos);
                    yPos += 5;
                }

                maxSectionHeight = yPos - dataStartY;

                // Agregar foto si existe
                if (vehicle.foto) {
                    try {
                        const img = new Image();
                        img.src = vehicle.foto;
                        
                        await new Promise((resolve) => {
                            img.onload = resolve;
                            img.onerror = resolve;
                        });
                        
                        if (img.width && img.height) {
                            const maxPhotoWidth = 50;
                            const maxPhotoHeight = 50;
                            
                            let photoWidth = img.width * 0.264583;
                            let photoHeight = img.height * 0.264583;
                            
                            if (photoWidth > maxPhotoWidth) {
                                const ratio = maxPhotoWidth / photoWidth;
                                photoWidth = maxPhotoWidth;
                                photoHeight = photoHeight * ratio;
                            }
                            
                            if (photoHeight > maxPhotoHeight) {
                                const ratio = maxPhotoHeight / photoHeight;
                                photoHeight = maxPhotoHeight;
                                photoWidth = photoWidth * ratio;
                            }
                            
                            const photoX = pageWidth - margin - photoWidth;
                            const photoY = dataStartY;
                            
                            doc.setDrawColor(200, 200, 200);
                            doc.setLineWidth(0.5);
                            doc.rect(photoX - 1, photoY - 1, photoWidth + 2, photoHeight + 2);
                            doc.addImage(vehicle.foto, 'JPEG', photoX, photoY, photoWidth, photoHeight);
                            
                            if (photoHeight > maxSectionHeight) {
                                yPos = dataStartY + photoHeight;
                            }
                        }
                    } catch (e) {
                        console.log('No se pudo agregar foto del vehículo:', e);
                    }
                }

                yPos += 8;

                // Guardar posición inicial para ambos cuadros
                const boxesStartY = yPos;

                // Información técnica
                doc.setFillColor(245, 245, 250);
                doc.rect(margin, boxesStartY, (pageWidth - 2 * margin - 5) / 2, 30, 'F');
                doc.setDrawColor(200, 200, 200);
                doc.rect(margin, boxesStartY, (pageWidth - 2 * margin - 5) / 2, 30);
                
                doc.setFontSize(10);
                doc.setFont(undefined, 'bold');
                doc.setTextColor(30, 58, 138);
                doc.text('INFORMACIÓN TÉCNICA', margin + 3, boxesStartY + 6);
                doc.setFontSize(8);
                doc.setFont(undefined, 'normal');
                doc.setTextColor(0, 0, 0);
                let techYPos = boxesStartY + 12;
                
                if (vehicle.chasis) {
                    doc.text(`Nº Chasis: ${vehicle.chasis}`, margin + 3, techYPos);
                    techYPos += 4;
                }
                if (vehicle.motor) {
                    doc.text(`Nº Motor: ${vehicle.motor}`, margin + 3, techYPos);
                    techYPos += 4;
                }
                if (vehicle.conductor) {
                    doc.text('Conductor: ' + safeText(vehicle.conductor), margin + 3, techYPos);
                    techYPos += 4;
                }
                if (vehicle.sector) {
                    doc.text('Sector: ' + safeText(vehicle.sector), margin + 3, techYPos);
                    techYPos += 4;
                }
                
                // Documentación - altura aumentada para contener toda la información
                const docBoxX = margin + (pageWidth - 2 * margin - 5) / 2 + 5;
                const docBoxHeight = 55; // Aumentado de 30 a 55 para que quepa todo
                doc.setFillColor(245, 245, 250);
                doc.rect(docBoxX, boxesStartY, (pageWidth - 2 * margin - 5) / 2, docBoxHeight, 'F');
                doc.setDrawColor(200, 200, 200);
                doc.rect(docBoxX, boxesStartY, (pageWidth - 2 * margin - 5) / 2, docBoxHeight);
                
                doc.setFontSize(10);
                doc.setFont(undefined, 'bold');
                doc.setTextColor(30, 58, 138);
                doc.text('DOCUMENTACIÓN', docBoxX + 3, boxesStartY + 6);
                doc.setFontSize(8);
                doc.setFont(undefined, 'normal');
                let docYPos = boxesStartY + 12;
                
                // Cédula
                doc.setTextColor(0, 0, 0);
                doc.setFont(undefined, 'bold');
                doc.text('Cédula:', docBoxX + 3, docYPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.cedula || 'No especificado', docBoxX + 20, docYPos);
                if (vehicle.cedula_vencimiento) {
                    docYPos += 4;
                    const cedulaStatus = getVencimientoStatus(vehicle.cedula_vencimiento);
                    doc.text(`Venc: ${new Date(vehicle.cedula_vencimiento).toLocaleDateString('es-AR')}`, docBoxX + 6, docYPos);
                    doc.setTextColor(cedulaStatus.color[0], cedulaStatus.color[1], cedulaStatus.color[2]);
                    doc.setFont(undefined, 'bold');
                    doc.text(cedulaStatus.text, docBoxX + 40, docYPos);
                    doc.setFont(undefined, 'normal');
                    doc.setTextColor(0, 0, 0);
                }
                docYPos += 5;
                
                // Seguro
                doc.setFont(undefined, 'bold');
                doc.text('Seguro:', docBoxX + 3, docYPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.seguro || 'No especificado', docBoxX + 20, docYPos);
                if (vehicle.seguro_vencimiento) {
                    docYPos += 4;
                    const seguroStatus = getVencimientoStatus(vehicle.seguro_vencimiento);
                    doc.text(`Venc: ${new Date(vehicle.seguro_vencimiento).toLocaleDateString('es-AR')}`, docBoxX + 6, docYPos);
                    doc.setTextColor(seguroStatus.color[0], seguroStatus.color[1], seguroStatus.color[2]);
                    doc.setFont(undefined, 'bold');
                    doc.text(seguroStatus.text, docBoxX + 40, docYPos);
                    doc.setFont(undefined, 'normal');
                    doc.setTextColor(0, 0, 0);
                }
                if (vehicle.seguro_compania) {
                    docYPos += 4;
                    doc.text(`Compañía: ${vehicle.seguro_compania}`, docBoxX + 6, docYPos);
                }
                if (vehicle.seguro_poliza) {
                    docYPos += 4;
                    doc.text(`Póliza: ${vehicle.seguro_poliza}`, docBoxX + 6, docYPos);
                }
                docYPos += 5;
                
                // VTV
                doc.setFont(undefined, 'bold');
                doc.text('VTV:', docBoxX + 3, docYPos);
                doc.setFont(undefined, 'normal');
                doc.text(vehicle.vtv || 'No especificado', docBoxX + 20, docYPos);
                if (vehicle.vtv_vencimiento) {
                    docYPos += 4;
                    const vtvStatus = getVencimientoStatus(vehicle.vtv_vencimiento);
                    doc.text(`Venc: ${new Date(vehicle.vtv_vencimiento).toLocaleDateString('es-AR')}`, docBoxX + 6, docYPos);
                    doc.setTextColor(vtvStatus.color[0], vtvStatus.color[1], vtvStatus.color[2]);
                    doc.setFont(undefined, 'bold');
                    doc.text(vtvStatus.text, docBoxX + 40, docYPos);
                    doc.setFont(undefined, 'normal');
                    doc.setTextColor(0, 0, 0);
                }

                // Actualizar yPos para continuar después del cuadro más alto
                yPos = boxesStartY + Math.max(30, docBoxHeight) + 5;

                // Observaciones
                if (vehicle.observaciones) {
                    doc.setFillColor(254, 249, 195);
                    doc.rect(margin, yPos, pageWidth - 2 * margin, 20, 'F');
                    doc.setDrawColor(234, 179, 8);
                    doc.rect(margin, yPos, pageWidth - 2 * margin, 20);
                    
                    doc.setFontSize(9);
                    doc.setFont(undefined, 'bold');
                    doc.text('OBSERVACIONES:', margin + 3, yPos + 6);
                    doc.setFont(undefined, 'normal');
                    const obsLines = doc.splitTextToSize(vehicle.observaciones, pageWidth - 2 * margin - 10);
                    doc.text(obsLines, margin + 3, yPos + 11);
                    yPos += 25;
                }

                // Historial de inspecciones
                yPos += 5;
                doc.setFontSize(12);
                doc.setFont(undefined, 'bold');
                doc.setTextColor(30, 58, 138);
                doc.text('HISTORIAL DE INSPECCIONES', margin, yPos);
                yPos += 8;
                doc.setTextColor(0, 0, 0);

                if (vehicle.inspecciones && vehicle.inspecciones.length > 0) {
                    // Ordenar por fecha
                    const sortedInsp = [...vehicle.inspecciones].sort((a, b) => 
                        new Date(b.fecha) - new Date(a.fecha)
                    );
                    
                    doc.setFontSize(9);
                    doc.setFont(undefined, 'normal');
                    doc.text(`Total de inspecciones: ${vehicle.inspecciones.length}`, margin, yPos);
                    yPos += 7;
                    
                    // Headers de tabla de inspecciones
                    doc.setFillColor(230, 230, 235);
                    doc.rect(margin, yPos, pageWidth - 2 * margin, 7, 'F');
                    doc.setFontSize(8);
                    doc.setFont(undefined, 'bold');
                    doc.text('Fecha', margin + 2, yPos + 5);
                    doc.text('Inspector', margin + 30, yPos + 5);
                    doc.text('Kilometraje', margin + 80, yPos + 5);
                    doc.text('Estado', margin + 115, yPos + 5);
                    doc.text('Observaciones', margin + 145, yPos + 5);
                    yPos += 9;
                    
                    doc.setFont(undefined, 'normal');
                    doc.setFontSize(7);
                    
                    sortedInsp.forEach((insp, inspIdx) => {
                        if (checkPageBreak(8)) {
                            // Repetir headers
                            doc.setFillColor(230, 230, 235);
                            doc.rect(margin, yPos, pageWidth - 2 * margin, 7, 'F');
                            doc.setFontSize(8);
                            doc.setFont(undefined, 'bold');
                            doc.text('Fecha', margin + 2, yPos + 5);
                            doc.text('Inspector', margin + 30, yPos + 5);
                            doc.text('Kilometraje', margin + 80, yPos + 5);
                            doc.text('Estado', margin + 115, yPos + 5);
                            doc.text('Observaciones', margin + 145, yPos + 5);
                            yPos += 9;
                            doc.setFont(undefined, 'normal');
                            doc.setFontSize(7);
                        }
                        
                        if (inspIdx % 2 === 0) {
                            doc.setFillColor(250, 250, 252);
                            doc.rect(margin, yPos - 3, pageWidth - 2 * margin, 6, 'F');
                        }
                        
                        doc.text(new Date(insp.fecha).toLocaleDateString('es-AR'), margin + 2, yPos);
                        doc.text(insp.inspector.substring(0, 25), margin + 30, yPos);
                        doc.text(insp.kilometraje ? parseInt(insp.kilometraje).toLocaleString('es-AR') : 'N/D', margin + 80, yPos);
                        
                        const estadoText = insp.estado_general === 'apto' ? 'APTO' :
                                          insp.estado_general === 'apto_con_observaciones' ? 'APTO C/OBS' : 'NO APTO';
                        const estadoColor = insp.estado_general === 'apto' ? [22, 163, 74] :
                                           insp.estado_general === 'apto_con_observaciones' ? [234, 179, 8] : [220, 38, 38];
                        doc.setTextColor(estadoColor[0], estadoColor[1], estadoColor[2]);
                        doc.text(estadoText, margin + 115, yPos);
                        doc.setTextColor(0, 0, 0);
                        
                        const obs = insp.observaciones ? insp.observaciones.substring(0, 30) + (insp.observaciones.length > 30 ? '...' : '') : '-';
                        doc.text(obs, margin + 145, yPos);
                        
                        yPos += 6;
                    });
                } else {
                    doc.setFontSize(9);
                    doc.setFont(undefined, 'italic');
                    doc.setTextColor(150, 150, 150);
                    doc.text('No se han registrado inspecciones para este vehículo', margin, yPos);
                    doc.setTextColor(0, 0, 0);
                }
            }

            // Pie de página en todas las páginas
            const pageCount = doc.internal.getNumberOfPages();
            for (let i = 1; i <= pageCount; i++) {
                doc.setPage(i);
                addPdfFooter(doc, i, pageCount);
            }

            const fileName = `Flota-Completa-${(currentEstablishment.nombre || 'Sin_nombre').replace(/\s+/g, '-')}-${new Date().toISOString().split('T')[0]}.pdf`;
            exportPdf(doc, fileName, mode);
        }




        // ============= MACHINERY MANAGEMENT FUNCTIONS =============
        let machineryInspectionPhotosData = [];
        let currentEditMachineryId = null;
        let machineryPhotoRemoved = false;

