        async function deleteSurvey(id) { if (!await appConfirm('¿Eliminar esta encuesta?')) return; appData.surveys = appData.surveys.filter(s => s.id !== id); saveData(); loadSurveys(); }

        async function exportSatisfactionPDF(mode) {
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            const surveys = (appData.surveys || []).filter(s => s.establecimiento_id === currentEstablishment.id);
            if (surveys.length === 0) { alert('No hay encuestas para exportar'); return; }
            
            const { jsPDF } = window.jspdf; 
            const doc = new jsPDF();
            const pdfTitle = 'Informe de Satisfacción del Cliente';
            let yPos = addPdfHeader(doc, pdfTitle);
            
            const tipoLabels = { 'encuesta': 'Encuesta', 'queja': 'Queja', 'reclamo': 'Reclamo', 'sugerencia': 'Sugerencia', 'felicitacion': 'Felicitación' };
            
            // RESUMEN EJECUTIVO
            doc.setTextColor(0, 0, 0); 
            doc.setFontSize(11); 
            doc.setFont(undefined, 'bold');
            doc.text('RESUMEN EJECUTIVO', 15, yPos); 
            yPos += 7;
            
            doc.setFont(undefined, 'normal'); 
            doc.setFontSize(9);
            const introText = 'El presente informe analiza la satisfacción del cliente del establecimiento "' + currentEstablishment.nombre + '", conforme al requisito 9.1.2 de ISO 9001:2015. El seguimiento de la percepción del cliente es fundamental para la mejora continua del Sistema de Gestión de Calidad.';
            const splitIntro = doc.splitTextToSize(introText, 180);
            doc.text(splitIntro, 15, yPos); 
            yPos += splitIntro.length * 4 + 6;
            
            // Estadísticas
            const encuestas = surveys.filter(s => s.tipo === 'encuesta');
            const quejas = surveys.filter(s => s.tipo === 'queja' || s.tipo === 'reclamo').length;
            let avgSat = 0;
            if (encuestas.length > 0) {
                avgSat = encuestas.reduce((acc, s) => acc + ((s.calif_calidad || 0) + (s.calif_tiempo || 0) + (s.calif_comunicacion || 0)) / 3, 0) / encuestas.length;
            }
            let nps = 0;
            if (encuestas.length > 0) {
                const promoters = encuestas.filter(s => (s.calif_nps || 0) >= 9).length;
                const detractors = encuestas.filter(s => (s.calif_nps || 0) <= 6).length;
                nps = Math.round(((promoters - detractors) / encuestas.length) * 100);
            }
            
            // Cuadro de métricas
            doc.setFillColor(240, 253, 244);
            doc.rect(15, yPos, 180, 20, 'F');
            doc.setFontSize(9);
            doc.text('Total Registros: ' + surveys.length, 20, yPos + 7);
            doc.text('Encuestas: ' + encuestas.length, 60, yPos + 7);
            doc.text('Quejas/Reclamos: ' + quejas, 100, yPos + 7);
            doc.setFont(undefined, 'bold');
            doc.text('Satisfacción Promedio: ' + avgSat.toFixed(1) + '/10', 20, yPos + 15);
            doc.text('NPS (Net Promoter Score): ' + nps, 100, yPos + 15);
            yPos += 28;
            
            // DETALLE DE REGISTROS
            doc.setFont(undefined, 'bold');
            doc.setFontSize(11);
            doc.text('DETALLE DE REGISTROS', 15, yPos); 
            yPos += 7;
            
            const tableData = surveys.map(s => [
                s.fecha ? new Date(s.fecha).toLocaleDateString('es-AR') : '-',
                s.cliente || '-',
                tipoLabels[s.tipo] || s.tipo || '-',
                s.servicio || '-',
                s.calif_nps ? s.calif_nps + '/10' : '-'
            ]);
            
            doc.autoTable({ 
                startY: yPos, 
                head: [['Fecha', 'Cliente', 'Tipo', 'Servicio', 'NPS']], 
                body: tableData, 
                theme: 'grid', 
                headStyles: { fillColor: [15, 115, 197], fontSize: 8, fontStyle: 'bold' }, 
                bodyStyles: { fontSize: 8 },
                columnStyles: {
                    4: { halign: 'center' }
                },
                didParseCell: function(data) {
                    if (data.section === 'body' && data.column.index === 2) {
                        const val = data.cell.raw;
                        if (val === 'Queja' || val === 'Reclamo') { data.cell.styles.textColor = [220, 38, 38]; }
                        else if (val === 'Felicitación') { data.cell.styles.textColor = [34, 197, 94]; }
                    }
                },
                didDrawPage: function(data) {
                    // Agregar encabezado en páginas adicionales
                    if (data.pageNumber > 1) {
                        addPdfHeader(doc, pdfTitle);
                    }
                },
                margin: { left: 15, right: 15, top: 45 } 
            });
            yPos = doc.lastAutoTable.finalY + 10;
            
            // INTERPRETACIÓN
            if (yPos < 250) {
                doc.setFont(undefined, 'bold');
                doc.setFontSize(11);
                doc.text('INTERPRETACIÓN DEL NPS', 15, yPos); 
                yPos += 7;
                doc.setFont(undefined, 'normal');
                doc.setFontSize(8);
                doc.text('- NPS > 50: Excelente - Clientes muy satisfechos y leales', 15, yPos); yPos += 4;
                doc.text('- NPS 0 a 50: Bueno - Hay espacio para mejorar', 15, yPos); yPos += 4;
                doc.text('- NPS < 0: Crítico - Se requieren acciones correctivas urgentes', 15, yPos);
            }
            
            const totalPages = doc.internal.getNumberOfPages();
            for (let i = 1; i <= totalPages; i++) { doc.setPage(i); addPdfFooter(doc, i, totalPages); }
            exportPdf(doc, 'Satisfaccion_' + (currentEstablishment.nombre || 'Sin_nombre').replace(/\s+/g, '_') + '.pdf', mode);
        }

        // ==========================================
        // MÓDULO NO CONFORMIDADES
        // ==========================================

        let editingNCId = null;

        function loadNonconformities() {
            if (!currentEstablishment) return;
            const ncs = (appData.nonconformities || []).filter(n => n.establecimiento_id === currentEstablishment.id);
            const closed = ncs.filter(n => n.estado === 'cerrada').length;
            document.getElementById('ncTotal').textContent = ncs.length;
            document.getElementById('ncOpen').textContent = ncs.filter(n => n.estado !== 'cerrada').length;
            document.getElementById('ncClosed').textContent = closed;
            document.getElementById('ncEfficacy').textContent = closed > 0 ? Math.round((ncs.filter(n => n.estado === 'cerrada' && n.eficaz === true).length / closed) * 100) + '%' : '-%';
            const list = document.getElementById('ncList');
            if (ncs.length === 0) { list.innerHTML = '<p class="text-gray-500 text-center py-4">No hay no conformidades registradas</p>'; return; }
            const clasifColors = { 'mayor': 'red', 'menor': 'yellow', 'observacion': 'blue', 'oportunidad_mejora': 'green' };
            const clasifLabels = { 'mayor': 'NC MAYOR', 'menor': 'NC MENOR', 'observacion': 'OBSERVACIÓN', 'oportunidad_mejora': 'OPORTUNIDAD' };
            const sorted = [...ncs].sort((a, b) => new Date(b.fecha) - new Date(a.fecha));
            list.innerHTML = sorted.map(function(n) {
                const color = clasifColors[n.clasificacion] || 'gray';
                return '<div class="border rounded-lg p-3 border-l-4 border-' + color + '-500 hover:shadow-md transition">' +
                    '<div class="flex justify-between items-start flex-wrap gap-2">' +
                        '<div class="flex-1">' +
                            '<div class="flex items-center gap-2 mb-1">' +
                                '<span class="px-2 py-0.5 rounded text-xs font-semibold bg-' + color + '-100 text-' + color + '-800">' + (clasifLabels[n.clasificacion] || 'NC') + '</span>' +
                                '<span class="text-xs text-gray-500">' + new Date(n.fecha).toLocaleDateString('es-AR') + '</span>' +
                            '</div>' +
                            '<h4 class="font-semibold text-gray-800 text-sm">' + n.area + '</h4>' +
                            '<p class="text-xs text-gray-600 mt-1">' + ((n.descripcion || '').substring(0, 100)) + (n.descripcion && n.descripcion.length > 100 ? '...' : '') + '</p>' +
                        '</div>' +
                        '<div class="flex flex-col items-end gap-1">' +
                            '<span class="px-2 py-0.5 rounded-full text-xs font-semibold ' + (n.estado === 'cerrada' ? 'bg-green-100 text-green-800' : 'bg-orange-100 text-orange-800') + '">' + (n.estado === 'cerrada' ? 'Cerrada' : 'Abierta') + '</span>' +
                            '<div class="flex gap-2">' +
                                '<button onclick="editNC(\'' + n.id + '\')" class="text-blue-600 hover:text-blue-800 text-sm"><i class="fas fa-edit"></i></button>' +
                                (n.estado !== 'cerrada' ? '<button onclick="closeNC(\'' + n.id + '\')" class="text-green-600 hover:text-green-800 text-sm"><i class="fas fa-check"></i></button>' : '') +
                                signedAttachBtn('nc', n.id) + '<button onclick="deleteNC(\'' + n.id + '\')" class="text-red-600 hover:text-red-800 text-sm"><i class="fas fa-trash"></i></button>' +
                            '</div>' +
                        '</div>' +
                    '</div>' +
                '</div>';
            }).join('');
        }

        function showNewNC() { 
            editingNCId = null;
            document.getElementById('ncFormTitle').textContent = 'Nueva No Conformidad';
            document.getElementById('ncForm').classList.remove('hidden'); 
            document.getElementById('ncFormElement').reset(); 
            document.querySelector('#ncFormElement input[name="fecha"]').valueAsDate = new Date(); 
        }
        function cancelNewNC() { document.getElementById('ncForm').classList.add('hidden'); editingNCId = null; }

        function editNC(id) {
            const nc = appData.nonconformities.find(n => n.id === id);
            if (!nc) return;
            editingNCId = id;
            document.getElementById('ncFormTitle').textContent = 'Editar No Conformidad';
            document.getElementById('ncForm').classList.remove('hidden');
            const form = document.getElementById('ncFormElement');
            form.querySelector('[name="fecha"]').value = nc.fecha;
            form.querySelector('[name="origen"]').value = nc.origen || '';
            form.querySelector('[name="clasificacion"]').value = nc.clasificacion || '';
            form.querySelector('[name="area"]').value = nc.area || '';
            form.querySelector('[name="requisito"]').value = nc.requisito || '';
            form.querySelector('[name="descripcion"]').value = nc.descripcion || '';
            form.querySelector('[name="correccion"]').value = nc.correccion || '';
            form.querySelector('[name="causa_raiz"]').value = nc.causa_raiz || '';
            form.querySelector('[name="accion_correctiva"]').value = nc.accion_correctiva || '';
            form.querySelector('[name="responsable"]').value = nc.responsable || '';
            form.querySelector('[name="fecha_compromiso"]').value = nc.fecha_compromiso || '';
        }

        function saveNC(event) {
            event.preventDefault();
            const form = event.target; const formData = new FormData(form);
            const ncData = { 
                establecimiento_id: currentEstablishment.id, 
                fecha: formData.get('fecha'), 
                origen: formData.get('origen'), 
                clasificacion: formData.get('clasificacion'), 
                area: formData.get('area'), 
                requisito: formData.get('requisito'), 
                descripcion: formData.get('descripcion'), 
                correccion: formData.get('correccion'), 
                causa_raiz: formData.get('causa_raiz'), 
                accion_correctiva: formData.get('accion_correctiva'), 
                responsable: formData.get('responsable'), 
                fecha_compromiso: formData.get('fecha_compromiso')
            };
            
            if (editingNCId) {
                const idx = appData.nonconformities.findIndex(n => n.id === editingNCId);
                if (idx !== -1) {
                    appData.nonconformities[idx] = { ...appData.nonconformities[idx], ...ncData };
                }
            } else {
                ncData.id = 'NC' + Date.now();
                ncData.estado = 'abierta';
                ncData.created_at = new Date().toISOString();
                if (!appData.nonconformities) appData.nonconformities = [];
                appData.nonconformities.push(ncData);
            }
            saveData(); cancelNewNC(); loadNonconformities(); 
            alert(editingNCId ? 'No Conformidad actualizada' : 'No Conformidad registrada');
        }

        async function closeNC(id) { const nc = appData.nonconformities.find(n => n.id === id); if (nc) { const eficaz = await appChoice('¿La acción correctiva fue eficaz?', [{ label: 'No fue eficaz', value: false }, { label: 'Sí, fue eficaz', value: true, primary: true }], { title: 'Cerrar no conformidad' }); if (eficaz === null) return; nc.estado = 'cerrada'; nc.fecha_cierre = new Date().toISOString(); nc.eficaz = eficaz; saveData(); loadNonconformities(); alert('NC cerrada'); } }
        async function deleteNC(id) { if (!await appConfirm('¿Eliminar esta NC?')) return; appData.nonconformities = appData.nonconformities.filter(n => n.id !== id); saveData(); loadNonconformities(); }

        async function exportNCPDF(mode) {
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            const ncs = (appData.nonconformities || []).filter(n => n.establecimiento_id === currentEstablishment.id);
            if (ncs.length === 0) { alert('No hay NC para exportar'); return; }
            
            const { jsPDF } = window.jspdf; 
            const doc = new jsPDF();
            const pdfTitle = 'Registro de No Conformidades';
            let yPos = addPdfHeader(doc, pdfTitle);
            
            // Mapeo de etiquetas
            const clasifLabels = { 'mayor': 'NC Mayor', 'menor': 'NC Menor', 'observacion': 'Observación', 'oportunidad_mejora': 'Oportunidad de Mejora' };
            const origenLabels = { 'auditoria_interna': 'Auditoría Interna', 'auditoria_externa': 'Auditoría Externa', 'queja_cliente': 'Queja de Cliente', 'inspeccion': 'Inspección', 'revision_direccion': 'Revisión por la Dirección', 'proceso': 'Control de Proceso', 'otro': 'Otro' };
            
            // RESUMEN EJECUTIVO
            doc.setTextColor(0, 0, 0); 
            doc.setFontSize(11); 
            doc.setFont(undefined, 'bold');
            doc.text('RESUMEN EJECUTIVO', 15, yPos); 
            yPos += 7;
            
            doc.setFont(undefined, 'normal'); 
            doc.setFontSize(9);
            const introText = 'El presente registro documenta las no conformidades identificadas en el establecimiento "' + currentEstablishment.nombre + '", conforme al requisito 10.2 de ISO 9001:2015. El tratamiento adecuado de las no conformidades es esencial para la mejora continua del Sistema de Gestión de Calidad.';
            const splitIntro = doc.splitTextToSize(introText, 180);
            doc.text(splitIntro, 15, yPos); 
            yPos += splitIntro.length * 4 + 6;
            
            // Estadísticas
            const abiertas = ncs.filter(n => n.estado !== 'cerrada').length;
            const cerradas = ncs.filter(n => n.estado === 'cerrada').length;
            const mayores = ncs.filter(n => n.clasificacion === 'mayor').length;
            const eficaces = ncs.filter(n => n.estado === 'cerrada' && n.eficaz === true).length;
            const eficacia = cerradas > 0 ? Math.round((eficaces / cerradas) * 100) : 0;
            
            // Cuadro de métricas
            doc.setFillColor(255, 245, 245);
            doc.rect(15, yPos, 180, 20, 'F');
            doc.setFontSize(9);
            doc.text('Total NC: ' + ncs.length, 20, yPos + 7);
            doc.text('Abiertas: ' + abiertas, 55, yPos + 7);
            doc.text('Cerradas: ' + cerradas, 90, yPos + 7);
            doc.text('NC Mayores: ' + mayores, 125, yPos + 7);
            doc.setFont(undefined, 'bold');
            doc.text('Eficacia de Acciones Correctivas: ' + eficacia + '%', 20, yPos + 15);
            yPos += 28;
            
            // DETALLE
            doc.setFont(undefined, 'bold');
            doc.setFontSize(11);
            doc.text('REGISTRO DE NO CONFORMIDADES', 15, yPos); 
            yPos += 7;
            
            const tableData = ncs.map(n => [
                n.fecha ? new Date(n.fecha).toLocaleDateString('es-AR') : '-',
                clasifLabels[n.clasificacion] || n.clasificacion || '-',
                n.area || '-',
                origenLabels[n.origen] || n.origen || '-',
                n.estado === 'cerrada' ? 'Cerrada' : 'Abierta'
            ]);
            
            doc.autoTable({ 
                startY: yPos, 
                head: [['Fecha', 'Clasificación', 'Área', 'Origen', 'Estado']], 
                body: tableData, 
                theme: 'grid', 
                headStyles: { fillColor: [15, 115, 197], fontSize: 8, fontStyle: 'bold' }, 
                bodyStyles: { fontSize: 8 },
                columnStyles: {
                    0: { cellWidth: 25 },
                    1: { cellWidth: 35 },
                    2: { cellWidth: 45 },
                    3: { cellWidth: 45 },
                    4: { cellWidth: 25, halign: 'center' }
                },
                didParseCell: function(data) {
                    if (data.section === 'body') {
                        if (data.column.index === 1) {
                            const val = data.cell.raw;
                            if (val === 'NC Mayor') { data.cell.styles.textColor = [220, 38, 38]; data.cell.styles.fontStyle = 'bold'; }
                            else if (val === 'NC Menor') { data.cell.styles.textColor = [234, 179, 8]; }
                        }
                        if (data.column.index === 4) {
                            const val = data.cell.raw;
                            if (val === 'Cerrada') { data.cell.styles.textColor = [34, 197, 94]; data.cell.styles.fontStyle = 'bold'; }
                            else { data.cell.styles.textColor = [234, 179, 8]; }
                        }
                    }
                },
                didDrawPage: function(data) {
                    // Agregar encabezado en páginas adicionales
                    if (data.pageNumber > 1) {
                        addPdfHeader(doc, pdfTitle);
                    }
                },
                margin: { left: 15, right: 15, top: 45 } 
            });
            yPos = doc.lastAutoTable.finalY + 10;
            
            // METODOLOGÍA
            if (yPos < 240) {
                doc.setFont(undefined, 'bold');
                doc.setFontSize(11);
                doc.text('METODOLOGÍA DE TRATAMIENTO', 15, yPos); 
                yPos += 7;
                doc.setFont(undefined, 'normal');
                doc.setFontSize(8);
                doc.text('- Identificación y registro de la no conformidad', 15, yPos); yPos += 4;
                doc.text('- Análisis de causa raíz (metodología 5 Por qué, Ishikawa, etc.)', 15, yPos); yPos += 4;
                doc.text('- Definición e implementación de acciones correctivas', 15, yPos); yPos += 4;
                doc.text('- Verificación de eficacia y cierre', 15, yPos);
            }
            
            const totalPages = doc.internal.getNumberOfPages();
            for (let i = 1; i <= totalPages; i++) { doc.setPage(i); addPdfFooter(doc, i, totalPages); }
            exportPdf(doc, 'No_Conformidades_' + (currentEstablishment.nombre || 'Sin_nombre').replace(/\s+/g, '_') + '.pdf', mode);
        }

        // ============= GLOSARIO SRT FUNCTIONS =============
        const glossaryData = {
            definiciones: {
                titulo: 'Definiciones Básicas',
                icono: 'fa-file-alt',
                color: 'blue',
                items: [
                    { termino: 'Accidente de Trabajo', definicion: 'Acontecimiento súbito y violento ocurrido por el hecho o en ocasión del trabajo, o en el trayecto entre el domicilio del trabajador y el lugar de trabajo (in itinere). Ley 24.557 Art. 6°.', normativa: 'Ley 24.557', ejemplo: 'Operario sufre corte en mano al manipular chapa metálica durante su jornada laboral' },
                    { termino: 'Accidente In Itinere', definicion: 'Accidente ocurrido en el trayecto directo entre el domicilio del trabajador y el lugar de trabajo, o viceversa, siempre que no se hubiere alterado dicho trayecto por causas ajenas al trabajo.', normativa: 'Ley 24.557', ejemplo: 'Trabajador es atropellado al cruzar la calle camino a la fábrica' },
                    { termino: 'Enfermedad Profesional', definicion: 'Enfermedad producida por causa del lugar o del tipo de trabajo, incluida en el Listado de Enfermedades Profesionales (Decreto 658/96), que identifica agente de riesgo, cuadros clínicos, exposición y actividades.', normativa: 'Ley 24.557, Dec. 658/96', ejemplo: 'Minero desarrolla silicosis por exposición prolongada a polvo de sílice' },
                    { termino: 'Incidente', definicion: 'Suceso en el curso del trabajo o en relación con el trabajo, en el que la persona afectada no sufre lesiones corporales. El daño es solo material.', normativa: 'Res. SRT', ejemplo: 'Cae una herramienta desde altura pero no golpea a nadie, solo daña el piso' },
                    { termino: 'Peligro', definicion: 'Fuente, situación o acto con potencial de causar daño en términos de lesión o enfermedad, o una combinación de ambas. Es la capacidad intrínseca de provocar daño.', normativa: 'ISO 45001', ejemplo: 'Cables eléctricos expuestos, sustancias químicas inflamables, máquinas sin protección' },
                    { termino: 'Riesgo', definicion: 'Probabilidad de que un peligro se materialice y genere daño. Combinación de la probabilidad de ocurrencia de un evento peligroso y la severidad de la lesión o enfermedad.', normativa: 'ISO 45001', ejemplo: 'Probabilidad alta de caída al trabajar en andamio sin barandas a 5 metros de altura' },
                    { termino: 'Condición Insegura', definicion: 'Causa imputable a la maquinaria, equipo, herramientas o ambiente físico, cuya presencia genera el accidente. Ejemplos: pisos resbaladizos, equipos defectuosos, falta de señalización.', normativa: 'Dec. 351/79', ejemplo: 'Piso mojado sin señalizar, escalera sin pasamanos, iluminación deficiente' },
                    { termino: 'Acto Inseguro', definicion: 'Error humano, consciente o no, que produce un accidente. Acciones u omisiones del trabajador que contravienen las normas de seguridad establecidas.', normativa: 'Dec. 351/79', ejemplo: 'No usar casco en obra, operar máquina sin capacitación, anular dispositivos de seguridad' },
                    { termino: 'Incapacidad Laboral Temporaria (ILT)', definicion: 'Situación en la que el trabajador se encuentra imposibilitado temporariamente para realizar su trabajo habitual, precisando asistencia sanitaria durante ese período.', normativa: 'Ley 24.557', ejemplo: 'Trabajador con fractura de muñeca que requiere 45 días de reposo antes de volver' },
                    { termino: 'Incapacidad Laboral Permanente (ILP)', definicion: 'Daño producido por accidente o enfermedad profesional que ocasiona una disminución permanente en la capacidad de trabajo. Puede ser parcial (<66%) o total (≥66%).', normativa: 'Ley 24.557', ejemplo: 'Amputación de dedo que genera incapacidad permanente parcial del 12%' },
                    { termino: 'Gran Invalidez', definicion: 'Situación en que el trabajador con Incapacidad Laboral Permanente Total necesita asistencia continua de otra persona para realizar los actos elementales de la vida.', normativa: 'Ley 24.557', ejemplo: 'Paraplejia por accidente que requiere asistencia permanente para actividades básicas' },
                    { termino: 'Reingreso', definicion: 'Accidente o enfermedad profesional previamente notificado que, habiendo cesado la ILT, reingresa al sistema por reagravación del cuadro.', normativa: 'Res. SRT', ejemplo: 'Trabajador dado de alta por lumbalgia que se reagrava y requiere nueva licencia' },
                    { termino: 'ART (Aseguradora de Riesgos del Trabajo)', definicion: 'Empresa privada contratada por empleadores para asesorar en prevención de riesgos y reparar daños por accidentes de trabajo o enfermedades profesionales.', normativa: 'Ley 24.557', ejemplo: 'Provincia ART, Galeno ART, Experta ART, La Segunda ART' },
                    { termino: 'SRT (Superintendencia de Riesgos del Trabajo)', definicion: 'Organismo estatal encargado de controlar a las ART, garantizar prestaciones, promover la prevención e imponer sanciones según la Ley 24.557.', normativa: 'Ley 24.557', ejemplo: 'Ente que fiscaliza el cumplimiento normativo y recibe denuncias de trabajadores' }
                ]
            },
            tipos_riesgo: {
                titulo: 'Tipos de Riesgo Laboral',
                icono: 'fa-exclamation-triangle',
                color: 'red',
                items: [
                    { termino: 'Riesgo Físico', definicion: 'Riesgo derivado de distintas formas de energía (mecánica, térmica, electromagnética) presentes en el ambiente laboral: ruido, vibraciones, radiaciones, temperaturas extremas, iluminación inadecuada, presión atmosférica anormal.', normativa: 'Dec. 351/79', ejemplo: 'Operador de martillo neumático expuesto a ruido de 95 dB durante 8 horas' },
                    { termino: 'Riesgo Químico', definicion: 'Riesgo por exposición a sustancias químicas en forma de gases, vapores, aerosoles, polvos, humos o nieblas que pueden producir efectos irritantes, tóxicos, corrosivos, sensibilizantes, cancerígenos o asfixiantes.', normativa: 'Dec. 351/79, Res. 295/03', ejemplo: 'Pintor expuesto a vapores de solventes en cabina sin ventilación adecuada' },
                    { termino: 'Riesgo Biológico', definicion: 'Riesgo derivado de la exposición a microorganismos vivos (bacterias, virus, hongos, parásitos) que pueden causar enfermedades infecciosas o parasitarias.', normativa: 'Dec. 351/79', ejemplo: 'Enfermero que manipula sangre y fluidos de pacientes con hepatitis B' },
                    { termino: 'Riesgo Ergonómico', definicion: 'Riesgo asociado a la carga física del trabajo: posturas forzadas, movimientos repetitivos, manipulación manual de cargas, bipedestación prolongada. Puede causar trastornos músculo-esqueléticos.', normativa: 'Res. 295/03, Dec. 49/14', ejemplo: 'Cajera de supermercado con movimientos repetitivos de muñeca 6 horas diarias' },
                    { termino: 'Riesgo Psicosocial', definicion: 'Factores organizacionales y psicosociales que pueden afectar la salud mental: estrés laboral, carga mental excesiva, violencia laboral, burnout, acoso laboral.', normativa: 'Res. SRT', ejemplo: 'Operador de call center con alta demanda, metas inalcanzables y hostigamiento' },
                    { termino: 'Riesgo Mecánico', definicion: 'Riesgo generado por máquinas, equipos, herramientas y elementos móviles: atrapamiento, cortes, golpes, proyección de partículas, caída de objetos.', normativa: 'Dec. 351/79 Cap. 15', ejemplo: 'Operario de torno sin protección ante viruta proyectada a alta velocidad' },
                    { termino: 'Riesgo Eléctrico', definicion: 'Riesgo de contacto con corriente eléctrica: electrocución, quemaduras, incendio por cortocircuito. Incluye contacto directo e indirecto.', normativa: 'Dec. 351/79 Cap. 14', ejemplo: 'Electricista trabajando en tablero de 380V sin bloqueo ni EPP dieléctrico' },
                    { termino: 'Riesgo Locativo', definicion: 'Riesgo derivado de las condiciones de las instalaciones: pisos, escaleras, pasillos, orden y limpieza, almacenamiento, señalización deficiente.', normativa: 'Dec. 351/79', ejemplo: 'Depósito con estanterías sobrecargadas y pasillos obstruidos con materiales' },
                    { termino: 'Riesgo de Incendio', definicion: 'Posibilidad de ocurrencia de fuego no controlado. Se evalúa mediante carga de fuego, clasificación de materiales y sistemas de protección.', normativa: 'Dec. 351/79 Cap. 18', ejemplo: 'Taller de carpintería con acumulación de viruta y aserrín cerca de fuentes de calor' },
                    { termino: 'Riesgo de Explosión', definicion: 'Riesgo de liberación violenta de energía por reacción química o física: atmósferas explosivas, recipientes a presión, sustancias inflamables.', normativa: 'Dec. 351/79', ejemplo: 'Estación de servicio con vapores de nafta en concentración explosiva' }
                ]
            },
            agentes: {
                titulo: 'Agentes de Riesgo',
                icono: 'fa-biohazard',
                color: 'orange',
                items: [
                    { termino: 'Ruido', definicion: 'Agente físico. Límite permisible: 85 dB(A) para 8 horas de exposición. Puede causar hipoacusia inducida por ruido. Código SRT: 40001.', normativa: 'Res. 295/03', ejemplo: 'Prensa hidráulica de 92 dB, sierra circular de 98 dB, martillo neumático de 105 dB' },
                    { termino: 'Vibraciones', definicion: 'Agente físico. Pueden ser de cuerpo entero (vehículos, plataformas) o mano-brazo (herramientas vibrátiles). Causan trastornos vasculares y osteoarticulares.', normativa: 'Res. 295/03', ejemplo: 'Conductor de autoelevador (cuerpo entero), operador de amoladora (mano-brazo)' },
                    { termino: 'Radiaciones Ionizantes', definicion: 'Agente físico. Rayos X, gamma, partículas alfa, beta. Pueden causar efectos determinísticos y estocásticos. Requiere dosimetría personal.', normativa: 'Res. SRT', ejemplo: 'Técnico radiólogo en hospital, operador de gammagrafía industrial' },
                    { termino: 'Radiaciones No Ionizantes', definicion: 'Agente físico. Ultravioleta, infrarroja, microondas, láser. Pueden causar lesiones oculares y cutáneas.', normativa: 'Res. 295/03', ejemplo: 'Soldador expuesto a UV, operador de horno industrial con IR, técnico con láser' },
                    { termino: 'Estrés Térmico por Calor', definicion: 'Agente termohigrométrico. Se evalúa mediante índice TGBH. Puede causar golpe de calor, agotamiento, calambres.', normativa: 'Res. 295/03', ejemplo: 'Trabajador de fundición expuesto a 38°C con humedad del 70%' },
                    { termino: 'Estrés Térmico por Frío', definicion: 'Agente termohigrométrico. Exposición a temperaturas bajas. Puede causar hipotermia, congelamiento, enfermedad de Raynaud.', normativa: 'Res. 295/03', ejemplo: 'Operario de cámara frigorífica a -18°C, trabajador de pesca en alta mar' },
                    { termino: 'Sílice Cristalina', definicion: 'Agente químico. Polvo de cuarzo, cristobalita, tridimita. Causa silicosis (neumoconiosis). Presente en minería, construcción, fundiciones.', normativa: 'Dec. 658/96', ejemplo: 'Perforista de mina, arenador, cortador de piedra, pulidor de granito' },
                    { termino: 'Asbesto/Amianto', definicion: 'Agente químico cancerígeno. Prohibido en Argentina (Res. 823/01). Causa mesotelioma y asbestosis. Código SRT: 10001.', normativa: 'Dec. 658/96, Res. 823/01', ejemplo: 'Trabajador de mantenimiento que retira aislaciones antiguas con amianto' },
                    { termino: 'Plomo', definicion: 'Agente químico. Metal pesado que causa saturnismo. Presente en fundiciones, fabricación de baterías, pinturas. Código SRT: 10301.', normativa: 'Dec. 658/96', ejemplo: 'Fundidor de plomo, fabricante de baterías, soldador con estaño-plomo' },
                    { termino: 'Mercurio', definicion: 'Agente químico. Metal líquido que causa hidrargirismo. Afecta sistema nervioso central. Presente en termómetros, amalgamas, electroquímica.', normativa: 'Dec. 658/96', ejemplo: 'Trabajador de planta cloro-álcali, odontólogo con amalgamas, minero artesanal' },
                    { termino: 'Benceno', definicion: 'Agente químico cancerígeno (leucemia). Solvente presente en industria petroquímica, pinturas. Límite: 0.5 ppm. Código SRT: 10101.', normativa: 'Dec. 658/96, Res. 81/19', ejemplo: 'Operador de refinería de petróleo, trabajador de estación de servicio' },
                    { termino: 'Isocianatos', definicion: 'Agentes químicos sensibilizantes. Causan asma ocupacional. Presentes en pinturas de poliuretano, espumas, adhesivos.', normativa: 'Dec. 658/96', ejemplo: 'Pintor automotriz con poliuretano, fabricante de colchones de espuma' },
                    { termino: 'Mycobacterium Tuberculosis', definicion: 'Agente biológico. Causa tuberculosis ocupacional. Personal de salud, laboratorios, cárceles son poblaciones expuestas.', normativa: 'Dec. 658/96', ejemplo: 'Enfermero de sala de neumotisiología, personal penitenciario' },
                    { termino: 'Virus Hepatitis B y C', definicion: 'Agentes biológicos. Transmisión parenteral. Personal de salud expuesto. Requiere vacunación y medidas de bioseguridad.', normativa: 'Dec. 658/96', ejemplo: 'Cirujano, instrumentista quirúrgico, técnico de laboratorio de análisis clínicos' },
                    { termino: 'Carga Física - Columna Vertebral', definicion: 'Agente ergonómico. Manipulación manual de cargas, posturas forzadas. Causa lumbalgias, hernias de disco. Tablas de peso máximo en Res. 295/03.', normativa: 'Dec. 49/14, Res. 295/03', ejemplo: 'Estibador que carga bolsas de 50 kg, albañil levantando ladrillos repetidamente' },
                    { termino: 'Movimientos Repetitivos', definicion: 'Agente ergonómico. Gestos repetitivos de miembros superiores. Causa síndrome del túnel carpiano, tendinitis, epicondilitis.', normativa: 'Dec. 49/14', ejemplo: 'Operaria de línea de empaque con 15.000 movimientos por jornada' }
                ]
            },
            formas_accidente: {
                titulo: 'Formas de Accidente',
                icono: 'fa-bolt',
                color: 'yellow',
                items: [
                    { termino: 'Caída de personas a nivel', definicion: 'Caída al mismo nivel por resbalones, tropiezos o traspiés. Una de las formas más frecuentes. Código: 01.', normativa: 'Res. SRT 1604/07', ejemplo: 'Trabajador resbala en piso mojado del comedor, tropiezo con cable en pasillo' },
                    { termino: 'Caída de personas a distinto nivel', definicion: 'Caída desde altura: escaleras, andamios, techos, pozos, excavaciones. Alta gravedad potencial. Código: 02.', normativa: 'Res. SRT 1604/07', ejemplo: 'Albañil cae de andamio de 4 metros, operario cae por hueco de ascensor' },
                    { termino: 'Caída de objetos', definicion: 'Incluye desplome de estructuras, objetos que caen durante manipulación, objetos desprendidos. Código: 03.', normativa: 'Res. SRT 1604/07', ejemplo: 'Herramienta cae desde andamio y golpea a trabajador, derrumbe de estantería' },
                    { termino: 'Pisadas sobre objetos', definicion: 'Pisar objetos punzantes, cortantes o irregulares (clavos, vidrios, herramientas). Código: 04.', normativa: 'Res. SRT 1604/07', ejemplo: 'Obrero pisa clavo que atraviesa la suela, trabajador pisa vidrio roto' },
                    { termino: 'Choque contra objetos', definicion: 'Golpe del trabajador contra objetos fijos o móviles. Incluye choques con maquinaria, mobiliario, estructuras. Código: 05.', normativa: 'Res. SRT 1604/07', ejemplo: 'Operario golpea cabeza contra viga baja, choque contra puerta de vidrio' },
                    { termino: 'Golpes por objetos', definicion: 'Impacto de objetos contra el trabajador: herramientas, piezas, objetos proyectados. Código: 06.', normativa: 'Res. SRT 1604/07', ejemplo: 'Partícula metálica proyectada por amoladora, martillo que golpea mano' },
                    { termino: 'Atrapamiento', definicion: 'Atrapamiento por o entre objetos, máquinas, piezas en movimiento. Incluye aplastamiento. Código: 07.', normativa: 'Res. SRT 1604/07', ejemplo: 'Dedos atrapados en rodillos de máquina, mano atrapada en prensa' },
                    { termino: 'Sobreesfuerzos', definicion: 'Esfuerzos físicos excesivos y/o falsos movimientos. Causa lesiones músculo-esqueléticas agudas. Código: 08.', normativa: 'Res. SRT 1604/07', ejemplo: 'Lumbalgia aguda al levantar carga pesada, desgarro al girar bruscamente' },
                    { termino: 'Exposición a temperaturas extremas', definicion: 'Contacto con superficies calientes o frías, exposición a ambientes térmicos extremos. Código: 09.', normativa: 'Res. SRT 1604/07', ejemplo: 'Quemadura por contacto con tubo de escape caliente, congelación en cámara fría' },
                    { termino: 'Exposición a sustancias nocivas', definicion: 'Contacto, inhalación o ingestión de sustancias químicas peligrosas. Código: 10.', normativa: 'Res. SRT 1604/07', ejemplo: 'Salpicadura de ácido en piel, inhalación de cloro gaseoso en derrame' },
                    { termino: 'Contacto con electricidad', definicion: 'Contacto directo o indirecto con corriente eléctrica. Incluye arco eléctrico. Código: 11.', normativa: 'Res. SRT 1604/07', ejemplo: 'Electrocución al tocar cable pelado, arco eléctrico en tablero de 380V' },
                    { termino: 'Exposición a radiaciones', definicion: 'Exposición a radiaciones ionizantes o no ionizantes nocivas. Código: 12.', normativa: 'Res. SRT 1604/07', ejemplo: 'Quemadura por UV en soldadura sin máscara, sobreexposición a rayos X' },
                    { termino: 'Explosión o incendio', definicion: 'Lesiones por explosiones o incendios. Incluye quemaduras, asfixia. Código: 13.', normativa: 'Res. SRT 1604/07', ejemplo: 'Explosión de garrafa de gas, incendio de solventes en taller de pintura' },
                    { termino: 'Accidente de tránsito', definicion: 'Accidentes con vehículos en vía pública o dentro del establecimiento. Frecuente en accidentes in itinere. Código: 14.', normativa: 'Res. SRT 1604/07', ejemplo: 'Colisión de autoelevador en depósito, atropello de peatón en playa de maniobras' },
                    { termino: 'Agresión por personas', definicion: 'Violencia física ejercida por terceros o compañeros de trabajo. Código: 15.', normativa: 'Res. SRT 1604/07', ejemplo: 'Asalto a chofer de transporte de caudales, pelea entre compañeros' },
                    { termino: 'Ataque de animales', definicion: 'Mordeduras, picaduras, embestidas de animales. Código: 16.', normativa: 'Res. SRT 1604/07', ejemplo: 'Mordedura de perro a cartero, picadura de abeja a trabajador rural' }
                ]
            },
            lesiones: {
                titulo: 'Tipos de Lesiones',
                icono: 'fa-user-injured',
                color: 'green',
                items: [
                    { termino: 'Herida cortante', definicion: 'Lesión producida por objetos con filo: cuchillos, vidrios, chapas, herramientas. Bordes regulares.', normativa: 'CIE-10', ejemplo: 'Corte en mano por manipulación de chapa metálica sin guantes' },
                    { termino: 'Herida punzante', definicion: 'Lesión producida por objetos puntiagudos: clavos, agujas, punzones. Mayor profundidad que extensión.', normativa: 'CIE-10', ejemplo: 'Punción en pie por clavo que atraviesa tabla, pinchazo con aguja hipodérmica' },
                    { termino: 'Contusión', definicion: 'Lesión por golpe sin pérdida de continuidad de la piel. Incluye hematomas, equimosis.', normativa: 'CIE-10', ejemplo: 'Golpe en muslo contra esquina de mesa, hematoma en brazo por caída de objeto' },
                    { termino: 'Fractura', definicion: 'Rotura total o parcial de un hueso. Puede ser cerrada o expuesta. Clasificación según localización y tipo.', normativa: 'CIE-10', ejemplo: 'Fractura de radio por caída con apoyo de mano, fractura de costilla por golpe' },
                    { termino: 'Luxación', definicion: 'Pérdida permanente de la relación articular normal entre dos superficies óseas.', normativa: 'CIE-10', ejemplo: 'Luxación de hombro por tracción brusca, luxación de rótula por giro forzado' },
                    { termino: 'Esguince', definicion: 'Distensión o desgarro de ligamentos articulares sin pérdida de contacto entre superficies óseas.', normativa: 'CIE-10', ejemplo: 'Esguince de tobillo por mal paso en escalera, esguince de muñeca por caída' },
                    { termino: 'Amputación', definicion: 'Pérdida total o parcial de un miembro o segmento corporal. Lesión grave con secuela permanente.', normativa: 'CIE-10', ejemplo: 'Amputación de falange por prensa, pérdida de dedo en sierra circular' },
                    { termino: 'Quemadura', definicion: 'Lesión tisular por calor, frío, electricidad, radiación o sustancias químicas. Se clasifica por grado y extensión (SCQ).', normativa: 'CIE-10', ejemplo: 'Quemadura de 2° grado en antebrazo por vapor, quemadura química por ácido' },
                    { termino: 'Aplastamiento', definicion: 'Lesión por compresión del cuerpo o partes del mismo entre dos superficies. Puede causar síndrome compartimental.', normativa: 'CIE-10', ejemplo: 'Pie aplastado por rueda de autoelevador, mano atrapada entre placas metálicas' },
                    { termino: 'Cuerpo extraño', definicion: 'Objeto que penetra o queda alojado en el organismo: ojos, oídos, vías respiratorias, tejidos.', normativa: 'CIE-10', ejemplo: 'Partícula metálica en ojo por amolado, astilla de madera en dedo' },
                    { termino: 'Asfixia', definicion: 'Falta de oxígeno por obstrucción de vías aéreas, inmersión, compresión torácica o ambiente deficiente de oxígeno.', normativa: 'CIE-10', ejemplo: 'Asfixia por inhalación de humo en incendio, asfixia en espacio confinado' },
                    { termino: 'Intoxicación', definicion: 'Efectos nocivos por exposición a sustancias tóxicas: inhalación, ingestión, absorción cutánea.', normativa: 'CIE-10', ejemplo: 'Intoxicación por monóxido de carbono en garaje, intoxicación por plaguicida' },
                    { termino: 'Shock eléctrico', definicion: 'Lesión por paso de corriente eléctrica a través del cuerpo. Incluye fibrilación, quemaduras eléctricas.', normativa: 'CIE-10', ejemplo: 'Electrocución al tocar conductores de 220V sin desenergizar' },
                    { termino: 'Traumatismo Encéfalo Craneano (TEC)', definicion: 'Lesión cerebral por impacto directo o aceleración/desaceleración. Clasificación según escala de Glasgow.', normativa: 'CIE-10', ejemplo: 'TEC por caída de altura sin casco, golpe de cabeza contra estructura' },
                    { termino: 'Politraumatismo', definicion: 'Lesiones múltiples en distintas regiones corporales, donde al menos una pone en peligro la vida.', normativa: 'CIE-10', ejemplo: 'Múltiples fracturas y TEC por caída desde andamio de 8 metros' }
                ]
            },
            partes_cuerpo: {
                titulo: 'Partes del Cuerpo Afectadas',
                icono: 'fa-child',
                color: 'teal',
                items: [
                    { termino: 'Cabeza (excepto ojos)', definicion: 'Incluye cráneo, cara, cuero cabelludo, oídos. Frecuente en caídas y golpes con objetos. Código: 10.', normativa: 'Res. SRT', ejemplo: 'Golpe en frente contra viga, corte en mejilla por proyección de vidrio' },
                    { termino: 'Ojos', definicion: 'Lesiones oculares por proyección de partículas, salpicaduras químicas, radiaciones. Código: 11.', normativa: 'Res. SRT', ejemplo: 'Partícula metálica en córnea por amolado, salpicadura de solvente en ojo' },
                    { termino: 'Cuello', definicion: 'Incluye columna cervical, garganta, laringe. Lesiones por latigazo, compresión. Código: 12.', normativa: 'Res. SRT', ejemplo: 'Latigazo cervical por accidente de tránsito, contractura por postura forzada' },
                    { termino: 'Tronco', definicion: 'Incluye espalda, tórax, abdomen, pelvis. Código: 20.', normativa: 'Res. SRT', ejemplo: 'Contusión torácica por golpe, herida en abdomen por objeto punzante' },
                    { termino: 'Columna vertebral', definicion: 'Región cervical, dorsal, lumbar y sacra. Muy frecuente en sobreesfuerzos. Código: 21.', normativa: 'Res. SRT', ejemplo: 'Lumbalgia aguda al levantar carga, hernia discal por esfuerzo repetido' },
                    { termino: 'Miembro superior (excepto manos)', definicion: 'Hombro, brazo, codo, antebrazo, muñeca. Código: 30.', normativa: 'Res. SRT', ejemplo: 'Fractura de húmero por caída, tendinitis de hombro por movimiento repetitivo' },
                    { termino: 'Manos', definicion: 'Mano, dedos. La parte del cuerpo más frecuentemente lesionada en accidentes laborales. Código: 31.', normativa: 'Res. SRT', ejemplo: 'Corte en dedos por cuchilla, aplastamiento de mano en prensa' },
                    { termino: 'Miembro inferior (excepto pies)', definicion: 'Cadera, muslo, rodilla, pierna, tobillo. Código: 40.', normativa: 'Res. SRT', ejemplo: 'Fractura de tibia por caída de objeto, esguince de rodilla por giro' },
                    { termino: 'Pies', definicion: 'Pie, dedos del pie. Frecuente en caídas de objetos y pisadas. Código: 41.', normativa: 'Res. SRT', ejemplo: 'Aplastamiento de pie por caída de pallet, punción por clavo' },
                    { termino: 'Múltiples localizaciones', definicion: 'Lesiones en más de una región corporal. Común en accidentes graves. Código: 50.', normativa: 'Res. SRT', ejemplo: 'Fracturas en pierna y brazo más TEC por caída de altura' },
                    { termino: 'Lesiones generales', definicion: 'Afectación sistémica: intoxicaciones, asfixia, efectos de temperaturas extremas. Código: 60.', normativa: 'Res. SRT', ejemplo: 'Intoxicación generalizada por inhalación de gas, hipotermia por exposición' }
                ]
            },
            enfermedades: {
                titulo: 'Enfermedades Profesionales',
                icono: 'fa-notes-medical',
                color: 'purple',
                items: [
                    { termino: 'Hipoacusia Inducida por Ruido', definicion: 'Pérdida auditiva neurosensorial bilateral e irreversible por exposición a ruido laboral. Agente: Ruido >85 dB(A).', normativa: 'Dec. 658/96', ejemplo: 'Operador de prensa con 15 años de exposición a 92 dB sin protección auditiva' },
                    { termino: 'Silicosis', definicion: 'Neumoconiosis fibrogénica por inhalación de sílice cristalina. Actividades: minería, construcción, fundiciones.', normativa: 'Dec. 658/96', ejemplo: 'Minero de cantera de piedra con 20 años de exposición a polvo de cuarzo' },
                    { termino: 'Asbestosis', definicion: 'Fibrosis pulmonar por inhalación de fibras de asbesto. Período de latencia prolongado. Puede derivar en mesotelioma.', normativa: 'Dec. 658/96', ejemplo: 'Ex trabajador de fábrica de fibrocemento diagnosticado 30 años después' },
                    { termino: 'Dermatosis Profesional', definicion: 'Afecciones cutáneas por contacto con agentes irritantes o sensibilizantes: dermatitis de contacto, eccemas.', normativa: 'Dec. 658/96', ejemplo: 'Peluquera con dermatitis en manos por contacto con tinturas y químicos' },
                    { termino: 'Asma Ocupacional', definicion: 'Enfermedad respiratoria caracterizada por obstrucción bronquial reversible causada por agentes del trabajo.', normativa: 'Dec. 658/96', ejemplo: 'Panadero con asma por exposición a harina de trigo (asma del panadero)' },
                    { termino: 'Síndrome del Túnel Carpiano', definicion: 'Neuropatía compresiva del nervio mediano a nivel del carpo por movimientos repetitivos de muñeca y manos.', normativa: 'Dec. 49/14', ejemplo: 'Operaria de empaque con parestesias en dedos por 8 años de trabajo repetitivo' },
                    { termino: 'Lumbalgia Crónica', definicion: 'Dolor lumbar persistente por carga física, posturas forzadas o vibraciones de cuerpo entero.', normativa: 'Dec. 49/14', ejemplo: 'Camionero de larga distancia con dolor lumbar crónico por vibraciones' },
                    { termino: 'Hernia de Disco', definicion: 'Protrusión del núcleo pulposo por degeneración discal asociada a manipulación de cargas y posturas forzadas.', normativa: 'Dec. 49/14', ejemplo: 'Estibador con hernia L4-L5 por levantar cargas de 40 kg repetidamente' },
                    { termino: 'Saturnismo', definicion: 'Intoxicación crónica por plomo. Afecta sistema nervioso, renal, hematopoyético. Actividades: fundiciones, baterías.', normativa: 'Dec. 658/96', ejemplo: 'Fundidor de plomo con anemia, cólicos y ribete de Burton en encías' },
                    { termino: 'Hidrargirismo', definicion: 'Intoxicación por mercurio. Afecta sistema nervioso central (eretismo mercurial), riñón, encías.', normativa: 'Dec. 658/96', ejemplo: 'Trabajador de planta cloro-álcali con temblor intencional y gingivitis' },
                    { termino: 'Várices de Miembros Inferiores', definicion: 'Dilatación venosa por bipedestación prolongada (más de 6 horas por jornada).', normativa: 'Dec. 49/14', ejemplo: 'Docente con várices en piernas por estar de pie 8 horas diarias' },
                    { termino: 'Hepatitis B y C', definicion: 'Infección viral del hígado por exposición a sangre contaminada. Personal de salud, laboratorios.', normativa: 'Dec. 658/96', ejemplo: 'Enfermera infectada por pinchazo con aguja de paciente positivo' },
                    { termino: 'Tuberculosis Ocupacional', definicion: 'Enfermedad infecciosa pulmonar por Mycobacterium tuberculosis. Personal de salud, cárceles.', normativa: 'Dec. 658/96', ejemplo: 'Kinesiólogo respiratorio contagiado en sala de neumotisiología' },
                    { termino: 'Cáncer Ocupacional', definicion: 'Neoplasias asociadas a exposición laboral: mesotelioma (asbesto), leucemia (benceno), cáncer de pulmón.', normativa: 'Dec. 658/96, Res. 81/19', ejemplo: 'Mesotelioma pleural en ex trabajador de astillero expuesto a amianto' },
                    { termino: 'Tendinitis', definicion: 'Inflamación de tendones por movimientos repetitivos y sobrecarga. Localizaciones frecuentes: hombro, codo, muñeca.', normativa: 'Dec. 49/14', ejemplo: 'Pintador de automóviles con tendinitis del manguito rotador por trabajo sobre cabeza' }
                ]
            },
            normativa: {
                titulo: 'Normativa y Resoluciones SRT',
                icono: 'fa-gavel',
                color: 'indigo',
                items: [
                    { termino: 'Ley 19.587', definicion: 'Ley de Higiene y Seguridad en el Trabajo (1972). Establece las condiciones de higiene y seguridad que deben cumplir los establecimientos.', normativa: 'Nacional', ejemplo: 'Marco legal para iluminación, ventilación, ruido, instalaciones eléctricas en establecimientos' },
                    { termino: 'Decreto 351/79', definicion: 'Reglamentación de la Ley 19.587. Requisitos técnicos de higiene y seguridad: instalaciones, máquinas, riesgos, equipos de protección.', normativa: 'Nacional', ejemplo: 'Define niveles de iluminación por tarea, requisitos de escaleras, protección de máquinas' },
                    { termino: 'Ley 24.557', definicion: 'Ley de Riesgos del Trabajo (1995). Crea el sistema de ART, define contingencias cubiertas, prestaciones y obligaciones.', normativa: 'Nacional', ejemplo: 'Establece que todo empleador debe tener ART y todo accidente laboral debe ser cubierto' },
                    { termino: 'Decreto 658/96', definicion: 'Listado de Enfermedades Profesionales. Identifica 89 agentes de riesgo con sus enfermedades y actividades asociadas.', normativa: 'Nacional', ejemplo: 'Define que silicosis es EP para mineros, hipoacusia para expuestos a ruido >85dB' },
                    { termino: 'Decreto 911/96', definicion: 'Reglamento de Higiene y Seguridad para la Industria de la Construcción. Requisitos específicos para obras.', normativa: 'Nacional', ejemplo: 'Requisitos de andamios, excavaciones, EPP específico, legajo técnico de obra' },
                    { termino: 'Decreto 617/97', definicion: 'Reglamento de Higiene y Seguridad para la Actividad Agraria.', normativa: 'Nacional', ejemplo: 'Normas para uso de agroquímicos, maquinaria agrícola, trabajo en silos' },
                    { termino: 'Resolución 295/03', definicion: 'Especificaciones técnicas sobre ergonomía, levantamiento manual de cargas, estrés térmico, contaminantes químicos, ruido y vibraciones.', normativa: 'SRT', ejemplo: 'Tablas de peso máximo según frecuencia y postura, CMP de contaminantes, límites de ruido' },
                    { termino: 'Resolución 463/09', definicion: 'Relevamiento General de Riesgos Laborales (RGRL). Declaración jurada del estado de cumplimiento de la normativa.', normativa: 'SRT', ejemplo: 'Formulario donde empleador declara cumplimiento de Dec. 351/79 a la ART' },
                    { termino: 'Resolución 905/15', definicion: 'Protocolo para evacuación de edificios y planes de emergencia. Obligatorio para establecimientos con más de 50 trabajadores.', normativa: 'SRT', ejemplo: 'Obliga a realizar simulacros de evacuación y tener plan de emergencia documentado' },
                    { termino: 'Resolución 960/15', definicion: 'Protocolo de medición de iluminación en el ambiente laboral.', normativa: 'SRT', ejemplo: 'Establece metodología de medición de lux en puestos de trabajo y grilla de puntos' },
                    { termino: 'Resolución 81/19', definicion: 'Sistema de Vigilancia y Control de Sustancias y Agentes Cancerígenos (SVCC). Listado y procedimientos de registro.', normativa: 'SRT', ejemplo: 'Obliga a registrar trabajadores expuestos a asbesto, benceno, formaldehído, etc.' },
                    { termino: 'Decreto 49/14', definicion: 'Incorpora al listado de enfermedades profesionales: várices, hernias, síndrome del túnel carpiano, lumbalgias.', normativa: 'Nacional', ejemplo: 'Reconoce hernia inguinal por aumento de presión intraabdominal como EP' },
                    { termino: 'Resolución 283/02', definicion: 'Define accidentes graves a denunciar en 24 horas. Listado de lesiones de alta complejidad.', normativa: 'SRT', ejemplo: 'Obliga a denunciar amputaciones, TEC grave, quemaduras extensas dentro de 24hs' },
                    { termino: 'Resolución 37/10', definicion: 'Exámenes médicos en salud: preocupacionales, periódicos, previos a transferencia, posteriores a ausencias prolongadas, previos a egreso.', normativa: 'SRT', ejemplo: 'Define contenido y periodicidad de exámenes según exposición a riesgos' }
                ]
            },
            indices: {
                titulo: 'Índices y Estadísticas',
                icono: 'fa-chart-line',
                color: 'pink',
                items: [
                    { termino: 'Índice de Incidencia', definicion: 'Cantidad de casos notificados con baja laboral o secuela incapacitante cada 1.000 trabajadores cubiertos en un período determinado.', normativa: 'SRT', ejemplo: 'Índice de 45,2 significa 45,2 accidentes cada 1.000 trabajadores al año' },
                    { termino: 'Índice de Incidencia AT y EP', definicion: 'Índice que excluye accidentes in itinere y reingresos. Considera solo accidentes de trabajo y enfermedades profesionales.', normativa: 'SRT', ejemplo: 'Permite comparar accidentabilidad real en el trabajo sin distorsión por tránsito' },
                    { termino: 'Índice de Incidencia Global', definicion: 'Incluye todos los casos: accidentes de trabajo, enfermedades profesionales, accidentes in itinere y reingresos.', normativa: 'SRT', ejemplo: 'Visión completa de la siniestralidad total del sistema de riesgos del trabajo' },
                    { termino: 'Índice de Mortalidad', definicion: 'Cantidad de casos mortales cada millón de trabajadores cubiertos.', normativa: 'SRT', ejemplo: 'Índice de 35 significa 35 fallecidos cada millón de trabajadores por año' },
                    { termino: 'Índice de Letalidad', definicion: 'Cantidad de casos mortales cada cien mil casos notificados. Mide la gravedad promedio de los accidentes.', normativa: 'SRT', ejemplo: 'Construcción tiene mayor letalidad que comercio por la gravedad de sus accidentes' },
                    { termino: 'Días con Baja Laboral', definicion: 'Jornadas no trabajadas por el damnificado dentro del período de Incapacidad Laboral Temporaria (ILT).', normativa: 'SRT', ejemplo: 'Fractura de radio: promedio 45 días de baja; esguince leve: 5-7 días de baja' },
                    { termino: 'CIIU (Clasificador Industrial Internacional Uniforme)', definicion: 'Sistema de clasificación de actividades económicas usado para estadísticas de accidentabilidad por sector.', normativa: 'ONU/SRT', ejemplo: 'CIIU 4520: Construcción de edificios; CIIU 1010: Elaboración de productos cárnicos' },
                    { termino: 'Trabajador Cubierto', definicion: 'Persona trabajadora declarada por el empleador en la DDJJ mensual y con cobertura vigente de una ART.', normativa: 'SRT', ejemplo: 'Empleado en blanco con aportes al día aparece en nómina de trabajadores cubiertos' },
                    { termino: 'Caso Notificado', definicion: 'Accidente o enfermedad profesional que ha sido informado por la ART o empleador autoasegurado a la SRT.', normativa: 'SRT', ejemplo: 'Accidente denunciado mediante formulario de siniestro ingresado al sistema RENAL' },
                    { termino: 'PMI (Primera Manifestación Invalidante)', definicion: 'Fecha en que se manifestaron por primera vez los síntomas de la enfermedad profesional.', normativa: 'SRT', ejemplo: 'Fecha de la primera audiometría que detectó hipoacusia, aunque haga años de exposición' }
                ]
            }
        };
        
        function showGlossary() {
            window.scrollTo({ top: 0, behavior: 'smooth' });
            
            hideAllViews();
            const glossaryView = document.getElementById('glossaryView');
            glossaryView.classList.remove('hidden');
            glossaryView.style.animation = 'slideInRight 0.3s ease-out forwards';
            
            setActiveSidebarItem('glossary');
            renderGlossary();
            
            setTimeout(() => {
                glossaryView.style.animation = '';
            }, 350);
        }
        
        function renderGlossary() {
            const container = document.getElementById('glossaryContent');
            let html = '';
            let totalItems = 0;
            
            for (const [key, section] of Object.entries(glossaryData)) {
                const colorClasses = {
                    blue: { bg: 'bg-blue-50', border: 'border-blue-500', text: 'text-blue-800', icon: 'text-blue-600' },
                    red: { bg: 'bg-red-50', border: 'border-red-500', text: 'text-red-800', icon: 'text-red-600' },
                    orange: { bg: 'bg-orange-50', border: 'border-orange-500', text: 'text-orange-800', icon: 'text-orange-600' },
                    yellow: { bg: 'bg-yellow-50', border: 'border-yellow-500', text: 'text-yellow-800', icon: 'text-yellow-600' },
                    green: { bg: 'bg-green-50', border: 'border-green-500', text: 'text-green-800', icon: 'text-green-600' },
                    teal: { bg: 'bg-teal-50', border: 'border-teal-500', text: 'text-teal-800', icon: 'text-teal-600' },
                    purple: { bg: 'bg-purple-50', border: 'border-purple-500', text: 'text-purple-800', icon: 'text-purple-600' },
                    indigo: { bg: 'bg-indigo-50', border: 'border-indigo-500', text: 'text-indigo-800', icon: 'text-indigo-600' },
                    pink: { bg: 'bg-pink-50', border: 'border-pink-500', text: 'text-pink-800', icon: 'text-pink-600' }
                };
                
                const colors = colorClasses[section.color] || colorClasses.blue;
                
                html += `
                    <div id="glossary-section-${key}" class="bg-white rounded-lg shadow-md overflow-hidden glossary-section" data-category="${key}">
                        <div class="${colors.bg} px-6 py-4 border-l-4 ${colors.border}">
                            <h3 class="text-lg font-bold ${colors.text}">
                                <i class="fas ${section.icono} ${colors.icon} mr-2"></i>
                                ${section.titulo}
                                <span class="text-sm font-normal ml-2">(${section.items.length} términos)</span>
                            </h3>
                        </div>
                        <div class="divide-y divide-gray-100">
                `;
                
                section.items.forEach((item, idx) => {
                    totalItems++;
                    const ejemploHtml = item.ejemplo ? `
                        <span class="relative inline-flex items-center justify-center w-5 h-5 bg-blue-500 text-white rounded-full cursor-pointer ml-2 text-xs hover:bg-blue-600 transition" onclick="showGlossaryTooltip(event, '${item.ejemplo.replace(/'/g, "\\'")}')">
                            <i class="fas fa-info text-xs"></i>
                        </span>
                    ` : '';
                    
                    html += `
                        <div id="gl-${key}-${idx}" class="glossary-item p-4 hover:bg-gray-50 transition" data-category="${key}" data-search="${item.termino.toLowerCase()} ${item.definicion.toLowerCase()} ${(item.ejemplo || '').toLowerCase()}">
                            <div class="flex flex-col md:flex-row md:items-start gap-2">
                                <div class="md:w-1/4 flex items-center">
                                    <span class="gl-term font-bold text-gray-800">${item.termino}</span>
                                    ${ejemploHtml}
                                </div>
                                <div class="md:w-3/4">
                                    <p class="gl-def text-gray-600 text-sm">${item.definicion}</p>
                                    <span class="inline-block mt-2 text-xs px-2 py-1 bg-gray-100 text-gray-600 rounded">${item.normativa}</span>
                                </div>
                            </div>
                        </div>
                    `;
                });
                
                html += '</div></div>';
            }
            
            container.innerHTML = html;
            document.getElementById('glossaryResultsCount').textContent = totalItems;
        }
        
        function showGlossaryTooltip(event, texto) {
            event.stopPropagation();
            // Eliminar tooltip anterior si existe
            const existingTooltip = document.getElementById('glossaryTooltip');
            if (existingTooltip) {
                existingTooltip.remove();
            }
            
            // Crear tooltip
            const tooltip = document.createElement('div');
            tooltip.id = 'glossaryTooltip';
            tooltip.className = 'fixed z-50 bg-blue-600 text-white text-sm p-3 rounded-lg shadow-lg max-w-xs';
            tooltip.style.cssText = 'animation: fadeIn 0.2s ease-out;';
            tooltip.innerHTML = `<strong>Ejemplo:</strong> ${texto}`;
            
            // Posicionar cerca del clic
            const rect = event.target.getBoundingClientRect();
            tooltip.style.top = (rect.bottom + 8) + 'px';
            tooltip.style.left = Math.min(rect.left, window.innerWidth - 320) + 'px';
            
            document.body.appendChild(tooltip);
            
            // Cerrar al hacer clic en cualquier lugar
            setTimeout(() => {
                document.addEventListener('click', closeGlossaryTooltip, { once: true });
            }, 100);
        }
        
        function closeGlossaryTooltip() {
            const tooltip = document.getElementById('glossaryTooltip');
            if (tooltip) {
                tooltip.remove();
            }
        }
        
        function filterGlossary() {
            const searchTerm = normalizeText(document.getElementById('glossarySearch').value.toLowerCase().trim());
            const categoryFilter = document.getElementById('glossaryCategoryFilter').value;
            
            const items = document.querySelectorAll('.glossary-item');
            const sections = document.querySelectorAll('.glossary-section');
            let visibleCount = 0;
            
            // Ocultar todas las secciones primero
            sections.forEach(section => {
                section.style.display = 'none';
            });
            
            items.forEach(item => {
                const category = item.dataset.category;
                const searchData = normalizeText(item.dataset.search);
                
                const matchesCategory = !categoryFilter || category === categoryFilter;
                const matchesSearch = !searchTerm || searchData.includes(searchTerm);
                
                if (matchesCategory && matchesSearch) {
                    item.style.display = 'block';
                    // Mostrar la sección padre
                    document.getElementById('glossary-section-' + category).style.display = 'block';
                    visibleCount++;
                } else {
                    item.style.display = 'none';
                }
            });
            
            document.getElementById('glossaryResultsCount').textContent = visibleCount;
        }
        
        // Función para normalizar texto (quitar acentos)
        function normalizeText(text) {
            return text.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        }
        
        function scrollToGlossarySection(sectionId) {
            // Limpiar filtros
            document.getElementById('glossarySearch').value = '';
            document.getElementById('glossaryCategoryFilter').value = '';
            filterGlossary();
            
            // Scroll a la sección
            const section = document.getElementById('glossary-section-' + sectionId);
            if (section) {
                section.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
        }

        // ==========================================
        // MÓDULO PROTOCOLOS Y PROCEDIMIENTOS
        // ==========================================
        // Control de documentos del sistema de gestión: cada protocolo /
        // procedimiento / instructivo tiene un código único
        // (PREFIJO-TIPO-NNN), un número de revisión, un historial de
        // revisiones, un archivo adjunto opcional (Word / PDF / imagen) y
        // se puede imprimir como documento con membrete.
        const PROTO_TIPOS = {
            PRC: 'Procedimiento',
            PRT: 'Protocolo',
            INS: 'Instructivo',
            PLN: 'Plan / Programa',
            REG: 'Registro / Formulario'
        };
        const PROTO_ESTADOS = { vigente: 'Vigente', en_revision: 'En revisión', obsoleto: 'Obsoleto' };
        const PROTO_MAX_FILE_BYTES = 5 * 1024 * 1024;

        let editingProtocolId = null;
        let protoRevisionMode = false;   // true cuando se está cargando una nueva revisión de un documento existente
        let protoCodeManual = false;     // true si el usuario escribió el código a mano (no se autogenera más)

        function protoEsc(value) {
            return String(value === null || value === undefined ? '' : value)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
                .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
        }

        function protoFmtDate(iso) {
            if (!iso) return '-';
            const d = new Date(iso + (String(iso).length <= 10 ? 'T00:00:00' : ''));
            return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('es-AR');
        }

        // Prefijo de códigos: el configurado para este establecimiento; si es
        // una obra sin prefijo propio, el de su empresa; si no hay ninguno,
        // iniciales del nombre (ej. "Constructora Andes SA" -> "CA").
        function getProtocolPrefix() {
            if (!currentEstablishment) return 'DOC';
            const own = (currentEstablishment.prefijo_protocolos || '').trim();
            if (own) return own.toUpperCase();
            const madre = esObra(currentEstablishment) ? getEmpresaMadre(currentEstablishment) : null;
            if (madre && (madre.prefijo_protocolos || '').trim()) return madre.prefijo_protocolos.trim().toUpperCase();
            const base = (madre || currentEstablishment).nombre || '';
            const stop = ['de', 'del', 'la', 'las', 'los', 'y', 'e', 'sa', 'srl', 's.a.', 's.r.l.', 'sas', 'sh', 'ltda'];
            const words = base.split(/\s+/).map(w => w.trim()).filter(w => w && stop.indexOf(w.toLowerCase()) === -1);
            let prefix = '';
            if (words.length >= 2) prefix = words.slice(0, 4).map(w => w[0]).join('');
            else if (words.length === 1) prefix = words[0].substring(0, 4);
            prefix = prefix.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]/g, '').toUpperCase();
            return prefix || 'DOC';
        }

        function saveProtocolPrefix(value) {
            if (!currentEstablishment) return;
            const clean = String(value || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9]/g, '').toUpperCase().substring(0, 8);
            const est = appData.establishments.find(e => e.id === currentEstablishment.id);
            if (est) est.prefijo_protocolos = clean;
            currentEstablishment.prefijo_protocolos = clean;
            saveData();
            document.getElementById('protoPrefix').value = getProtocolPrefix();
            // Si el formulario está abierto con un código automático, refrescarlo
            if (!document.getElementById('protoForm').classList.contains('hidden') && !protoCodeManual && !editingProtocolId) {
                onProtocolTypeChange();
            }
        }

        function nextProtocolCode(tipo) {
            const prefix = getProtocolPrefix();
            const re = new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '-' + tipo + '-(\\d+)$');
            let max = 0;
            (appData.protocols || []).forEach(p => {
                if (p.establecimiento_id !== currentEstablishment.id) return;
                const m = re.exec(p.codigo || '');
                if (m) max = Math.max(max, parseInt(m[1], 10));
            });
            return prefix + '-' + tipo + '-' + String(max + 1).padStart(3, '0');
        }

        function onProtocolTypeChange() {
            if (protoCodeManual || editingProtocolId) return;
            const form = document.getElementById('protoFormElement');
            form.querySelector('[name="codigo"]').value = nextProtocolCode(form.querySelector('[name="tipo"]').value);
        }

        function getEstablishmentProtocols() {
            if (!currentEstablishment) return [];
            return (appData.protocols || []).filter(p => p.establecimiento_id === currentEstablishment.id);
        }

        function protoRevisionVencida(p) {
            if (!p.proxima_revision || p.estado === 'obsoleto') return false;
            const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
            return new Date(p.proxima_revision + 'T00:00:00') < hoy;
        }

        function loadProtocols() {
            if (!currentEstablishment) return;
            document.getElementById('protoPrefix').value = getProtocolPrefix();
            const all = getEstablishmentProtocols();
            document.getElementById('protoTotal').textContent = all.length;
            document.getElementById('protoVigentes').textContent = all.filter(p => p.estado === 'vigente').length;
            document.getElementById('protoRevVencida').textContent = all.filter(protoRevisionVencida).length;
            document.getElementById('protoConArchivo').textContent = all.filter(p => p.archivo).length;
            loadCommunications();

            const q = (document.getElementById('protoSearch').value || '').trim().toLowerCase();
            const tipo = document.getElementById('protoFilterTipo').value;
            const list = all
                .filter(p => !tipo || p.tipo === tipo)
                .filter(p => !q || (p.codigo || '').toLowerCase().indexOf(q) !== -1 || (p.titulo || '').toLowerCase().indexOf(q) !== -1)
                .sort((a, b) => (a.codigo || '').localeCompare(b.codigo || ''));

            const el = document.getElementById('protoList');
            if (all.length === 0) {
                el.innerHTML = '<p class="text-gray-500 text-center py-4">No hay protocolos ni procedimientos registrados</p>';
                return;
            }
            if (list.length === 0) {
                el.innerHTML = '<p class="text-gray-500 text-center py-4">Ningún documento coincide con el filtro</p>';
                return;
            }
            const estadoColor = { vigente: 'green', en_revision: 'yellow', obsoleto: 'gray' };
            el.innerHTML = list.map(function (p) {
                const color = estadoColor[p.estado] || 'gray';
                const vencida = protoRevisionVencida(p);
                return '<div class="border rounded-lg p-3 border-l-4 border-' + color + '-500 hover:shadow-md transition">' +
                    '<div class="flex justify-between items-start flex-wrap gap-2">' +
                        '<div class="flex-1" style="min-width:200px">' +
                            '<div class="flex items-center gap-2 mb-1 flex-wrap">' +
                                '<span class="font-mono font-bold text-blue-800 text-sm">' + protoEsc(p.codigo) + '</span>' +
                                '<span class="px-2 py-0.5 rounded text-xs font-semibold bg-blue-100 text-blue-800">' + protoEsc(PROTO_TIPOS[p.tipo] || p.tipo) + '</span>' +
                                '<span class="px-2 py-0.5 rounded text-xs font-semibold bg-gray-100 text-gray-700">Rev. ' + protoEsc(String(p.revision).padStart(2, '0')) + '</span>' +
                                '<span class="px-2 py-0.5 rounded-full text-xs font-semibold bg-' + color + '-100 text-' + color + '-800">' + protoEsc(PROTO_ESTADOS[p.estado] || p.estado) + '</span>' +
                                (vencida ? '<span class="px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-800"><i class="fas fa-clock"></i> Revisión vencida</span>' : '') +
                            '</div>' +
                            '<h4 class="font-semibold text-gray-800 text-sm">' + protoEsc(p.titulo) + '</h4>' +
                            '<div class="mt-1">' + protoCoverageBadge(p) + '</div>' +
                            '<p class="text-xs text-gray-600 mt-1">' +
                                (p.area ? protoEsc(p.area) + ' · ' : '') + 'Emisión: ' + protoFmtDate(p.fecha_emision) +
                                (p.proxima_revision ? ' · Próx. revisión: ' + protoFmtDate(p.proxima_revision) : '') +
                            '</p>' +
                            (p.archivo ? '<p class="text-xs text-green-700 mt-1"><i class="fas fa-paperclip"></i> ' + protoEsc(p.archivoNombre) + '</p>' : '') +
                            (p.aplica_puestos ? '<p class="text-xs text-gray-600 mt-1"><i class="fas fa-user-tag"></i> Aplica a: ' + protoEsc(p.aplica_puestos) + '</p>' : '') +
                        '</div>' +
                        '<div class="flex gap-3 items-center text-lg">' +
                            (p.archivo ? '<button title="Ver archivo" onclick="viewProtocolFile(\'' + p.id + '\')" class="text-indigo-600 hover:text-indigo-800"><i class="fas fa-eye"></i></button><button title="Descargar archivo" onclick="downloadProtocolFile(\'' + p.id + '\')" class="text-green-600 hover:text-green-800"><i class="fas fa-download"></i></button>' : '') +
                            '<button title="Imprimir / PDF con membrete" onclick="printProtocolPDF(\'' + p.id + '\')" class="text-blue-700 hover:text-blue-900"><i class="fas fa-print"></i></button>' +
                            '<button title="Registrar comunicación (a quién se le dio a conocer)" onclick="openCommunicationForm({protocolIds:[\'' + p.id + '\']})" class="text-green-600 hover:text-green-800"><i class="fas fa-bullhorn"></i></button>' +
                            '<button title="Historial de revisiones y a quién se explicó cada una" onclick="openProtocolHistory(\'' + p.id + '\')" class="text-indigo-600 hover:text-indigo-800"><i class="fas fa-history"></i></button>' +
                            '<button title="Nueva revisión" onclick="newProtocolRevision(\'' + p.id + '\')" class="text-purple-600 hover:text-purple-800"><i class="fas fa-code-branch"></i></button>' +
                            '<button title="Editar" onclick="editProtocol(\'' + p.id + '\')" class="text-blue-600 hover:text-blue-800"><i class="fas fa-edit"></i></button>' +
                            signedAttachBtn('protocol', p.id) + '<button title="Eliminar" onclick="deleteProtocol(\'' + p.id + '\')" class="text-red-600 hover:text-red-800"><i class="fas fa-trash"></i></button>' +
                        '</div>' +
                    '</div>' +
                '</div>';
            }).join('');
        }

        function ensureProtoMotivoField() {
            // El campo "Motivo del cambio" sólo aparece al cargar una nueva revisión.
            let wrap = document.getElementById('protoMotivoWrap');
            if (!wrap) {
                const form = document.getElementById('protoFormElement');
                wrap = document.createElement('div');
                wrap.id = 'protoMotivoWrap';
                wrap.className = 'hidden';
                wrap.innerHTML = '<label class="block text-sm font-semibold mb-1">Motivo del cambio de revisión *</label>' +
                    '<input type="text" name="motivo_cambio" placeholder="Ej: Se actualiza por cambio de normativa" class="border border-gray-300 rounded-lg p-2 w-full">';
                const fileBlock = document.getElementById('protoFileInput').parentElement;
                form.insertBefore(wrap, fileBlock);
            }
            return wrap;
        }

        function showNewProtocol() {
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            editingProtocolId = null;
            protoRevisionMode = false;
            protoCodeManual = false;
            const form = document.getElementById('protoFormElement');
            form.reset();
            ensureProtoMotivoField().classList.add('hidden');
            document.getElementById('protoFormTitle').innerHTML = '<i class="fas fa-plus-circle text-blue-700"></i> Nuevo documento';
            form.querySelector('[name="fecha_emision"]').valueAsDate = new Date();
            form.querySelector('[name="revision"]').value = 0;
            form.querySelector('[name="codigo"]').value = nextProtocolCode(form.querySelector('[name="tipo"]').value);
            document.getElementById('protoFilePreview').textContent = '';
            protoFillAplicaList();
            document.getElementById('protoForm').classList.remove('hidden');
            document.getElementById('protoForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function cancelNewProtocol() {
            document.getElementById('protoForm').classList.add('hidden');
            editingProtocolId = null;
            protoRevisionMode = false;
        }

        function fillProtocolForm(p) {
            const f = document.getElementById('protoFormElement');
            ['tipo', 'codigo', 'revision', 'estado', 'titulo', 'area', 'fecha_emision', 'proxima_revision', 'normativa', 'aplica_puestos',
             'elaboro', 'reviso', 'aprobo', 'objetivo', 'alcance', 'responsabilidades', 'desarrollo', 'registros'].forEach(function (name) {
                const input = f.querySelector('[name="' + name + '"]');
                if (input) input.value = (p[name] === undefined || p[name] === null) ? '' : p[name];
            });
            protoFillAplicaList();
            document.getElementById('protoFileInput').value = '';
            document.getElementById('protoFilePreview').textContent = p.archivo ? 'Archivo actual: ' + p.archivoNombre + ' (se conserva si no subís otro)' : '';
        }

        function editProtocol(id) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p) return;
            editingProtocolId = id;
            protoRevisionMode = false;
            protoCodeManual = true;
            fillProtocolForm(p);
            ensureProtoMotivoField().classList.add('hidden');
            document.getElementById('protoFormTitle').innerHTML = '<i class="fas fa-edit text-blue-700"></i> Editar documento';
            document.getElementById('protoForm').classList.remove('hidden');
            document.getElementById('protoForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function newProtocolRevision(id) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p) return;
            editingProtocolId = id;
            protoRevisionMode = true;
            protoCodeManual = true;
            fillProtocolForm(p);
            const f = document.getElementById('protoFormElement');
            f.querySelector('[name="revision"]').value = (parseInt(p.revision, 10) || 0) + 1;
            f.querySelector('[name="estado"]').value = 'vigente';
            f.querySelector('[name="fecha_emision"]').valueAsDate = new Date();
            const wrap = ensureProtoMotivoField();
            wrap.classList.remove('hidden');
            wrap.querySelector('input').value = '';
            if (p.archivo) document.getElementById('protoFilePreview').textContent = 'Archivo de la revisión anterior: ' + p.archivoNombre + ' (subí el nuevo; el anterior queda guardado en el historial)';
            document.getElementById('protoFormTitle').innerHTML = '<i class="fas fa-code-branch text-purple-600"></i> Nueva revisión de ' + protoEsc(p.codigo);
            document.getElementById('protoForm').classList.remove('hidden');
            document.getElementById('protoForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function saveProtocol(event) {
            event.preventDefault();
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            const fd = new FormData(event.target);
            const codigo = String(fd.get('codigo') || '').trim().toUpperCase();
            if (!codigo) { alert('El código es obligatorio'); return; }
            const dup = (appData.protocols || []).some(p => p.establecimiento_id === currentEstablishment.id && p.codigo === codigo && p.id !== editingProtocolId);
            if (dup) { alert('Ya existe otro documento con el código ' + codigo + '. Elegí un código distinto.'); return; }
            const motivo = String(fd.get('motivo_cambio') || '').trim();
            if (protoRevisionMode && !motivo) { alert('Indicá el motivo del cambio de revisión'); return; }

            const data = {
                establecimiento_id: currentEstablishment.id,
                tipo: fd.get('tipo'),
                codigo: codigo,
                revision: parseInt(fd.get('revision'), 10) || 0,
                estado: fd.get('estado'),
                titulo: String(fd.get('titulo') || '').trim(),
                area: String(fd.get('area') || '').trim(),
                fecha_emision: fd.get('fecha_emision'),
                proxima_revision: fd.get('proxima_revision') || '',
                normativa: String(fd.get('normativa') || '').trim(),
                aplica_puestos: String(fd.get('aplica_puestos') || '').trim(),
                elaboro: String(fd.get('elaboro') || '').trim(),
                reviso: String(fd.get('reviso') || '').trim(),
                aprobo: String(fd.get('aprobo') || '').trim(),
                objetivo: fd.get('objetivo') || '',
                alcance: fd.get('alcance') || '',
                responsabilidades: fd.get('responsabilidades') || '',
                desarrollo: fd.get('desarrollo') || '',
                registros: fd.get('registros') || ''
            };

            const existing = editingProtocolId ? appData.protocols.find(x => x.id === editingProtocolId) : null;
            const fileInput = document.getElementById('protoFileInput');
            const file = fileInput.files && fileInput.files[0];

            function finish() {
                if (existing) {
                    const historial = (existing.historial || []).slice();
                    if (protoRevisionMode) {
                        // el archivo de la revisión que se reemplaza queda guardado en el historial: es el que se explicó en su momento
                        if (data.archivo && existing.archivo && data.archivo !== existing.archivo) {
                            let prev = historial.find(h => String(h.revision) === String(existing.revision));
                            if (!prev) { prev = { revision: existing.revision, fecha: existing.fecha_emision, motivo: 'Emisión inicial' }; historial.push(prev); }
                            prev.archivo = existing.archivo;
                            prev.archivoTipo = existing.archivoTipo;
                            prev.archivoNombre = existing.archivoNombre;
                        }
                        historial.push({ revision: data.revision, fecha: data.fecha_emision, motivo: motivo, archivoNombre: data.archivoNombre || '' });
                    }
                    Object.assign(existing, data, { historial: historial, updated_at: new Date().toISOString() });
                } else {
                    data.id = 'PR' + Date.now();
                    data.created_at = new Date().toISOString();
                    data.historial = [{ revision: data.revision, fecha: data.fecha_emision, motivo: 'Emisión inicial', archivoNombre: data.archivoNombre || '' }];
                    if (!appData.protocols) appData.protocols = [];
                    appData.protocols.push(data);
                }
                const wasRevision = protoRevisionMode;
                saveData();
                cancelNewProtocol();
                loadProtocols();
                alert(wasRevision ? 'Nueva revisión registrada' : (existing ? 'Documento actualizado' : 'Documento registrado'));
            }

            if (file) {
                if (file.size > PROTO_MAX_FILE_BYTES) { alert('El archivo es demasiado grande. Máximo 5 MB.'); return; }
                const reader = new FileReader();
                reader.onload = function (e) {
                    data.archivo = e.target.result;
                    data.archivoNombre = file.name;
                    data.archivoTipo = file.type;
                    finish();
                };
                reader.onerror = function () { alert('No se pudo leer el archivo seleccionado'); };
                reader.readAsDataURL(file);
            } else {
                if (existing && existing.archivo) {
                    data.archivo = existing.archivo;
                    data.archivoNombre = existing.archivoNombre;
                    data.archivoTipo = existing.archivoTipo;
                }
                finish();
            }
        }

        async function deleteProtocol(id) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p) return;
            if (!await appConfirm('¿Eliminar ' + p.codigo + ' — ' + p.titulo + '?\n\nSe borra también el archivo adjunto y su historial de revisiones.')) return;
            appData.protocols = appData.protocols.filter(x => x.id !== id);
            saveData();
            loadProtocols();
        }

        function viewProtocolFile(id) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p || !p.archivo) return;
            viewStoredFile(p.archivo, p.archivoNombre || (p.codigo + '.pdf'), p.archivoTipo);
        }

        function downloadProtocolFile(id) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p || !p.archivo) return;
            downloadStoredFile(p.archivo, p.archivoNombre || (p.codigo + '.pdf'));
        }

        // Descarga / comparte un archivo guardado como data URI (cualquier
        // tipo: Word, PDF, imagen). Reutilizable por otros módulos.
        async function downloadStoredFile(dataUri, filename) {
            try {
                const isNative = window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform();
                const plugins = (isNative && window.Capacitor.Plugins) || {};
                const { Filesystem, Share } = plugins;
                if (isNative && Filesystem && Share) {
                    const base64 = dataUri.substring(dataUri.indexOf(',') + 1);
                    await Filesystem.writeFile({ path: filename, data: base64, directory: 'CACHE' });
                    const info = await Filesystem.getUri({ directory: 'CACHE', path: filename });
                    await Share.share({ title: filename, url: info.uri, dialogTitle: 'Guardar o compartir archivo' });
                    return;
                }
                const mime = (dataUri.substring(5, dataUri.indexOf(';')) || 'application/octet-stream');
                const bin = atob(dataUri.substring(dataUri.indexOf(',') + 1));
                const bytes = new Uint8Array(bin.length);
                for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
                const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
                const link = document.createElement('a');
                link.href = url;
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                setTimeout(() => URL.revokeObjectURL(url), 1000);
            } catch (e) {
                console.error('Error al descargar el archivo:', e);
                alert('No se pudo descargar el archivo: ' + (e && e.message ? e.message : e));
            }
        }

        // ---------- PDF: documento con membrete ----------
        function drawProtocolMembrete(doc, p, pageNum, totalPages) {
            const L = 15, W = 180, top = 10, H = 28;
            const est = currentEstablishment;
            const empresa = (esObra(est) && getEmpresaMadre(est)) ? getEmpresaMadre(est) : est;
            doc.setDrawColor(15, 115, 197);
            doc.setLineWidth(0.4);
            doc.setTextColor(0, 0, 0);
            doc.rect(L, top, W, H);
            doc.line(L + 50, top, L + 50, top + H);
            doc.line(L + 130, top, L + 130, top + H);
            // Izquierda: empresa / obra
            doc.setFont('helvetica', 'bold'); doc.setFontSize(9);
            const nom = doc.splitTextToSize(String(empresa.nombre || ''), 44);
            doc.text(nom.slice(0, 3), L + 3, top + 6);
            doc.setFont('helvetica', 'normal'); doc.setFontSize(7);
            let ly = top + 6 + Math.min(nom.length, 3) * 4 + 1;
            if (empresa.cuit) { doc.text('CUIT: ' + empresa.cuit, L + 3, ly); ly += 3.5; }
            if (esObra(est)) doc.text(doc.splitTextToSize('Obra: ' + (est.nombre || ''), 44).slice(0, 2), L + 3, ly);
            // Centro: título
            doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
            doc.setTextColor(15, 115, 197);
            doc.text((PROTO_TIPOS[p.tipo] || 'Documento').toUpperCase(), L + 90, top + 7, { align: 'center' });
            doc.setTextColor(0, 0, 0); doc.setFontSize(12);
            const tit = doc.splitTextToSize(String(p.titulo || ''), 74);
            doc.text(tit.slice(0, 3), L + 90, top + 14, { align: 'center' });
            // Derecha: código / rev / fecha / página
            const rows = [
                ['Código', p.codigo || ''],
                ['Revisión', String(p.revision).padStart(2, '0')],
                ['Fecha', protoFmtDate(p.fecha_emision)],
                ['Página', pageNum + ' de ' + totalPages]
            ];
            rows.forEach(function (r, i) {
                const ry = top + i * 7;
                if (i > 0) doc.line(L + 130, ry, L + W, ry);
                doc.setFont('helvetica', 'bold'); doc.setFontSize(7);
                doc.text(r[0], L + 132, ry + 4.7);
                doc.setFont('helvetica', 'normal'); doc.setFontSize(8);
                doc.text(r[1], L + 146, ry + 4.8);
            });
            // Pie
            const ph = doc.internal.pageSize.getHeight();
            doc.setDrawColor(200, 200, 200); doc.setLineWidth(0.3);
            doc.line(L, ph - 14, L + W, ph - 14);
            doc.setFont('helvetica', 'normal'); doc.setFontSize(7); doc.setTextColor(120, 120, 120);
            doc.text((p.codigo || '') + ' - Rev. ' + String(p.revision).padStart(2, '0') + ' - ' + (PROTO_TIPOS[p.tipo] || ''), L, ph - 9);
            doc.text('Copia impresa: verificar la revisión vigente antes de usar.', L, ph - 5.5);
            doc.text('PROHS Consulting', L + W, ph - 9, { align: 'right' });
            doc.setTextColor(0, 0, 0);
        }

        function printProtocolPDF(id, mode) {
            const p = (appData.protocols || []).find(x => x.id === id);
            if (!p || !currentEstablishment) return;
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const L = 15, W = 180, START = 44, LIMIT = 272;
            let y = START;

            function ensure(h) { if (y + h > LIMIT) { doc.addPage(); y = START; } }
            function heading(text) {
                ensure(16);
                doc.setFillColor(232, 241, 251);
                doc.rect(L, y - 4.5, W, 6.5, 'F');
                doc.setFont('helvetica', 'bold'); doc.setFontSize(10); doc.setTextColor(15, 115, 197);
                doc.text(text, L + 2, y);
                doc.setTextColor(0, 0, 0);
                y += 7;
            }
            function section(title, text, blankLines) {
                heading(title);
                doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
                const t = String(text || '').trim();
                if (t) {
                    doc.splitTextToSize(t, W - 2).forEach(function (line) { ensure(5); doc.text(line, L + 1, y); y += 4.6; });
                } else {
                    // Sin contenido cargado: renglones en blanco para completar a mano
                    doc.setDrawColor(190, 190, 190); doc.setLineWidth(0.2);
                    for (let i = 0; i < blankLines; i++) { ensure(7); doc.line(L + 1, y + 1.5, L + W - 1, y + 1.5); y += 7; }
                }
                y += 4;
            }

            section('1. OBJETIVO', p.objetivo, 2);
            section('2. ALCANCE', p.alcance, 2);
            section('3. RESPONSABILIDADES', p.responsabilidades, 3);
            section('4. DESARROLLO', p.desarrollo, 14);
            section('5. REGISTROS ASOCIADOS', p.registros, 2);
            if (p.normativa) section('6. NORMATIVA DE REFERENCIA', p.normativa, 0);

            // Historial de revisiones
            if ((p.historial || []).length > 0) {
                ensure(30);
                heading('HISTORIAL DE REVISIONES');
                doc.autoTable({
                    startY: y,
                    head: [['Rev.', 'Fecha', 'Motivo del cambio']],
                    body: p.historial.map(h => [String(h.revision).padStart(2, '0'), protoFmtDate(h.fecha), h.motivo || '']),
                    theme: 'grid',
                    headStyles: { fillColor: [15, 115, 197], fontSize: 8 },
                    bodyStyles: { fontSize: 8 },
                    columnStyles: { 0: { cellWidth: 15, halign: 'center' }, 1: { cellWidth: 28 } },
                    margin: { left: L, right: 15, top: START, bottom: 20 }
                });
                y = doc.lastAutoTable.finalY + 8;
            }

            // Bloque de firmas
            ensure(36);
            const colW = W / 3;
            const labels = [['Elaboró', p.elaboro], ['Revisó', p.reviso], ['Aprobó', p.aprobo]];
            doc.setDrawColor(120, 120, 120); doc.setLineWidth(0.3);
            doc.rect(L, y, W, 30);
            labels.forEach(function (lb, i) {
                const x = L + i * colW;
                if (i > 0) doc.line(x, y, x, y + 30);
                doc.setFont('helvetica', 'bold'); doc.setFontSize(8);
                doc.text(lb[0], x + 3, y + 5);
                doc.setFont('helvetica', 'normal');
                doc.text(doc.splitTextToSize(String(lb[1] || ''), colW - 6).slice(0, 2), x + 3, y + 10);
                doc.setFontSize(7); doc.setTextColor(120, 120, 120);
                doc.text('Firma y aclaración', x + 3, y + 26);
                doc.setTextColor(0, 0, 0);
            });

            const total = doc.internal.getNumberOfPages();
            for (let i = 1; i <= total; i++) { doc.setPage(i); drawProtocolMembrete(doc, p, i, total); }
            exportPdf(doc, (p.codigo || 'Documento') + '_Rev' + String(p.revision).padStart(2, '0') + '.pdf', mode);
        }

        function exportProtocolsMasterList(mode) {
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            const list = getEstablishmentProtocols().sort((a, b) => (a.codigo || '').localeCompare(b.codigo || ''));
            if (list.length === 0) { alert('No hay documentos para exportar'); return; }
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF();
            const title = 'Listado Maestro de Documentos';
            let y = addPdfHeader(doc, title);
            doc.setFontSize(9); doc.setFont('helvetica', 'normal');
            doc.text('Protocolos, procedimientos e instructivos de "' + currentEstablishment.nombre + '" con su revisión vigente.', 15, y);
            y += 6;
            doc.autoTable({
                startY: y,
                head: [['Código', 'Título', 'Tipo', 'Rev.', 'Emisión', 'Próx. rev.', 'Estado', 'Archivo']],
                body: list.map(p => [
                    p.codigo, p.titulo, PROTO_TIPOS[p.tipo] || p.tipo, String(p.revision).padStart(2, '0'),
                    protoFmtDate(p.fecha_emision), protoFmtDate(p.proxima_revision),
                    (PROTO_ESTADOS[p.estado] || p.estado) + (protoRevisionVencida(p) ? ' (rev. vencida)' : ''),
                    p.archivo ? 'Sí' : 'No'
                ]),
                theme: 'grid',
                headStyles: { fillColor: [15, 115, 197], fontSize: 8, fontStyle: 'bold' },
                bodyStyles: { fontSize: 8 },
                columnStyles: { 0: { cellWidth: 26, fontStyle: 'bold' }, 3: { cellWidth: 10, halign: 'center' }, 7: { cellWidth: 14, halign: 'center' } },
                didDrawPage: function (data) { if (data.pageNumber > 1) addPdfHeader(doc, title); },
                margin: { left: 15, right: 15, top: 30 }
            });
            const total = doc.internal.getNumberOfPages();
            for (let i = 1; i <= total; i++) { doc.setPage(i); addPdfFooter(doc, i, total); }
            exportPdf(doc, 'Listado_Maestro_' + (currentEstablishment.nombre || 'Sin_nombre').replace(/\s+/g, '_') + '.pdf', mode);
        }

        // ==========================================
        // MÓDULO NÓMINA DE PERSONAL
        // ==========================================
        // Registro de trabajadores (propios o de un contratista) con su
        // cobertura de ART, documentación adjunta y foto. La aptitud médica,
        // las capacitaciones y los EPP entregados NO se vuelven a cargar:
        // se toman de sus módulos buscando al trabajador por legajo, DNI o
        // nombre.
        const PNL_DOC_CATEGORIAS = ['DNI', 'Alta temprana AFIP', 'Constancia de ART', 'Certificado / Curso', 'Apto médico', 'Otro'];
        const PNL_ESTADOS = { activo: 'Activo', licencia: 'En licencia', baja: 'Baja' };

        let editingWorkerId = null;
        let workerPhotoData = null;      // foto pendiente de guardar (data URL ya reducida)
        let openWorkerDetailId = null;

        function pnlNorm(s) {
            return String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
        }
        function pnlTokensKey(s) { return pnlNorm(s).split(' ').filter(Boolean).sort().join(' '); }
        function pnlDigits(s) { return String(s || '').replace(/\D/g, ''); }

        // ¿Este texto libre (nombre en un EPP, línea de participantes, etc.) corresponde al trabajador?
        function pnlMatchesWorker(text, w) {
            const wn = pnlTokensKey(w.nombre);
            if (!wn) return false;
            if (pnlTokensKey(text) === wn) return true;
            const dni = pnlDigits(w.dni);
            if (dni.length >= 7 && pnlDigits(text).indexOf(dni) !== -1) return true;
            const n = pnlNorm(text), plain = pnlNorm(w.nombre);
            return plain.length > 5 && n.indexOf(plain) !== -1;
        }

        function getEstablishmentWorkers() {
            if (!currentEstablishment) return [];
            return (appData.personnel || []).filter(w => workerVisibleInEst(w, currentEstablishment));
        }

        function pnlDaysTo(iso) {
            if (!iso) return null;
            const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
            const d = new Date(iso + 'T00:00:00');
            if (isNaN(d.getTime())) return null;
            return Math.round((d - hoy) / 86400000);
        }

        function workerArtEstado(w) {
            if (w.estado === 'baja') return { key: 'na', label: 'Baja', color: 'gray' };
            const dias = pnlDaysTo(w.art_hasta);
            if (dias === null) return { key: 'problema', label: w.art ? 'ART sin vigencia' : 'Sin ART', color: 'red' };
            if (dias < 0) return { key: 'problema', label: 'ART vencida', color: 'red' };
            if (dias <= 30) return { key: 'por_vencer', label: 'ART vence en ' + dias + ' d', color: 'yellow' };
            return { key: 'vigente', label: 'ART vigente', color: 'green' };
        }

        function findWorkerMedicals(w) {
            const leg = String(w.legajo || '').trim().toLowerCase();
            const fam = getFamilyEstIds(w.establecimiento_id);
            return (appData.medicals || [])
                .filter(m => idEnLista(fam, m.establecimiento_id))
                .filter(m => (m.trabajador_id && m.trabajador_id === w.id) || (!m.trabajador_id && ((leg && String(m.legajo || '').trim().toLowerCase() === leg) || pnlMatchesWorker(m.nombre_completo, w))))
                .sort((a, b) => String(b.fecha_examen || '').localeCompare(String(a.fecha_examen || '')));
        }

        function workerMedEstado(w) {
            if (w.estado === 'baja') return { key: 'na', label: '-', color: 'gray' };
            const recs = findWorkerMedicals(w);
            if (recs.length === 0) return { key: 'sin', label: 'Sin examen médico', color: 'red', rec: null };
            const m = recs[0];
            if (m.resultado === 'No apto') return { key: 'no_apto', label: 'No apto', color: 'red', rec: m };
            const dias = pnlDaysTo(m.proximo_control);
            if (dias !== null && dias < 0) return { key: 'vencido', label: 'Examen vencido', color: 'red', rec: m };
            if (dias !== null && dias <= 30) return { key: 'por_vencer', label: 'Examen vence en ' + dias + ' d', color: 'yellow', rec: m };
            return { key: 'vigente', label: m.resultado || 'Apto', color: 'green', rec: m };
        }

        function findWorkerTrainings(w) {
            const fam = getFamilyEstIds(w.establecimiento_id);
            return (appData.trainings || [])
                .filter(t => idEnLista(fam, t.establecimiento_id))
                .filter(t => (t.participantes || []).some(p => pnlMatchesWorker(p, w)))
                .sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));
        }

        function findWorkerPPE(w) {
            const fam = getFamilyEstIds(w.establecimiento_id);
            return (appData.ppe || [])
                .filter(e => idEnLista(fam, e.establecimiento_id))
                .filter(e => pnlMatchesWorker(e.empleado, w))
                .sort((a, b) => String(b.fecha_entrega || '').localeCompare(String(a.fecha_entrega || '')));
        }

        function workerEmployerName(w) {
            if (!w.contratista_id) return 'Personal propio';
            const c = (appData.contractors || []).find(x => x.id === w.contratista_id);
            return c ? c.razon_social : 'Contratista (eliminado)';
        }

        function loadPersonnel() {
            if (!currentEstablishment) return;
            const all = getEstablishmentWorkers();
            const activos = all.filter(w => w.estado !== 'baja');
            document.getElementById('pnlActivos').textContent = activos.length;
            document.getElementById('pnlArtOk').textContent = activos.filter(w => workerArtEstado(w).key === 'vigente' || workerArtEstado(w).key === 'por_vencer').length;
            document.getElementById('pnlArtMal').textContent = activos.filter(w => workerArtEstado(w).key === 'problema').length;
            document.getElementById('pnlMedMal').textContent = activos.filter(w => ['sin', 'no_apto', 'vencido'].indexOf(workerMedEstado(w).key) !== -1).length;

            const q = pnlNorm(document.getElementById('pnlSearch').value);
            const fe = document.getElementById('pnlFilterEstado').value;
            const fa = document.getElementById('pnlFilterArt').value;
            const fi = (document.getElementById('pnlFilterInd') || {}).value || '';
            // filtro por obra: sólo desde la empresa (una obra ya muestra únicamente a su gente)
            const fo = pnlFillObraFilter();
            const list = all
                .filter(w => !fe || w.estado === fe)
                .filter(w => !fo || (fo === '__empresa' ? workerObrasNombres(w).length === 0 : (idEnLista(workerObrasAbiertas(w), fo) || String(w.establecimiento_id) === String(fo))))
                .filter(w => !fa || workerArtEstado(w).key === fa)
                .filter(w => !fi || (fi === 'sin_induccion' ? (w.estado !== 'baja' && workerInductions(w).length === 0) : (w.estado !== 'baja' && workerPendingProtocols(w).length > 0)))
                .filter(w => !q || pnlNorm([w.nombre, w.dni, w.cuil, w.legajo].join(' ')).indexOf(q) !== -1)
                .sort((a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es'));

            const el = document.getElementById('pnlList');
            if (all.length === 0) { el.innerHTML = '<p class="text-gray-500 text-center py-4">No hay personal registrado. Cargá un trabajador o usá "Detectar personal ya cargado".</p>'; return; }
            if (list.length === 0) { el.innerHTML = '<p class="text-gray-500 text-center py-4">Ningún trabajador coincide con el filtro</p>'; return; }

            el.innerHTML = list.map(function (w) {
                const art = workerArtEstado(w), med = workerMedEstado(w);
                const avatar = w.foto
                    ? '<img src="' + w.foto + '" alt="" style="width:48px;height:48px;border-radius:50%;object-fit:cover;flex-shrink:0;">'
                    : '<div style="width:48px;height:48px;border-radius:50%;background:#e0e7ff;color:#4338ca;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0;">' + protoEsc((w.nombre || '?').trim().charAt(0).toUpperCase()) + '</div>';
                const badge = (c, t) => '<span class="px-2 py-0.5 rounded-full text-xs font-semibold bg-' + c + '-100 text-' + c + '-800">' + protoEsc(t) + '</span>';
                return '<div class="border rounded-lg p-3 border-l-4 border-' + art.color + '-500 hover:shadow-md transition">' +
                    '<div class="flex justify-between items-start flex-wrap gap-2">' +
                        '<div class="flex gap-3 flex-1" style="min-width:220px">' + avatar +
                            '<div>' +
                                '<h4 class="font-semibold text-gray-800 text-sm">' + protoEsc(w.nombre) + (w.legajo ? ' <span class="text-xs text-gray-500">Leg. ' + protoEsc(w.legajo) + '</span>' : '') + '</h4>' +
                                '<p class="text-xs text-gray-600">DNI ' + protoEsc(w.dni || '-') + (w.cuil ? ' · CUIL ' + protoEsc(w.cuil) : '') + '</p>' +
                                '<p class="text-xs text-gray-600">' + protoEsc([w.puesto, w.sector].filter(Boolean).join(' · ') || 'Sin puesto') + ' · ' + protoEsc(workerEmployerName(w)) + '</p>' +
                                '<div class="flex gap-1 flex-wrap mt-1">' + badge(art.color, art.label) + badge(med.color, med.label) +
                                    (w.estado !== 'activo' ? badge('gray', PNL_ESTADOS[w.estado] || w.estado) : '') + pnlObraBadges(w) +
                                    (w.estado !== 'baja' && workerInductions(w).length === 0 ? '<button type="button" title="Registrar inducción" onclick="openInductionForm(\'' + w.id + '\')" class="px-2 py-0.5 rounded-full text-xs font-semibold bg-red-100 text-red-800">Sin inducción · registrar</button>' : '') +
                                    ((w.documentos || []).length ? badge('blue', (w.documentos.length) + ' doc.') : '') + '</div>' +
                            '</div>' +
                        '</div>' +
                        '<div class="flex gap-3 items-center text-lg">' +
                            '<button title="Ver ficha completa" onclick="showWorkerDetail(\'' + w.id + '\')" class="text-indigo-600 hover:text-indigo-800"><i class="fas fa-id-card"></i></button>' +
                            '<button title="Registrar inducción" onclick="openInductionForm(\'' + w.id + '\')" class="text-green-600 hover:text-green-800"><i class="fas fa-chalkboard-teacher"></i></button>' +
                            '<button title="Ficha en PDF" onclick="exportWorkerFichaPDF(\'' + w.id + '\')" class="text-blue-600 hover:text-blue-800"><i class="fas fa-file-pdf"></i></button>' +
                            '<button title="Editar" onclick="editWorker(\'' + w.id + '\')" class="text-blue-600 hover:text-blue-800"><i class="fas fa-edit"></i></button>' +
                            signedAttachBtn('worker', w.id) + '<button title="Eliminar" onclick="deleteWorker(\'' + w.id + '\')" class="text-red-600 hover:text-red-800"><i class="fas fa-trash"></i></button>' +
                        '</div>' +
                    '</div>' +
                '</div>';
            }).join('');
            if (openWorkerDetailId) renderWorkerDetail(openWorkerDetailId);
        }

        // Chips con las obras donde trabaja (o "En la empresa" si no tiene ninguna asignada)
        function pnlObraBadges(w) {
            const noms = workerObrasNombres(w);
            const chip = (txt, bg, fg, ic) => '<span class="px-2 py-0.5 rounded-full text-xs font-semibold" style="background:' + bg + ';color:' + fg + ';"><i class="fas ' + ic + '"></i> ' + protoEsc(txt) + '</span>';
            if (!noms.length) return w.contratista_id ? '' : chip('En la empresa', '#e5e7eb', '#374151', 'fa-building');
            return noms.map(n => chip(n, '#fef3c7', '#92400e', 'fa-hard-hat')).join('');
        }
        // Arma el selector "Todas las obras" (sólo visible en una empresa con obras) y devuelve el valor elegido.
        function pnlFillObraFilter() {
            const sel = document.getElementById('pnlFilterObra');
            if (!sel) return '';
            const obras = (currentEstablishment && !esObra(currentEstablishment))
                ? (appData.establishments || []).filter(e => esObra(e) && String(e.empresaPadreId) === String(getOwnerEmpresaId(currentEstablishment))) : [];
            if (!obras.length) { sel.classList.add('hidden'); sel.innerHTML = ''; sel.dataset.sig = ''; return ''; }
            const prev = sel.value;
            const html = '<option value="">Todas las obras</option><option value="__empresa">Sin obra (en la empresa)</option>' +
                obras.map(o => '<option value="' + protoEsc(o.id) + '">' + protoEsc(o.nombre) + '</option>').join('');
            if (sel.dataset.sig !== html) { sel.innerHTML = html; sel.dataset.sig = html; sel.value = obras.some(o => String(o.id) === prev) || prev === '__empresa' ? prev : ''; }
            sel.classList.remove('hidden');
            return sel.value;
        }

        // ---------- alta / edición ----------
        // Casillas "Obras donde trabaja": las obras de la empresa dueña del trabajador.
        function populateWorkerObras(w) {
            const box = document.getElementById('workerObrasBox'), list = document.getElementById('workerObrasList');
            if (!box || !list) return;
            const home = w ? getEstablecimientoPorId(w.establecimiento_id) : currentEstablishment;
            const ownerId = getOwnerEmpresaId(home || currentEstablishment);
            const obras = (appData.establishments || []).filter(e => esObra(e) && String(e.empresaPadreId) === String(ownerId));
            if (!obras.length) { box.classList.add('hidden'); list.innerHTML = ''; return; }
            let marcadas = w ? workerObrasAbiertas(w).map(String) : [];
            if (w && home && esObra(home) && marcadas.indexOf(String(home.id)) === -1) marcadas.push(String(home.id)); // fijo en una obra (dato viejo)
            if (!w && esObra(currentEstablishment)) marcadas = [String(currentEstablishment.id)];                       // alta desde una obra
            list.innerHTML = obras.map(o => '<label class="flex items-center gap-2 text-sm"><input type="checkbox" name="obras_ids" value="' + protoEsc(o.id) + '"' + (marcadas.indexOf(String(o.id)) !== -1 ? ' checked' : '') + '> <i class="fas fa-hard-hat text-yellow-600"></i> ' + protoEsc(o.nombre) + '</label>').join('');
            box.classList.remove('hidden');
            workerContratistaChanged();
        }
        // El personal de un contratista no se comparte entre obras: queda en el establecimiento del contratista.
        function workerContratistaChanged() {
            const c = document.getElementById('workerContratista');
            const list = document.getElementById('workerObrasList');
            if (!c || !list) return;
            const fija = !!c.value;
            list.querySelectorAll('input').forEach(i => { i.disabled = fija; if (fija) i.checked = false; });
            const note = document.getElementById('workerObrasNote');
            if (note) note.textContent = fija ? 'El personal de un contratista queda en este establecimiento y no se asigna a otras obras.' : 'Se carga una sola vez en la empresa y se lo asigna a una o más obras. Cada obra ve solamente a su gente; la empresa ve a todos.';
        }

        function populateWorkerContractors(selected) {
            const sel = document.getElementById('workerContratista');
            const cs = (appData.contractors || []).filter(c => c.establecimiento_id === currentEstablishment.id);
            sel.innerHTML = '<option value="">Personal propio</option>' + cs.map(c => '<option value="' + protoEsc(c.id) + '">' + protoEsc(c.razon_social) + '</option>').join('');
            sel.value = selected || '';
        }

        function resizeImageFile(file, maxPx) {
            return new Promise(function (resolve, reject) {
                const reader = new FileReader();
                reader.onerror = reject;
                reader.onload = function (e) {
                    const img = new Image();
                    img.onerror = reject;
                    img.onload = function () {
                        const scale = Math.min(1, maxPx / Math.max(img.width, img.height));
                        const c = document.createElement('canvas');
                        c.width = Math.max(1, Math.round(img.width * scale));
                        c.height = Math.max(1, Math.round(img.height * scale));
                        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
                        resolve(c.toDataURL('image/jpeg', 0.8));
                    };
                    img.src = e.target.result;
                };
                reader.readAsDataURL(file);
            });
        }

        async function previewWorkerPhoto(input) {
            const f = input.files && input.files[0];
            if (!f) return;
            try {
                workerPhotoData = await resizeImageFile(f, 320);
                document.getElementById('workerPhotoPreview').innerHTML = '<img src="' + workerPhotoData + '" alt="" style="width:96px;height:96px;object-fit:cover;border-radius:50%;">';
            } catch (e) { alert('No se pudo leer la imagen seleccionada'); }
        }

        function showNewWorker() {
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            editingWorkerId = null;
            workerPhotoData = null;
            const form = document.getElementById('workerFormElement');
            form.reset();
            populateWorkerContractors('');
            populateWorkerObras(null);
            document.getElementById('workerPhotoPreview').innerHTML = '';
            document.getElementById('workerFormTitle').innerHTML = '<i class="fas fa-user-plus text-indigo-600"></i> Nuevo trabajador';
            document.getElementById('workerForm').classList.remove('hidden');
            document.getElementById('workerForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function cancelWorkerForm() {
            document.getElementById('workerForm').classList.add('hidden');
            editingWorkerId = null;
            workerPhotoData = null;
        }

        function editWorker(id) {
            const w = (appData.personnel || []).find(x => x.id === id);
            if (!w) return;
            editingWorkerId = id;
            workerPhotoData = null;
            const form = document.getElementById('workerFormElement');
            form.reset();
            populateWorkerContractors(w.contratista_id || '');
            populateWorkerObras(w);
            ['nombre', 'dni', 'cuil', 'legajo', 'puesto', 'sector', 'fecha_ingreso', 'fecha_nacimiento', 'telefono', 'domicilio', 'estado',
             'fecha_baja', 'contacto_emergencia', 'art', 'art_poliza', 'art_desde', 'art_hasta', 'alta_temprana', 'alta_temprana_nro', 'observaciones']
                .forEach(function (n) { const i = form.querySelector('[name="' + n + '"]'); if (i) i.value = w[n] === undefined || w[n] === null ? '' : w[n]; });
            document.getElementById('workerPhotoInput').value = '';
            document.getElementById('workerPhotoPreview').innerHTML = w.foto ? '<img src="' + w.foto + '" alt="" style="width:96px;height:96px;object-fit:cover;border-radius:50%;">' : '';
            document.getElementById('workerFormTitle').innerHTML = '<i class="fas fa-edit text-indigo-600"></i> Editar trabajador';
            document.getElementById('workerForm').classList.remove('hidden');
            document.getElementById('workerForm').scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        async function saveWorker(event) {
            event.preventDefault();
            if (!currentEstablishment) { alert('Seleccione un establecimiento primero'); return; }
            const fd = new FormData(event.target);
            const g = n => String(fd.get(n) || '').trim();
            const dni = pnlDigits(g('dni'));
            // el DNI no se puede repetir en ninguna de las obras de la empresa
            const famSave = getFamilyEstIds(currentEstablishment.id);
            const dup = (appData.personnel || []).some(x => x.id !== editingWorkerId && dni && idEnLista(famSave, x.establecimiento_id) && pnlDigits(x.dni) === dni);
            if (dup && !await appConfirm('Ya existe un trabajador con el DNI ' + g('dni') + '. ¿Guardar de todos modos?')) return;

            const existingW = editingWorkerId ? (appData.personnel || []).find(x => x.id === editingWorkerId) : null;
            const esContratista = !!g('contratista_id');
            // Personal propio: pertenece a la empresa dueña. Personal de contratista: queda en el establecimiento actual.
            const homeW = existingW ? getEstablecimientoPorId(existingW.establecimiento_id) : null;
            const ownerId = esContratista
                ? (existingW && existingW.contratista_id && homeW ? homeW.id : currentEstablishment.id)
                : getOwnerEmpresaId(homeW || currentEstablishment);
            const obrasSel = esContratista ? [] : fd.getAll('obras_ids');

            const data = {
                establecimiento_id: ownerId,
                nombre: g('nombre'), dni: g('dni'), cuil: g('cuil'), legajo: g('legajo'),
                puesto: g('puesto'), sector: g('sector'), fecha_ingreso: g('fecha_ingreso'),
                fecha_nacimiento: g('fecha_nacimiento'), telefono: g('telefono'), domicilio: g('domicilio'),
                estado: g('estado') || 'activo', fecha_baja: g('fecha_baja'), contratista_id: g('contratista_id'),
                contacto_emergencia: g('contacto_emergencia'),
                art: g('art'), art_poliza: g('art_poliza'), art_desde: g('art_desde'), art_hasta: g('art_hasta'),
                alta_temprana: g('alta_temprana'), alta_temprana_nro: g('alta_temprana_nro'),
                observaciones: g('observaciones')
            };
            if (!appData.personnel) appData.personnel = [];
            const existing = editingWorkerId ? appData.personnel.find(x => x.id === editingWorkerId) : null;
            if (existing) {
                Object.assign(existing, data, { modificado: new Date().toISOString() });
                if (workerPhotoData) existing.foto = workerPhotoData;
                asignarTrabajadorAObras(existing, obrasSel);
            } else {
                data.id = 'W' + Date.now();
                data.foto = workerPhotoData || null;
                data.documentos = [];
                data.created_at = new Date().toISOString();
                data.asignaciones = [];
                asignarTrabajadorAObras(data, obrasSel);
                appData.personnel.push(data);
            }
            saveData();
            cancelWorkerForm();
            loadPersonnel();
            alert(existing ? 'Trabajador actualizado' : 'Trabajador registrado');
        }

        async function deleteWorker(id) {
            const w = (appData.personnel || []).find(x => x.id === id);
            if (!w) return;
            if (!await appConfirm('¿Eliminar a ' + w.nombre + ' de la nómina?\n\nSe borran también sus documentos adjuntos e inducciones. Sus exámenes médicos, EPP y capacitaciones se conservan.')) return;
            appData.personnel = appData.personnel.filter(x => x.id !== id);
            appData.inductions = (appData.inductions || []).filter(i => i.worker_id !== id);
            if (openWorkerDetailId === id) closeWorkerDetail();
            saveData();
            loadPersonnel();
        }

