        const NAV_CAT_COLOR = { inicio: '#0891b2', diario: '#2563eb', personal: '#4f46e5', equipos: '#dc2626', riesgos: '#d97706', ambiente: '#0d9488', calidad: '#16a34a', sistema: '#4b5563' };
        const HOME_STORE = 'prohs_home_closed';
        function homeClosed() {
            try { const v = JSON.parse(navStore(HOME_STORE) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; }
        }
        function buildHomeModules() {
            const box = document.getElementById('homeModules');
            if (!box) return;
            // Al abrir la aplicación todas las categorías arrancan contraídas (después se pueden abrir a gusto)
            const closed = NAV_CATS.map(function (c) { return c.id; });
            let html = '<div class="home-cats-bar"><button type="button" class="home-cats-all" onclick="homeToggleAll()"><i class="fas fa-layer-group"></i> <span id="homeAllLabel">Contraer todo</span></button></div>';
            NAV_CATS.forEach(function (c) {
                const items = c.items.filter(function (id) { return id !== 'home'; });
                if (!items.length) return;
                const titulo = c.plana ? 'General' : (c.titulo || NAV_MODULES[items[0]].label);
                const icono = c.plana ? 'fa-th-large' : (c.icono || NAV_MODULES[items[0]].icon);
                const color = NAV_CAT_COLOR[c.id] || '#4b5563';
                const isClosed = closed.indexOf(c.id) !== -1;
                html += '<section class="home-cat' + (isClosed ? ' closed' : '') + '" data-cat="' + c.id + '" style="--cat-color:' + color + ';">' +
                    '<button type="button" class="home-cat-header" aria-expanded="' + (isClosed ? 'false' : 'true') + '" onclick="homeToggleCat(\'' + c.id + '\')">' +
                    '<span class="home-cat-ico"><i class="fas ' + icono + '"></i></span><span class="home-cat-title">' + titulo + '</span>' +
                    '<span class="home-cat-count">' + items.length + (items.length === 1 ? ' módulo' : ' módulos') + '</span>' +
                    '<i class="fas fa-chevron-down home-cat-chevron"></i></button>' +
                    '<div class="home-cat-grid">' + items.map(function (id) {
                        const m = NAV_MODULES[id];
                        return '<div class="module-card home-card" role="button" tabindex="0" data-module="' + id + '" onclick="navGo(\'' + id + '\')">' +
                            '<span class="home-card-ico module-icon"><i class="fas ' + m.icon + '"></i></span>' +
                            '<span class="home-card-txt"><span class="home-card-name">' + m.label + '</span><span class="home-card-desc">' + (NAV_DESC[id] || '') + '</span></span></div>';
                    }).join('') + '</div></section>';
            });
            box.innerHTML = html;
            box.addEventListener('keydown', function (ev) {
                if ((ev.key === 'Enter' || ev.key === ' ') && ev.target.classList && ev.target.classList.contains('home-card')) {
                    ev.preventDefault();
                    ev.target.click();
                }
            });
            homeUpdateAllLabel();
        }
        function homeSaveClosed() {
            homeUpdateAllLabel();
        }
        function homeUpdateAllLabel() {
            const l = document.getElementById('homeAllLabel');
            if (!l) return;
            l.textContent = document.querySelectorAll('#homeModules .home-cat:not(.closed)').length ? 'Contraer todo' : 'Expandir todo';
        }
        function homeToggleCat(id) {
            const s = document.querySelector('#homeModules .home-cat[data-cat="' + id + '"]');
            if (!s) return;
            const c = s.classList.toggle('closed');
            s.querySelector('.home-cat-header').setAttribute('aria-expanded', c ? 'false' : 'true');
            homeSaveClosed();
        }
        function homeToggleAll() {
            const secs = document.querySelectorAll('#homeModules .home-cat');
            const anyOpen = Array.prototype.some.call(secs, function (s) { return !s.classList.contains('closed'); });
            secs.forEach(function (s) {
                s.classList.toggle('closed', anyOpen);
                s.querySelector('.home-cat-header').setAttribute('aria-expanded', anyOpen ? 'false' : 'true');
            });
            homeSaveClosed();
        }
        // Avisos (vencidos / por vencer / sin denunciar) también en el inicio
        function updateHomeAlerts(perMod) {
            const root = document.getElementById('homeModules');
            if (!root) return;
            root.querySelectorAll('.nav-alerts, .nav-alert').forEach(function (n) { n.remove(); });
            NAV_CATS.forEach(function (cat) {
                const tot = { v: 0, p: 0, n: 0 };
                cat.items.forEach(function (id) {
                    const c = perMod[id];
                    if (!c) return;
                    tot.v += c.v; tot.p += c.p; tot.n += (c.n || 0);
                    const card = root.querySelector('.home-card[data-module="' + id + '"]');
                    const html = navPillHtml(c);
                    if (card && html) card.insertAdjacentHTML('beforeend', html);
                });
                const head = root.querySelector('.home-cat[data-cat="' + cat.id + '"] .home-cat-count');
                const html = navPillHtml(tot);
                if (head && html) head.insertAdjacentHTML('afterend', html);
            });
        }

        function buildSidebarNav() {
            const nav = document.getElementById('sidebarNav');
            if (!nav) return;
            let html = '';
            NAV_CATS.forEach(function (c, idx) {
                if (navIsFlat(c)) {
                    html += c.items.map(navItemHtml).join('');
                    if (c.plana) html += '<div class="nav-sep"></div>';
                } else {
                    html += '<div class="nav-cat" data-cat="' + c.id + '">' +
                        '<button type="button" class="nav-cat-header" aria-expanded="false" onclick="navToggleCat(\'' + c.id + '\')">' +
                        '<i class="fas ' + c.icono + ' nav-cat-icon"></i><span class="nav-cat-title">' + c.titulo + '</span>' +
                        '<i class="fas fa-chevron-down nav-cat-chevron"></i></button>' +
                        '<div class="nav-cat-body">' + c.items.map(navItemHtml).join('') + '</div></div>';
                }
            });
            nav.innerHTML = html;
            buildHomeModules();
            nav.addEventListener('keydown', function (ev) {
                if ((ev.key === 'Enter' || ev.key === ' ') && ev.target.classList && ev.target.classList.contains('sidebar-nav-item')) {
                    ev.preventDefault();
                    ev.target.click();
                }
            });
            // Categoría abierta: la última que dejó el usuario ('' = todas cerradas); la primera vez, la de uso diario.
            const saved = navStore('prohs_nav_open');
            const valid = NAV_CATS.filter(function (c) { return !navIsFlat(c); }).map(function (c) { return c.id; });
            NAV.open = saved === null ? 'diario' : (valid.indexOf(saved) !== -1 ? saved : null);
            navApplyOpen();
            NAV.ready = true;
        }
        function navApplyOpen() {
            document.querySelectorAll('.nav-cat').forEach(function (el) {
                const open = el.getAttribute('data-cat') === NAV.open;
                el.classList.toggle('open', open);
                const h = el.querySelector('.nav-cat-header');
                if (h) h.setAttribute('aria-expanded', open ? 'true' : 'false');
            });
        }
        function navToggleCat(id) {
            NAV.open = NAV.open === id ? null : id;
            navApplyOpen();
            navStore('prohs_nav_open', NAV.open || '');
        }
        // Lo llama setActiveSidebarItem: abre la categoría del módulo activo y la marca.
        function navSyncActive(moduleName) {
            const cat = NAV_CAT_OF[moduleName];
            document.querySelectorAll('.nav-cat').forEach(function (el) {
                el.classList.toggle('has-active', !!cat && el.getAttribute('data-cat') === cat.id);
            });
            if (cat && !navIsFlat(cat) && NAV.open !== cat.id) {
                NAV.open = cat.id;
                navApplyOpen();
                navStore('prohs_nav_open', NAV.open);
            }
            // Deja a la vista el ítem activo dentro del menú (cuando termina de desplegarse)
            setTimeout(function () {
                const it = document.querySelector('#sidebarNav .sidebar-nav-item.active');
                if (it && it.scrollIntoView) it.scrollIntoView({ block: 'nearest' });
            }, 300);
        }

        // ============= ATENCIÓN: VENCIMIENTOS Y PENDIENTES (fuente única) =============
        // Un solo criterio para: los números del menú y del inicio, el botón Pendientes, los avisos dentro de cada
        // módulo y las tarjetas de Gestión Documental.  Vencido = fecha anterior a hoy; por vencer = hasta 30 días.
        const ATTN_WARN_DAYS = 30;
        const ATTN_MODS = {
            documents: { label: 'Documento', icon: 'fa-folder-open' }, extinguishers: { label: 'Extintor', icon: 'fa-fire-extinguisher' },
            vehicles: { label: 'Vehículo', icon: 'fa-truck' }, ppe: { label: 'EPP', icon: 'fa-hard-hat' }, sds: { label: 'Químico', icon: 'fa-flask' },
            medical: { label: 'Examen médico', icon: 'fa-heartbeat' }, maintenance: { label: 'Mantenimiento', icon: 'fa-wrench' },
            personnel: { label: 'Seguro ART', icon: 'fa-users' }, protocols: { label: 'Revisión de documento', icon: 'fa-file-signature' },
            actions: { label: 'Acción pendiente', icon: 'fa-tasks' }, machinery: { label: 'Maquinaria', icon: 'fa-cogs' },
            contractors: { label: 'Contratista', icon: 'fa-user-tie' }, incidents: { label: 'Incidente', icon: 'fa-ambulance' },
            ambgest: { label: 'Gestión ambiental', icon: 'fa-leaf' }
        };
        function attnToday() { const d = new Date(); d.setHours(0, 0, 0, 0); return d; }
        function attnDay(s) {
            const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || ''));
            return m ? new Date(+m[1], +m[2] - 1, +m[3]) : null;
        }
        function attnDayStr(s) { const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(s || '')); return m ? m[1] : ''; }
        function attnDays(s) { const d = attnDay(s); return d ? Math.round((d - attnToday()) / 86400000) : null; }
        function attnClass(dias) { if (dias === null || dias === undefined) return null; return dias < 0 ? 'vencido' : (dias <= ATTN_WARN_DAYS ? 'por_vencer' : 'vigente'); }
        function attnPlural(n, s, p) { return n + ' ' + (n === 1 ? s : p); }
        function attnWhen(dias) {
            if (dias === null || dias === undefined) return '';
            if (dias < 0) return 'vencido hace ' + attnPlural(-dias, 'día', 'días');
            if (dias === 0) return 'vence hoy';
            return 'vence en ' + attnPlural(dias, 'día', 'días');
        }
        function attnFmt(s) { const d = attnDayStr(s); return d ? d.split('-').reverse().join('/') : ''; }
