            const dias = attnDays(doc && doc.fecha_vencimiento);
            if (st === 'faltante') return { estado: 'faltante', dias: null };
            if (st === 'en_tramite') return { estado: 'en_tramite', dias: dias };
            if (dias !== null) return { estado: attnClass(dias), dias: dias, };
