        // ---- panel de avisos dentro de cada módulo ----
        const ATTN_BAR_MODS = ['documents', 'extinguishers', 'vehicles', 'ppe', 'sds', 'medical', 'maintenance', 'personnel', 'protocols', 'actions', 'machinery', 'contractors', 'incidents', 'ambgest'];
